export enum UpgradeFeature {
  SEMANTIC_HTML = 'SEMANTIC_HTML',
  TAILWIND_CONVERSION = 'TAILWIND_CONVERSION',
  JS_MODERNIZATION = 'JS_MODERNIZATION',
  PERFORMANCE_OPTIMIZATION = 'PERFORMANCE_OPTIMIZATION',
  ACCESSIBILITY_A11Y = 'ACCESSIBILITY_A11Y'
}

export interface UpgradeOptions {
  features: UpgradeFeature[];
  targetFramework?: string;
}

export interface UpgradeResult {
  upgradedCode: string;
  explanation: string;
  stats: {
    linesAdded: number;
    linesRemoved: number;
    accessibilityScore: number;
    estimatedPerformanceGain: string;
  };
}

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { UpgradeResult, UpgradeOptions, UpgradeFeature } from "../types";

const MODEL_NAME = 'gemini-3-pro-preview';

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  async upgradeHTML(sourceCode: string, options: UpgradeOptions): Promise<UpgradeResult> {
    const featuresList = options.features.map(f => {
      switch(f) {
        case UpgradeFeature.SEMANTIC_HTML: return "Convert structure to HTML5 Semantic elements (<section>, <article>, <aside>, etc.)";
        case UpgradeFeature.TAILWIND_CONVERSION: return "Convert inline/internal CSS to modern Tailwind CSS utility classes";
        case UpgradeFeature.JS_MODERNIZATION: return "Modernize JS to ES6+ (Async/Await, Modules, Classes)";
        case UpgradeFeature.PERFORMANCE_OPTIMIZATION: return "Implement performance patterns like DOM fragments or Web Worker suggestions";
        case UpgradeFeature.ACCESSIBILITY_A11Y: return "Enhance WCAG compliance (ARIA labels, roles)";
        default: return "";
      }
    }).join(", ");

    const systemInstruction = `
      You are a World-Class Senior Web Architect specializing in 2025 standards.
      Your task is to upgrade legacy HTML code to modern, high-performance standards.
      Focus on these improvements: ${featuresList}.

      Requirements for the output:
      1. Use Semantic HTML5 tags correctly.
      2. Use Tailwind CSS for all styling.
      3. Use ES6+ modern JavaScript syntax.
      4. Ensure the output is a complete, valid single-file HTML structure if applicable.
      5. Provide an explanation of changes.
      6. Provide stats on the upgrade.
    `;

    const response = await this.ai.models.generateContent({
      model: MODEL_NAME,
      contents: `Upgrade this HTML code:\n\n${sourceCode}`,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            upgradedCode: { type: Type.STRING },
            explanation: { type: Type.STRING },
            stats: {
              type: Type.OBJECT,
              properties: {
                linesAdded: { type: Type.INTEGER },
                linesRemoved: { type: Type.INTEGER },
                accessibilityScore: { type: Type.INTEGER },
                estimatedPerformanceGain: { type: Type.STRING }
              },
              required: ["linesAdded", "linesRemoved", "accessibilityScore", "estimatedPerformanceGain"]
            }
          },
          required: ["upgradedCode", "explanation", "stats"]
        }
      }
    });

    try {
      return JSON.parse(response.text || '{}') as UpgradeResult;
    } catch (e) {
      throw new Error("Failed to parse AI response. The upgrade was too complex or returned invalid data.");
    }
  }

  async chatAssistant(history: { role: string, content: string }[], message: string, currentCode: string) {
    const response = await this.ai.models.generateContent({
      model: MODEL_NAME,
      contents: [
        { text: `Current Code Context:\n${currentCode}` },
        ...history.map(h => ({ text: `${h.role === 'user' ? 'User' : 'Assistant'}: ${h.content}` })),
        { text: `User Question: ${message}` }
      ],
      config: {
        systemInstruction: "You are an expert web development assistant. Help the user optimize and modify their HTML/CSS/JS code. Keep answers technical and helpful."
      }
    });

    return response.text;
  }
}

export const geminiService = new GeminiService();

