import React, { useState, useCallback } from 'react';
import { Editor } from './components/Editor';
import { geminiService } from './services/geminiService';
import { UpgradeFeature, UpgradeResult, ChatMessage } from './types';
import { 
  Sparkles, 
  Settings2, 
  Terminal, 
  Zap, 
  Layout, 
  Accessibility, 
  Cpu, 
  MessageSquare,
  Play,
