} from 'lucide-react';

const INITIAL_CODE = `<!DOCTYPE html>
<html>
<head>
    <style>
        .container { width: 1000px; margin: 0 auto; }
        .header { background: #333; color: #fff; padding: 20px; }
        .nav { float: left; width: 200px; }
        .content { float: left; width: 800px; }
        .footer { clear: both; background: #eee; padding: 10px; }
    </style>
</head>
<body>
    <div class="container">
        <div class="header"><h1>Legacy Site</h1></div>
        <div class="nav">
            <ul>
                <li><a href="#">Home</a></li>
                <li><a href="#">About</a></li>
            </ul>
        </div>
        <div class="content">
            <p>This is old code that needs upgrading to 2025 standards.</p>
            <div id="chart"></div>
        </div>
        <div class="footer">Copyright 2010</div>
    </div>
    <script>
        function doMath() {
            var x = 10;
            var y = 20;
            alert(x + y);
        }
    </script>
</body>
</html>`;

export default function App() {
  const [sourceCode, setSourceCode] = useState(INITIAL_CODE);
  const [upgradedCode, setUpgradedCode] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [result, setResult] = useState<UpgradeResult | null>(null);
  const [selectedFeatures, setSelectedFeatures] = useState<UpgradeFeature[]>([
    UpgradeFeature.SEMANTIC_HTML,
    UpgradeFeature.TAILWIND_CONVERSION,
    UpgradeFeature.JS_MODERNIZATION
  ]);

  // Chat state
  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);

  const toggleFeature = (feature: UpgradeFeature) => {
    setSelectedFeatures(prev => 
      prev.includes(feature) ? prev.filter(f => f !== feature) : [...prev, feature]
    );
  };

  const handleUpgrade = async () => {
    if (!sourceCode.trim()) return;
    setIsProcessing(true);
    try {
      const upgradeResult = await geminiService.upgradeHTML(sourceCode, { features: selectedFeatures });
      setResult(upgradeResult);
      setUpgradedCode(upgradeResult.upgradedCode);
    } catch (error) {
      console.error(error);
      alert("Upgrade failed. Please check your connection or simplify the input.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleChat = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || isChatLoading) return;

    const userMsg: ChatMessage = { role: 'user', content: chatInput };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatLoading(true);

    try {
      const response = await geminiService.chatAssistant(chatHistory, chatInput, upgradedCode || sourceCode);
      setChatHistory(prev => [...prev, { role: 'assistant', content: response || 'No response from assistant.' }]);
    } catch (error) {
      console.error(error);
      setChatHistory(prev => [...prev, { role: 'assistant', content: 'Sorry, I encountered an error processing your request.' }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#030712] text-gray-200">
      {/* Navbar */}
      <header className="h-16 border-b border-gray-800 bg-[#0d1117]/80 backdrop-blur-md sticky top-0 z-50 px-6 flex items-center justify-between">
