                { id: UpgradeFeature.JS_MODERNIZATION, label: 'ES6+ Engine Refactor', icon: Cpu },
                { id: UpgradeFeature.ACCESSIBILITY_A11Y, label: 'A11Y (WCAG 2.1) Audit', icon: Accessibility },
                { id: UpgradeFeature.PERFORMANCE_OPTIMIZATION, label: 'Turbo Optimization', icon: Zap },
