export enum UpgradeFeature {
  SEMANTIC_HTML = 'SEMANTIC_HTML',
  TAILWIND_CONVERSION = 'TAILWIND_CONVERSION',
  JS_MODERNIZATION = 'JS_MODERNIZATION',
  PERFORMANCE_OPTIMIZATION = 'PERFORMANCE_OPTIMIZATION',
  ACCESSIBILITY_A11Y = 'ACCESSIBILITY_A11Y',
  SECURITY_HARDENING = 'SECURITY_HARDENING',
  SEO_MARKETING = 'SEO_MARKETING',
  OFFLINE_CAPABILITY = 'OFFLINE_CAPABILITY'
}

export interface UpgradeOptions {
  features: UpgradeFeature[];
  autoPilot: boolean;
}

export interface UpgradeResult {
  upgradedCode: string;
  explanation: string;
  automationSummary: string[];
  stats: {
    linesAdded: number;
    linesRemoved: number;
    accessibilityScore: number;
    estimatedPerformanceGain: string;
    securityScore: number;
    seoReady: boolean;
  };
}

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { UpgradeResult, UpgradeOptions, UpgradeFeature } from "../types";

const MODEL_NAME = 'gemini-3-pro-preview';

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  async upgradeHTML(sourceCode: string, options: UpgradeOptions): Promise<UpgradeResult> {
    const checklist = `
      APPLY THE 50-POINT 2025 AUTOMATION CHECKLIST:
      1-10 (Layout): Semantic Tags, Aria Roles, Focus Traps, Skip Links, Color Contrast, Alt Text, Responsive Images, Modern Flexbox, CSS Grid, Tailwind 4.0 Utilities.
      11-20 (Performance): CSS Variables, Dark Mode, Reduced Motion, Font Preloading, Async Scripts, Module Preload, Resource Hints, Service Worker, Manifest.json, Web Workers.
      21-30 (Data): IndexedDB Wrapper, LocalStorage Sync, Error Boundaries, XSS Prevention, Sanitized InnerHTML, JSON-LD, Canonical Tags, OG Tags, Twitter Cards, Viewport Meta.
      31-40 (Modern JS): ES2025 Classes, Private Fields, Top-level Await, Optional Chaining, Proxy States, Custom Events, ResizeObserver, IntersectionObserver, MutationObserver, Web Animations API.
      41-50 (Architecture): CSS Containment, Critical CSS, Print Styles, SVGO optimization, Performance Marks, HSTS headers logic, CSP compliance, Tree-shaking readiness, Minification-friendly structure, 2025 Error Handling.
    `;

    const systemInstruction = `
      You are the "HTML Forge 2025" Automation Engine. 
      Your goal is 100% automation. If Auto-Pilot is ON, ignore specific feature picks and apply ALL 50 optimizations.

      OUTPUT REQUIREMENTS:
      - Upgraded Code: A complete, single-file HTML/CSS/JS solution.
      - Automation Summary: List 10 key professional features applied from the checklist.
      - Stats: Accurate metrics for the upgrade.

      ${options.autoPilot ? checklist : "Focus on: " + options.features.join(", ")}
    `;

    const response = await this.ai.models.generateContent({
      model: MODEL_NAME,
      contents: `Perform 100% Automation Upgrade on this code:\n\n${sourceCode}`,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            upgradedCode: { type: Type.STRING },
            explanation: { type: Type.STRING },
            automationSummary: { type: Type.ARRAY, items: { type: Type.STRING } },
            stats: {
              type: Type.OBJECT,
              properties: {
                linesAdded: { type: Type.INTEGER },
                linesRemoved: { type: Type.INTEGER },
                accessibilityScore: { type: Type.INTEGER },
                estimatedPerformanceGain: { type: Type.STRING },
                securityScore: { type: Type.INTEGER },
                seoReady: { type: Type.BOOLEAN }
              },
              required: ["linesAdded", "linesRemoved", "accessibilityScore", "estimatedPerformanceGain", "securityScore", "seoReady"]
            }
          },
          required: ["upgradedCode", "explanation", "automationSummary", "stats"]
        }
      }
    });

    try {
      return JSON.parse(response.text || '{}') as UpgradeResult;
    } catch (e) {
      throw new Error("Automation Engine encountered a structural complexity error.");
    }
  }

  async chatAssistant(history: { role: string, content: string }[], message: string, currentCode: string) {
    const response = await this.ai.models.generateContent({
      model: MODEL_NAME,
      contents: [
        { text: `Context: 2025 Automation Expert. Code:\n${currentCode}` },
        ...history.map(h => ({ text: `${h.role === 'user' ? 'User' : 'Assistant'}: ${h.content}` })),
        { text: `Request: ${message}` }
      ],
      config: {
        systemInstruction: "You are an Elite 2025 Web Automation Architect. Provide concise, high-impact technical advice."
      }
    });
    return response.text;
  }
}

export const geminiService = new GeminiService();

