    setSelectedFeatures(prev => 
      prev.includes(feature) ? prev.filter(f => f !== feature) : [...prev, feature]
    );
  };

  const handleUpgrade = async () => {
    if (!sourceCode.trim()) return;
    setIsProcessing(true);
    setViewMode('code');
    try {
      const upgradeResult = await geminiService.upgradeHTML(sourceCode, { 
        features: selectedFeatures,
        autoPilot
      });
      setResult(upgradeResult);
      setUpgradedCode(upgradeResult.upgradedCode);
      setViewMode('preview');
    } catch (error) {
      console.error(error);
      alert("Automation Engine Failed. Try reducing code complexity.");
    } finally {
      setIsProcessing(false);
    }
  };

