              >
                Bắt đầu ngay bây giờ
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Dynamic Header */}
      <header className="h-16 border-b border-white/5 bg-slate-900/50 backdrop-blur-xl sticky top-0 z-50 px-6 flex items-center justify-between shadow-2xl">
        <div className="flex items-center gap-3 group">
          <div className="p-2 bg-indigo-500 rounded-lg shadow-lg shadow-indigo-500/20 group-hover:scale-110 transition-transform">
            <Infinity className="w-5 h-5 text-white" />
          </div>
          <div>
