import { GoogleGenAI, Type } from "@google/genai";
import { UpgradeResult, UpgradeOptions, UpgradeFeature } from "../types";

const MODEL_NAME = 'gemini-3-pro-preview';

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  async upgradeHTML(sourceCode: string, options: UpgradeOptions): Promise<UpgradeResult> {
    const checklist = `
      APPLY THE 50-POINT 2025 AUTOMATION CHECKLIST:
      1-5 (Image Assets): AUTO-DETECT base64 (PNG/JPEG/GIF) strings and RE-ENCODE them to high-compression WebP base64 format. Implement <picture> tags for fallback support.
      6-15 (Responsive & Layout): Mobile-first approach. Use Tailwind 4.0 container-queries and breakpoints (sm, md, lg, xl, 2xl). Optimize touch targets for mobile. Use modern CSS Grid with auto-fit/auto-fill.
      16-25 (Performance): CSS Variables, Dark Mode, Reduced Motion, Font Preloading, Async Scripts, Module Preload, Resource Hints, Service Worker, Manifest.json, Web Workers.
      26-35 (Data): IndexedDB Wrapper, LocalStorage Sync, Error Boundaries, XSS Prevention, Sanitized InnerHTML, JSON-LD, Canonical Tags, OG Tags, Twitter Cards, Viewport Meta.
      36-45 (Modern JS): ES2025 Classes, Private Fields, Top-level Await, Optional Chaining, Proxy States, Custom Events, ResizeObserver, IntersectionObserver, MutationObserver, Web Animations API.
      46-50 (Architecture): CSS Containment, Critical CSS, Print Styles, SVGO optimization, Performance Marks, HSTS headers logic, CSP compliance.
    `;

    const systemInstruction = `
      You are the "HTML Forge 2025" Automation Engine. 
      Your goal is 100% automation with a focus on MULTI-DEVICE OPTIMIZATION. 

      CRITICAL TASK: 
      - Convert legacy fixed-width layouts (e.g., 1000px containers) into fluid, responsive Tailwind-based designs.
      - Optimize all images to WebP base64.
      - Ensure the output works perfectly on Mobile, Tablet, and Desktop.
      - Use "Mobile-First" strategy in all CSS/Tailwind classes.

      OUTPUT REQUIREMENTS:
      - Upgraded Code: A complete, single-file HTML/CSS/JS solution.
      - Automation Summary: List 10 key professional features applied, emphasizing Multi-device support.
      - Stats: Accurate metrics for the upgrade.

      ${options.autoPilot ? checklist : "Focus specifically on these features: " + options.features.join(", ") + ". Always include Multi-device and Image Optimization."}
    `;

    const response = await this.ai.models.generateContent({
      model: MODEL_NAME,
      contents: `Perform 100% Multi-Device Automation Upgrade on this code:\n\n${sourceCode}`,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            upgradedCode: { type: Type.STRING },
            explanation: { type: Type.STRING },
            automationSummary: { type: Type.ARRAY, items: { type: Type.STRING } },
            stats: {
              type: Type.OBJECT,
              properties: {
                linesAdded: { type: Type.INTEGER },
                linesRemoved: { type: Type.INTEGER },
                accessibilityScore: { type: Type.INTEGER },
                estimatedPerformanceGain: { type: Type.STRING },
                securityScore: { type: Type.INTEGER },
                seoReady: { type: Type.BOOLEAN }
              },
              required: ["linesAdded", "linesRemoved", "accessibilityScore", "estimatedPerformanceGain", "securityScore", "seoReady"]
            }
          },
          required: ["upgradedCode", "explanation", "automationSummary", "stats"]
        }
      }
    });

    try {
      return JSON.parse(response.text || '{}') as UpgradeResult;
    } catch (e) {
      throw new Error("Automation Engine encountered a structural complexity error.");
    }
  }

  async chatAssistant(history: { role: string, content: string }[], message: string, currentCode: string) {
    const response = await this.ai.models.generateContent({
      model: MODEL_NAME,
      contents: [
        { text: `Context: 2025 Automation Expert. Multi-device responsive design specialist. Code:\n${currentCode}` },
        ...history.map(h => ({ text: `${h.role === 'user' ? 'User' : 'Assistant'}: ${h.content}` })),
        { text: `Request: ${message}` }
      ],
      config: {
        systemInstruction: "You are an Elite 2025 Web Automation Architect. Expert in performance, WebP image conversion, and multi-platform responsive architecture."
      }
    });
    return response.text;
  }
}

