import { GoogleGenAI, Type } from "@google/genai";
import { UpgradeResult, UpgradeOptions, UpgradeFeature } from "../types";

const TEXT_MODEL = 'gemini-3-pro-preview';
const IMAGE_MODEL = 'gemini-3-pro-image-preview';

export class GeminiService {
  // Use process.env.API_KEY directly as per guidelines and create fresh instance
  private getAI() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  async upgradeHTML(sourceCode: string, options: UpgradeOptions): Promise<UpgradeResult> {
    const ai = this.getAI();
    const checklist = `
      APPLY THE 70-POINT 2025 HYPER-AUTOMATION CHECKLIST:
      1-10 (Branding & UX): Professional color theory (oklch), premium typography pairs, micro-interactions, consistent spacing, glassmorphism/bento-grid layouts, custom SVG decorators.
      11-20 (Transitions): View Transitions API, CSS scroll-driven animations, GSAP-like smooth entries, page-load reveals.
      21-30 (SEO & Marketing): High-fidelity JSON-LD (Organization, WebSite, Breadcrumb), Semantic header hierarchy, meta description optimization, social graph tags.
      31-40 (Image Assets): Convert all Base64 to WebP. Placeholder optimization. Responsive srcset.
      41-55 (Responsive): Multi-device breakpoint optimization (sm to 2xl), container queries.
      56-70 (Performance & Security): Web Workers, Proxy State, Content Security Policy, HSTS logic.
    `;

    const systemInstruction = `
      You are the "HTML Forge 2025" Hyper-Automation Engine. 
      Your mission is to transform simple, "boring" HTML into complex, detailed, high-conversion professional websites.

      CRITICAL INSTRUCTIONS:
      - BRANDING: Apply a world-class visual identity. Use professional color palettes and modern UI components.
      - DETAIL: Expand simple sections into detailed ones (e.g., a simple footer becomes a multi-column site-map footer).
      - EFFECTS: Add smooth scroll and entry animations using modern CSS/JS.
      - SEO: Ensure 100% SEO readiness with schema.org integrations.
      - WEBP: Always optimize base64 images.

      OUTPUT: Complete, single-file production-ready HTML/CSS/JS.
    `;

    const response = await ai.models.generateContent({
      model: TEXT_MODEL,
      contents: `Transform this simple input into a complex, professionally branded 2025 experience:\n\n${sourceCode}`,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            upgradedCode: { type: Type.STRING },
            explanation: { type: Type.STRING },
            automationSummary: { type: Type.ARRAY, items: { type: Type.STRING } },
            stats: {
              type: Type.OBJECT,
              properties: {
                linesAdded: { type: Type.INTEGER },
                linesRemoved: { type: Type.INTEGER },
                accessibilityScore: { type: Type.INTEGER },
                estimatedPerformanceGain: { type: Type.STRING },
                securityScore: { type: Type.INTEGER },
                seoReady: { type: Type.BOOLEAN }
              },
              required: ["linesAdded", "linesRemoved", "accessibilityScore", "estimatedPerformanceGain", "securityScore", "seoReady"]
            }
          },
          required: ["upgradedCode", "explanation", "automationSummary", "stats"]
        }
      }
    });

    try {
      // response.text is a getter, do not call as a function
      return JSON.parse(response.text || '{}') as UpgradeResult;
    } catch (e) {
      throw new Error("Complex Reconstruction Error.");
    }
  }

  async generateBrandingImage(prompt: string): Promise<string> {
    const ai = this.getAI(); 
    const response = await ai.models.generateContent({
      model: IMAGE_MODEL,
      contents: {
        parts: [
          { text: `High-quality, professional website asset: ${prompt}. Professional lighting, 2025 web design style, sharp focus.` }
        ]
      },
      config: {
        imageConfig: {
          aspectRatio: "16:9",
          imageSize: "1K"
        }
      }
    });

    // Iterate through all parts to find the image part
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    throw new Error("Image generation failed.");
  }

  async chatAssistant(history: { role: string, content: string }[], message: string, currentCode: string) {
    const ai = this.getAI();
    const response = await ai.models.generateContent({
      model: TEXT_MODEL,
      // Fixed: contents must be a single Content object with a parts array
      contents: {
        parts: [
          { text: `Context: Professional Branding & 2025 Tech. Code:\n${currentCode}` },
          ...history.map(h => ({ text: `${h.role === 'user' ? 'User' : 'Assistant'}: ${h.content}` })),
          { text: `Request: ${message}` }
        ]
      },
      config: {
        systemInstruction: "You are a World-Class Creative Director & Web Architect. Advise on branding, transitions, and SEO."
      }
    });
    // Access response.text property directly
    return response.text;
  }
}

export const geminiService = new GeminiService();

