import { GoogleGenAI, Type } from "@google/genai";
import { UpgradeResult, UpgradeOptions, UpgradeFeature } from "../types";

const TEXT_MODEL = 'gemini-3-pro-preview';
const IMAGE_MODEL = 'gemini-3-pro-image-preview';

export class GeminiService {
  private getAI() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  async upgradeHTML(sourceCode: string, options: UpgradeOptions): Promise<UpgradeResult> {
    const ai = this.getAI();
    const checklist = `
      APPLY THE 70-POINT 2025 HYPER-AUTOMATION CHECKLIST:
      1-10 (Branding & UX): Professional color theory (oklch), premium typography pairs, micro-interactions, glassmorphism.
      11-20 (Transitions): View Transitions API, smooth entries.
      21-30 (SEO & Marketing): High-fidelity JSON-LD, meta optimization.
      31-40 (Visual Integration): CRITICAL: If a section (Hero, Features, About) needs a high-quality visual, insert a placeholder exactly like this: {{AI_IMAGE_PROMPT: "A detailed description for an AI image generator"}}. 
      Do not use external URLs. The system will replace these placeholders with real AI-generated images.
      41-70 (Technical): Web Workers, Tailwind 4.0, Semantic Tags, Modern JS.
    `;

    const systemInstruction = `
      You are the "HTML Forge 2025" Hyper-Automation Engine. 
      Your mission: Transform simple HTML into a detailed, professionally branded 2025 experience.

      CRITICAL INSTRUCTIONS:
      - BRANDING: Apply a world-class visual identity.
      - IMAGES: Whenever the design requires a professional image (Hero banner, feature card, product photo), insert the placeholder: {{AI_IMAGE_PROMPT: "Description"}}. 
      - SEO: Include full schema.org JSON-LD.
      - TAILWIND: Use only Tailwind classes for styling.

      OUTPUT: Complete, single-file production-ready HTML/CSS/JS in JSON format.
    `;

    const response = await ai.models.generateContent({
      model: TEXT_MODEL,
      contents: `Transform this simple input into a complex, professionally branded 2025 experience. Add image placeholders for branding:\n\n${sourceCode}`,
      config: {
        systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            upgradedCode: { type: Type.STRING },
            explanation: { type: Type.STRING },
            automationSummary: { type: Type.ARRAY, items: { type: Type.STRING } },
            stats: {
              type: Type.OBJECT,
              properties: {
                linesAdded: { type: Type.INTEGER },
                linesRemoved: { type: Type.INTEGER },
                accessibilityScore: { type: Type.INTEGER },
                estimatedPerformanceGain: { type: Type.STRING },
                securityScore: { type: Type.INTEGER },
                seoReady: { type: Type.BOOLEAN }
              },
              required: ["linesAdded", "linesRemoved", "accessibilityScore", "estimatedPerformanceGain", "securityScore", "seoReady"]
            }
          },
          required: ["upgradedCode", "explanation", "automationSummary", "stats"]
        }
      }
    });

    try {
      return JSON.parse(response.text || '{}') as UpgradeResult;
    } catch (e) {
      throw new Error("Complex Reconstruction Error.");
    }
  }

  async generateBrandingImage(prompt: string): Promise<string> {
    const ai = this.getAI(); 
    const response = await ai.models.generateContent({
      model: IMAGE_MODEL,
      contents: {
        parts: [
          { text: `Professional website asset: ${prompt}. High resolution, 8k, modern 2025 aesthetic, commercial photography style.` }
        ]
      },
      config: {
        imageConfig: {
          aspectRatio: "16:9",
          imageSize: "1K"
        }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/webp;base64,${part.inlineData.data}`;
      }
    }
    throw new Error("Image generation failed.");
  }

  async chatAssistant(history: { role: string, content: string }[], message: string, currentCode: string) {
    const ai = this.getAI();
    const response = await ai.models.generateContent({
      model: TEXT_MODEL,
      contents: {
        parts: [
          { text: `Context: Professional Branding & 2025 Tech. Code:\n${currentCode}` },
          ...history.map(h => ({ text: `${h.role === 'user' ? 'User' : 'Assistant'}: ${h.content}` })),
          { text: `Request: ${message}` }
        ]
      },
      config: {
        systemInstruction: "You are a World-Class Creative Director & Web Architect. Advise on branding, transitions, and SEO."
      }
    });
    return response.text;
  }
}

export const geminiService = new GeminiService();

