  Activity,
  Image as ImageIcon,
  HelpCircle,
  X,
  Rocket,
  MousePointer2,
  Smartphone,
  Tablet as TabletIcon,
  Monitor,
  Menu,
  ChevronLeft,
  ChevronRight,
  Palette,
  Wind,
  Search,
  Key,
  Images
} from 'lucide-react';

const INITIAL_CODE = `<!DOCTYPE html>
<html>
<body>
    <h1>Premium Coffee Roasters</h1>
    <p>We source the finest beans from around the world.</p>
    <button>Shop Collection</button>
</body>
</html>`;

type DeviceType = 'mobile' | 'tablet' | 'desktop';

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }

  interface Window {
    readonly aistudio: AIStudio;
  }
}

export default function App() {
  const [sourceCode, setSourceCode] = useState(INITIAL_CODE);
  const [upgradedCode, setUpgradedCode] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStage, setProcessingStage] = useState<'text' | 'images' | 'idle'>('idle');
  const [result, setResult] = useState<UpgradeResult | null>(null);
  const [viewMode, setViewMode] = useState<'code' | 'preview'>('code');
  const [autoPilot, setAutoPilot] = useState(true);
  const [showHelp, setShowHelp] = useState(true);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [previewDevice, setPreviewDevice] = useState<DeviceType>('desktop');
  const [imagePrompt, setImagePrompt] = useState('');
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [generatedImages, setGeneratedImages] = useState<GeneratedImage[]>([]);
  const [selectedFeatures, setSelectedFeatures] = useState<UpgradeFeature[]>([
    UpgradeFeature.SEMANTIC_HTML,
    UpgradeFeature.TAILWIND_CONVERSION,
    UpgradeFeature.IMAGE_OPTIMIZATION,
    UpgradeFeature.BRANDING_DESIGN,
    UpgradeFeature.PAGE_EFFECTS
  ]);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);

  const toggleFeature = (feature: UpgradeFeature) => {
    setSelectedFeatures(prev => 
      prev.includes(feature) ? prev.filter(f => f !== feature) : [...prev, feature]
    );
  };

  const processImagePlaceholders = async (code: string): Promise<string> => {
    const placeholderRegex = /\{\{AI_IMAGE_PROMPT:\s*["'](.+?)["']\s*\}\}/g;
    let finalCode = code;
    const matches = Array.from(code.matchAll(placeholderRegex));

    if (matches.length > 0) {
      setProcessingStage('images');
      // Ensure API key is selected for Image Gen
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) await window.aistudio.openSelectKey();

      for (const match of matches) {
        const fullPlaceholder = match[0];
        const prompt = match[1];
        try {
          const base64 = await geminiService.generateBrandingImage(prompt);
          finalCode = finalCode.replace(fullPlaceholder, `<img src="${base64}" alt="${prompt}" class="w-full h-full object-cover rounded-2xl shadow-2xl" loading="lazy" />`);
        } catch (e) {
          console.error("Failed to generate asset for:", prompt, e);
          finalCode = finalCode.replace(fullPlaceholder, `<div class="w-full aspect-video bg-slate-900 flex items-center justify-center text-slate-700 text-[10px] uppercase font-bold border border-white/5 rounded-2xl italic">Visual Asset Pending: ${prompt}</div>`);
        }
      }
    }
    return finalCode;
  };

  const handleUpgrade = async () => {
    if (!sourceCode.trim()) return;
    setIsProcessing(true);
    setProcessingStage('text');
    setViewMode('code');
    try {
      // 1. Generate text structure
      const upgradeResult = await geminiService.upgradeHTML(sourceCode, { 
        features: selectedFeatures,
        autoPilot
      });

      // 2. Process image placeholders automatically
      const finalCode = await processImagePlaceholders(upgradeResult.upgradedCode);

      setResult(upgradeResult);
      setUpgradedCode(finalCode);
      setViewMode('preview');
    } catch (error) {
      console.error(error);
      alert("Automation Engine Failed.");
    } finally {
      setIsProcessing(false);
      setProcessingStage('idle');
    }
  };

  const handleGenerateImage = async () => {
    if (!imagePrompt.trim()) return;
    setIsGeneratingImage(true);
    try {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) await window.aistudio.openSelectKey();
      const imageUrl = await geminiService.generateBrandingImage(imagePrompt);
      setGeneratedImages(prev => [...prev, { url: imageUrl, prompt: imagePrompt }]);
      setImagePrompt('');
    } catch (error: any) {
      if (error.message?.includes("entity was not found")) {
        await window.aistudio.openSelectKey();
      } else {
        alert("Lỗi tạo hình ảnh: " + error.message);
      }
    } finally {
      setIsGeneratingImage(false);
    }
  };

  const handleChat = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || isChatLoading) return;
    const userMsg: ChatMessage = { role: 'user', content: chatInput };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatLoading(true);
    try {
      const response = await geminiService.chatAssistant(chatHistory, chatInput, upgradedCode || sourceCode);
      setChatHistory(prev => [...prev, { role: 'assistant', content: response || 'Architect busy...' }]);
    } catch (error) {
      setChatHistory(prev => [...prev, { role: 'assistant', content: 'Lỗi kết nối.' }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  const openInNewTab = () => {
    const blob = new Blob([upgradedCode], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    window.open(url, '_blank');
  };

  const getPreviewWidth = () => {
    switch(previewDevice) {
      case 'mobile': return '375px';
      case 'tablet': return '768px';
      default: return '100%';
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 selection:bg-indigo-500/30 overflow-hidden">
      {/* Help Modal */}
      {showHelp && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6 bg-slate-950/80 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="max-w-4xl w-full bg-[#0b0f1a] border border-white/10 rounded-3xl shadow-2xl overflow-hidden relative max-h-[90vh] overflow-y-auto">
            <button onClick={() => setShowHelp(false)} className="absolute top-6 right-6 p-2 text-slate-500 hover:text-white transition-colors z-10"><X className="w-6 h-6" /></button>
            <div className="p-8 sm:p-12">
              <div className="flex items-center gap-4 mb-8">
                <div className="p-3 bg-indigo-600 rounded-2xl"><Rocket className="w-8 h-8 text-white" /></div>
                <div>
                  <h2 className="text-2xl sm:text-3xl font-black tracking-tight text-white">Forge OS: 100% Visual Automation</h2>
                  <p className="text-slate-400 font-medium text-sm sm:text-base">Tự động hóa toàn bộ quy trình từ code đến hình ảnh thương hiệu.</p>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 mb-10">
                <div className="p-6 bg-white/5 rounded-2xl border border-white/5 group">
                  <div className="w-10 h-10 bg-indigo-500/10 rounded-xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform"><Images className="w-5 h-5 text-indigo-400" /></div>
                  <h4 className="font-bold text-white mb-2 uppercase text-xs tracking-widest">Tự Động Chèn Ảnh AI</h4>
                  <p className="text-[11px] text-slate-500 leading-relaxed">AI tự nhận diện vị trí cần ảnh và gọi Gemini Image Engine để chèn ảnh thực tế vào code.</p>
                </div>
                <div className="p-6 bg-white/5 rounded-2xl border border-white/5 group">
                  <div className="w-10 h-10 bg-emerald-500/10 rounded-xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform"><Palette className="w-5 h-5 text-emerald-400" /></div>
                  <h4 className="font-bold text-white mb-2 uppercase text-xs tracking-widest">Branding Độc Bản</h4>
                  <p className="text-[11px] text-slate-500 leading-relaxed">Không dùng ảnh stock. Mọi hình ảnh được tạo mới hoàn toàn khớp với nội dung của bạn.</p>
                </div>
                <div className="p-6 bg-white/5 rounded-2xl border border-white/5 group">
                  <div className="w-10 h-10 bg-blue-500/10 rounded-xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform"><Smartphone className="w-5 h-5 text-blue-400" /></div>
                  <h4 className="font-bold text-white mb-2 uppercase text-xs tracking-widest">Hiển Thị Đa Nền Tảng</h4>
                  <p className="text-[11px] text-slate-500 leading-relaxed">Hình ảnh được tối ưu WebP, tự động co giãn theo mọi kích thước màn hình.</p>
                </div>
              </div>

              <button onClick={() => setShowHelp(false)} className="w-full py-4 bg-white text-slate-950 rounded-2xl font-black uppercase tracking-widest hover:bg-slate-200 transition-all shadow-xl active:scale-[0.98]">Trải nghiệm ngay</button>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <header className="h-16 border-b border-white/5 bg-slate-900/50 backdrop-blur-xl sticky top-0 z-50 px-4 sm:px-6 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 text-slate-400 hover:text-white sm:hidden"><Menu className="w-6 h-6" /></button>
          <div className="hidden sm:flex items-center gap-3">
            <div className="p-2 bg-indigo-500 rounded-lg shadow-lg shadow-indigo-500/20"><Infinity className="w-5 h-5 text-white" /></div>
            <div>
              <h1 className="text-lg font-black tracking-tighter text-white leading-none">FORGE <span className="text-indigo-400">OS</span></h1>
              <div className="flex items-center gap-1 text-[8px] font-bold text-slate-500 uppercase tracking-widest mt-1"><Activity className="w-2 h-2 text-emerald-500" /> Hyper-Visual v5</div>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-3 sm:gap-6">
          <button onClick={handleUpgrade} disabled={isProcessing} className="flex items-center gap-2 px-4 sm:px-8 py-2 bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 disabled:opacity-50 text-white rounded-full font-black transition-all text-xs sm:text-sm shadow-xl shadow-indigo-500/20 active:scale-95">
            {isProcessing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
            <span>NÂNG CẤP TỰ ĐỘNG (FULL ASSETS)</span>
          </button>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden flex-col sm:flex-row">
        {/* Sidebar */}
        <aside className={`${sidebarOpen ? 'w-full sm:w-80' : 'w-0 sm:w-0'} border-r border-white/5 bg-[#0b0f1a] flex flex-col gap-6 overflow-y-auto transition-all duration-300 relative group/sidebar shrink-0`}>
          <button onClick={() => setSidebarOpen(!sidebarOpen)} className="absolute -right-3 top-1/2 -translate-y-1/2 w-6 h-12 bg-[#0b0f1a] border border-white/10 rounded-full hidden sm:flex items-center justify-center text-slate-500 hover:text-white z-20 transition-all opacity-0 group-hover/sidebar:opacity-100">
            {sidebarOpen ? <ChevronLeft className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
          </button>

          <div className={`${!sidebarOpen && 'hidden'} p-6 space-y-6 pb-20`}>
            {/* AI Image Generation Section */}
            <div className="p-4 rounded-2xl bg-emerald-500/5 border border-emerald-500/20 space-y-3 shadow-inner">
              <h4 className="text-[10px] font-black text-emerald-400 uppercase tracking-widest flex items-center gap-2">
                <ImageIcon className="w-3.5 h-3.5" /> Thư viện tài nguyên AI
              </h4>
              <p className="text-[9px] text-slate-500 leading-relaxed italic">Các hình ảnh được AI tự động tạo cho web sẽ hiển thị ở đây.</p>

              {generatedImages.length > 0 && (
                <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto">
                  {generatedImages.map((img, i) => (
                    <div key={i} className="group relative rounded-lg overflow-hidden border border-white/10 aspect-video">
                      <img src={img.url} alt={img.prompt} className="w-full h-full object-cover" />
                      <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                        <Download className="w-4 h-4 text-white" />
                      </div>
                    </div>
                  ))}
                </div>
              )}

              <div className="flex flex-col gap-2 pt-2 border-t border-white/5">
                <textarea 
                  value={imagePrompt}
                  onChange={(e) => setImagePrompt(e.target.value)}
                  placeholder="Mô tả ảnh muốn tạo thêm..."
                  className="w-full bg-slate-950 border border-white/10 rounded-lg px-3 py-2 text-[10px] outline-none h-16 resize-none focus:border-emerald-500"
                />
                <button 
                  onClick={handleGenerateImage}
                  disabled={isGeneratingImage || !imagePrompt}
                  className="w-full py-2 bg-slate-800 hover:bg-slate-700 disabled:opacity-50 text-white rounded-lg font-bold text-[10px] transition-all flex items-center justify-center gap-2"
                >
                  {isGeneratingImage ? <Loader2 className="w-3 h-3 animate-spin" /> : <Play className="w-3 h-3" />}
                  TẠO THỦ CÔNG
                </button>
              </div>
            </div>

            {/* Audit Status */}
            {result && (
              <div className="space-y-4 animate-in slide-in-from-left-2 duration-300">
                <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2"><CheckCircle2 className="w-3 h-3 text-emerald-500" /> Báo cáo tổng hợp</h3>
                <div className="grid grid-cols-2 gap-2">
                  {[
                    { label: 'Asset AI', val: 'Đã Nhúng', color: 'text-emerald-400' },
                    { label: 'Branding', val: 'Premium', color: 'text-purple-400' },
                    { label: 'SEO', val: 'Full Index', color: 'text-blue-400' },
                    { label: 'Speed', val: 'Hyper', color: 'text-amber-400' },
                  ].map((stat, i) => (
                    <div key={i} className="p-3 bg-white/5 rounded-xl border border-white/5">
                      <div className={`text-xs font-black ${stat.color}`}>{stat.val}</div>
                      <div className="text-[8px] text-slate-500 font-bold uppercase">{stat.label}</div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="bg-slate-900/50 rounded-2xl border border-white/5 overflow-hidden flex flex-col min-h-[200px]">
              <div className="p-3 border-b border-white/5 flex items-center gap-2 bg-slate-900/80"><MessageSquare className="w-3 h-3 text-indigo-400" /><span className="text-[10px] font-black text-slate-300 tracking-widest uppercase">Consultant Console</span></div>
              <div className="flex-1 overflow-y-auto p-4 space-y-3 text-[11px] h-32">
                {chatHistory.length === 0 && <p className="text-slate-600 italic font-medium">Hệ thống đang sẵn sàng...</p>}
                {chatHistory.map((msg, i) => (
                  <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                    <div className={`max-w-[90%] p-2 rounded-xl ${msg.role === 'user' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'bg-slate-800 text-slate-300'}`}>{msg.content}</div>
                  </div>
                ))}
              </div>
              <form onSubmit={handleChat} className="p-2 border-t border-white/5 flex gap-2 bg-slate-900/50">
                <input value={chatInput} onChange={(e) => setChatInput(e.target.value)} placeholder="Yêu cầu cụ thể..." className="flex-1 bg-slate-950 border border-white/10 rounded-lg px-3 py-1. text-[10px] outline-none" />
                <button className="p-1.5 bg-indigo-600 rounded-lg text-white hover:bg-indigo-500"><Play className="w-3 h-3 fill-current" /></button>
              </form>
            </div>
          </div>
        </aside>

        {/* Workspace */}
        <section className="flex-1 p-4 sm:p-6 grid grid-cols-1 lg:grid-cols-2 gap-6 overflow-y-auto sm:overflow-hidden bg-[#020617]">
          <div className="flex flex-col gap-4 h-[400px] sm:h-full min-h-[300px]">
            <Editor title="Buffer Nguồn" value={sourceCode} onChange={setSourceCode} />
          </div>

          <div className="flex flex-col gap-4 relative h-full min-h-[400px]">
            <div className="flex-1 flex flex-col bg-[#0b0f1a] rounded-3xl border border-white/5 overflow-hidden shadow-2xl">
              <div className="flex flex-col sm:flex-row items-center justify-between px-4 py-3 bg-[#131929] border-b border-white/5 gap-3">
                <div className="flex items-center gap-2 bg-slate-950/50 p-1 rounded-lg border border-white/10 w-full sm:w-auto">
                  <button onClick={() => setViewMode('code')} className={`flex-1 sm:flex-none flex items-center justify-center gap-2 px-4 py-1.5 text-[10px] font-black rounded-md transition-all ${viewMode === 'code' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-500'}`}><Code2 className="w-3.5 h-3.5" /> CODE</button>
                  <button onClick={() => setViewMode('preview')} className={`flex-1 sm:flex-none flex items-center justify-center gap-2 px-4 py-1.5 text-[10px] font-black rounded-md transition-all ${viewMode === 'preview' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-500'}`}><Eye className="w-3.5 h-3.5" /> LIVE PREVIEW</button>
                </div>

                {viewMode === 'preview' && (
                  <div className="flex items-center gap-2 bg-slate-950/50 p-1 rounded-lg border border-white/10">
                    <button onClick={() => setPreviewDevice('mobile')} className={`p-1.5 rounded transition-all ${previewDevice === 'mobile' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-500 hover:text-white'}`}><Smartphone className="w-3.5 h-3.5" /></button>
                    <button onClick={() => setPreviewDevice('tablet')} className={`p-1.5 rounded transition-all ${previewDevice === 'tablet' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-500 hover:text-white'}`}><TabletIcon className="w-3.5 h-3.5" /></button>
                    <button onClick={() => setPreviewDevice('desktop')} className={`p-1.5 rounded transition-all ${previewDevice === 'desktop' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-500 hover:text-white'}`}><Monitor className="w-3.5 h-3.5" /></button>
                  </div>
                )}
              </div>

              <div className="flex-1 relative overflow-hidden bg-[#0b0f1a] flex justify-center items-start pt-4 px-4 pb-4">
                {viewMode === 'code' ? (
                  <textarea value={upgradedCode} readOnly className="w-full h-full bg-transparent p-6 text-slate-300 code-font text-xs sm:text-sm outline-none resize-none leading-relaxed" placeholder="Code sẽ xuất hiện sau khi AI phân tích..." />
                ) : (
                  <div style={{ width: getPreviewWidth() }} className="h-full bg-white transition-all duration-500 shadow-2xl rounded-sm overflow-hidden flex flex-col relative">
                    {upgradedCode ? (
                      <iframe title="Live View" srcDoc={upgradedCode} className="w-full h-full border-none" sandbox="allow-scripts allow-forms" />
                    ) : (
                      <div className="w-full h-full flex flex-col items-center justify-center bg-[#0b0f1a] text-slate-700 text-center p-8">
                        <Images className="w-16 h-16 mb-4 opacity-10" />
                        <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-30">Phòng lab thiết kế sáng tạo</p>
                      </div>
                    )}
                  </div>
                )}

                {isProcessing && (
                  <div className="absolute inset-0 bg-slate-950/90 backdrop-blur-md z-30 flex flex-col items-center justify-center p-8 text-center animate-in fade-in duration-300">
                    <div className="relative mb-8">
                      <div className="w-24 h-24 border-2 border-indigo-500/10 rounded-full animate-ping"></div>
                      <div className="absolute inset-0 w-24 h-24 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
                      <div className="absolute inset-0 m-auto w-10 h-10 flex items-center justify-center">
                        {processingStage === 'text' ? <Code2 className="w-8 h-8 text-indigo-500 animate-pulse" /> : <ImageIcon className="w-8 h-8 text-emerald-500 animate-pulse" />}
                      </div>
                    </div>
                    <h4 className="text-2xl font-black text-white mb-2 tracking-tighter uppercase">
                      {processingStage === 'text' ? 'Đang tái cấu trúc Code...' : 'Đang thiết kế Asset AI...'}
                    </h4>
                    <p className="text-slate-500 text-xs max-w-xs leading-relaxed font-medium italic">
                      {processingStage === 'text' 
                        ? 'Xây dựng layout bento-grid và hệ thống typography chuyên nghiệp...' 
                        : 'Gemini Image Engine đang tạo các hình ảnh 1K độc bản cho branding của bạn...'}
                    </p>
                    <div className="mt-8 flex gap-1.5">
                      <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                      <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                      <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce"></div>
                    </div>
                  </div>
                )}
              </div>
            </div>

            {upgradedCode && !isProcessing && (
              <div className="absolute bottom-10 right-10 z-40 flex flex-col gap-3 items-end">
                <button 
                  onClick={() => window.aistudio.openSelectKey()}
                  className="p-3 bg-slate-800 text-slate-300 hover:text-white rounded-full shadow-2xl border border-white/10 transition-all group active:scale-90"
                  title="Cài đặt API Key"
                >
                  <Key className="w-4 h-4 group-hover:rotate-12" />
                </button>
                <button onClick={() => {
                  const blob = new Blob([upgradedCode], { type: 'text/html' });
                  const url = URL.createObjectURL(blob);
                  const a = document.createElement('a');
                  a.href = url;
                  a.download = 'branding_visual_build.html';
                  a.click();
                }} className="flex items-center gap-2 p-4 bg-white text-slate-950 rounded-2xl font-black shadow-2xl hover:scale-105 active:scale-95 transition-all text-xs uppercase tracking-tighter border-none">
                  <Download className="w-4 h-4" /> Export build
                </button>
              </div>
            )}
          </div>
        </section>
      </main>

      <footer className="h-8 sm:h-10 border-t border-white/5 bg-slate-950 flex items-center justify-between px-4 sm:px-6">
        <div className="flex items-center gap-4 text-[8px] sm:text-[9px] text-slate-600 font-black uppercase tracking-widest">
           <span className="flex items-center gap-1.5"><div className="w-1.5 h-1.5 bg-indigo-500 rounded-full"></div> Forge Engine v5.0</span>
           <span className="hidden sm:inline">Visual Automation: Online</span>
        </div>
        <div className="text-[8px] sm:text-[9px] text-slate-700 font-bold tracking-widest">FORGE OS 2025 // FULL ASSET RECONSTRUCTION</div>
      </footer>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Editor } from './components/Editor';
import { geminiService } from './services/geminiService';
import { UpgradeFeature, UpgradeResult, ChatMessage, GeneratedImage } from './types';
import { 
  Sparkles, 
  Settings2, 
  Terminal, 
  Zap, 
  Layout, 
  Accessibility, 
  Cpu, 
  MessageSquare,
  Play,
  RotateCcw,
  Download,
  CheckCircle2,
  AlertCircle,
  Loader2,
  Eye,
  Code2,
  ExternalLink,
  ShieldCheck,
  Globe,
  Infinity,
  Layers,
  Activity,
  Image as ImageIcon,
  HelpCircle,
  X,
  Rocket,
  MousePointer2,
  Smartphone,
  Tablet as TabletIcon,
  Monitor,
  Menu,
  ChevronLeft,
  ChevronRight,
  Palette,
  Wind,
  Search,
  Key,
  Images
} from 'lucide-react';

const INITIAL_CODE = `<!DOCTYPE html>
<html>
<body>
    <h1>Premium Coffee Roasters</h1>
    <p>We source the finest beans from around the world.</p>
    <button>Shop Collection</button>
</body>
</html>`;

type DeviceType = 'mobile' | 'tablet' | 'desktop';

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }

  interface Window {
    // Removed readonly to match environment modifiers
    aistudio: AIStudio;
  }
}

export default function App() {
  const [sourceCode, setSourceCode] = useState(INITIAL_CODE);
  const [upgradedCode, setUpgradedCode] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStage, setProcessingStage] = useState<'text' | 'images' | 'idle'>('idle');
  const [result, setResult] = useState<UpgradeResult | null>(null);
  const [viewMode, setViewMode] = useState<'code' | 'preview'>('code');
  const [autoPilot, setAutoPilot] = useState(true);
  const [showHelp, setShowHelp] = useState(true);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [previewDevice, setPreviewDevice] = useState<DeviceType>('desktop');
  const [imagePrompt, setImagePrompt] = useState('');
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [generatedImages, setGeneratedImages] = useState<GeneratedImage[]>([]);
  const [selectedFeatures, setSelectedFeatures] = useState<UpgradeFeature[]>([
    UpgradeFeature.SEMANTIC_HTML,
    UpgradeFeature.TAILWIND_CONVERSION,
    UpgradeFeature.IMAGE_OPTIMIZATION,
    UpgradeFeature.BRANDING_DESIGN,
    UpgradeFeature.PAGE_EFFECTS
  ]);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);

  const toggleFeature = (feature: UpgradeFeature) => {
    setSelectedFeatures(prev => 
      prev.includes(feature) ? prev.filter(f => f !== feature) : [...prev, feature]
    );
  };

  const processImagePlaceholders = async (code: string): Promise<string> => {
    const placeholderRegex = /\{\{AI_IMAGE_PROMPT:\s*["'](.+?)["']\s*\}\}/g;
    let finalCode = code;
    const matches = Array.from(code.matchAll(placeholderRegex));

    if (matches.length > 0) {
      setProcessingStage('images');
      // Ensure API key is selected for Image Gen
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) await window.aistudio.openSelectKey();

      for (const match of matches) {
        const fullPlaceholder = match[0];
        const prompt = match[1];
        try {
          const base64 = await geminiService.generateBrandingImage(prompt);
          finalCode = finalCode.replace(fullPlaceholder, `<img src="${base64}" alt="${prompt}" class="w-full h-full object-cover rounded-2xl shadow-2xl" loading="lazy" />`);
        } catch (e) {
          console.error("Failed to generate asset for:", prompt, e);
          finalCode = finalCode.replace(fullPlaceholder, `<div class="w-full aspect-video bg-slate-900 flex items-center justify-center text-slate-700 text-[10px] uppercase font-bold border border-white/5 rounded-2xl italic">Visual Asset Pending: ${prompt}</div>`);
        }
      }
    }
    return finalCode;
  };

  const handleUpgrade = async () => {
    if (!sourceCode.trim()) return;
    setIsProcessing(true);
    setProcessingStage('text');
    setViewMode('code');
    try {
      // 1. Generate text structure
      const upgradeResult = await geminiService.upgradeHTML(sourceCode, { 
        features: selectedFeatures,
        autoPilot
      });

      // 2. Process image placeholders automatically
      const finalCode = await processImagePlaceholders(upgradeResult.upgradedCode);

      setResult(upgradeResult);
      setUpgradedCode(finalCode);
      setViewMode('preview');
    } catch (error) {
      console.error(error);
      alert("Automation Engine Failed.");
    } finally {
      setIsProcessing(false);
      setProcessingStage('idle');
    }
  };

  const handleGenerateImage = async () => {
    if (!imagePrompt.trim()) return;
    setIsGeneratingImage(true);
    try {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) await window.aistudio.openSelectKey();
      const imageUrl = await geminiService.generateBrandingImage(imagePrompt);
      setGeneratedImages(prev => [...prev, { url: imageUrl, prompt: imagePrompt }]);
      setImagePrompt('');
    } catch (error: any) {
      if (error.message?.includes("entity was not found")) {
        await window.aistudio.openSelectKey();
      } else {
        alert("Lỗi tạo hình ảnh: " + error.message);
      }
    } finally {
      setIsGeneratingImage(false);
    }
  };

  const handleChat = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || isChatLoading) return;
    const userMsg: ChatMessage = { role: 'user', content: chatInput };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatLoading(true);
    try {
      const response = await geminiService.chatAssistant(chatHistory, chatInput, upgradedCode || sourceCode);
      setChatHistory(prev => [...prev, { role: 'assistant', content: response || 'Architect busy...' }]);
    } catch (error) {
      setChatHistory(prev => [...prev, { role: 'assistant', content: 'Lỗi kết nối.' }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  const openInNewTab = () => {
    const blob = new Blob([upgradedCode], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    window.open(url, '_blank');
  };

  const getPreviewWidth = () => {
    switch(previewDevice) {
      case 'mobile': return '375px';
      case 'tablet': return '768px';
      default: return '100%';
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 selection:bg-indigo-500/30 overflow-hidden">
      {/* Help Modal */}
      {showHelp && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6 bg-slate-950/80 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="max-w-4xl w-full bg-[#0b0f1a] border border-white/10 rounded-3xl shadow-2xl overflow-hidden relative max-h-[90vh] overflow-y-auto">
            <button onClick={() => setShowHelp(false)} className="absolute top-6 right-6 p-2 text-slate-500 hover:text-white transition-colors z-10"><X className="w-6 h-6" /></button>
            <div className="p-8 sm:p-12">
              <div className="flex items-center gap-4 mb-8">
                <div className="p-3 bg-indigo-600 rounded-2xl"><Rocket className="w-8 h-8 text-white" /></div>
                <div>
                  <h2 className="text-2xl sm:text-3xl font-black tracking-tight text-white">Forge OS: 100% Visual Automation</h2>
                  <p className="text-slate-400 font-medium text-sm sm:text-base">Tự động hóa toàn bộ quy trình từ code đến hình ảnh thương hiệu.</p>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 mb-10">
                <div className="p-6 bg-white/5 rounded-2xl border border-white/5 group">
                  <div className="w-10 h-10 bg-indigo-500/10 rounded-xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform"><Images className="w-5 h-5 text-indigo-400" /></div>
                  <h4 className="font-bold text-white mb-2 uppercase text-xs tracking-widest">Tự Động Chèn Ảnh AI</h4>
                  <p className="text-[11px] text-slate-500 leading-relaxed">AI tự nhận diện vị trí cần ảnh và gọi Gemini Image Engine để chèn ảnh thực tế vào code.</p>
                </div>
                <div className="p-6 bg-white/5 rounded-2xl border border-white/5 group">
                  <div className="w-10 h-10 bg-emerald-500/10 rounded-xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform"><Palette className="w-5 h-5 text-emerald-400" /></div>
                  <h4 className="font-bold text-white mb-2 uppercase text-xs tracking-widest">Branding Độc Bản</h4>
                  <p className="text-[11px] text-slate-500 leading-relaxed">Không dùng ảnh stock. Mọi hình ảnh được tạo mới hoàn toàn khớp với nội dung của bạn.</p>
                </div>
                <div className="p-6 bg-white/5 rounded-2xl border border-white/5 group">
                  <div className="w-10 h-10 bg-blue-500/10 rounded-xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform"><Smartphone className="w-5 h-5 text-blue-400" /></div>
                  <h4 className="font-bold text-white mb-2 uppercase text-xs tracking-widest">Hiển Thị Đa Nền Tảng</h4>
                  <p className="text-[11px] text-slate-500 leading-relaxed">Hình ảnh được tối ưu WebP, tự động co giãn theo mọi kích thước màn hình.</p>
                </div>
              </div>

              <button onClick={() => setShowHelp(false)} className="w-full py-4 bg-white text-slate-950 rounded-2xl font-black uppercase tracking-widest hover:bg-slate-200 transition-all shadow-xl active:scale-[0.98]">Trải nghiệm ngay</button>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <header className="h-16 border-b border-white/5 bg-slate-900/50 backdrop-blur-xl sticky top-0 z-50 px-4 sm:px-6 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 text-slate-400 hover:text-white sm:hidden"><Menu className="w-6 h-6" /></button>
          <div className="hidden sm:flex items-center gap-3">
            <div className="p-2 bg-indigo-500 rounded-lg shadow-lg shadow-indigo-500/20"><Infinity className="w-5 h-5 text-white" /></div>
            <div>
              <h1 className="text-lg font-black tracking-tighter text-white leading-none">FORGE <span className="text-indigo-400">OS</span></h1>
              <div className="flex items-center gap-1 text-[8px] font-bold text-slate-500 uppercase tracking-widest mt-1"><Activity className="w-2 h-2 text-emerald-500" /> Hyper-Visual v5</div>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-3 sm:gap-6">
          <button onClick={handleUpgrade} disabled={isProcessing} className="flex items-center gap-2 px-4 sm:px-8 py-2 bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 disabled:opacity-50 text-white rounded-full font-black transition-all text-xs sm:text-sm shadow-xl shadow-indigo-500/20 active:scale-95">
            {isProcessing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
            <span>NÂNG CẤP TỰ ĐỘNG (FULL ASSETS)</span>
          </button>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden flex-col sm:flex-row">
        {/* Sidebar */}
        <aside className={`${sidebarOpen ? 'w-full sm:w-80' : 'w-0 sm:w-0'} border-r border-white/5 bg-[#0b0f1a] flex flex-col gap-6 overflow-y-auto transition-all duration-300 relative group/sidebar shrink-0`}>
          <button onClick={() => setSidebarOpen(!sidebarOpen)} className="absolute -right-3 top-1/2 -translate-y-1/2 w-6 h-12 bg-[#0b0f1a] border border-white/10 rounded-full hidden sm:flex items-center justify-center text-slate-500 hover:text-white z-20 transition-all opacity-0 group-hover/sidebar:opacity-100">
            {sidebarOpen ? <ChevronLeft className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
          </button>

          <div className={`${!sidebarOpen && 'hidden'} p-6 space-y-6 pb-20`}>
            {/* AI Image Generation Section */}
            <div className="p-4 rounded-2xl bg-emerald-500/5 border border-emerald-500/20 space-y-3 shadow-inner">
              <h4 className="text-[10px] font-black text-emerald-400 uppercase tracking-widest flex items-center gap-2">
                <ImageIcon className="w-3.5 h-3.5" /> Thư viện tài nguyên AI
              </h4>
              <p className="text-[9px] text-slate-500 leading-relaxed italic">Các hình ảnh được AI tự động tạo for web sẽ hiển thị ở đây.</p>

              {generatedImages.length > 0 && (
                <div className="grid grid-cols-2 gap-2 max-h-40 overflow-y-auto">
                  {generatedImages.map((img, i) => (
                    <div key={i} className="group relative rounded-lg overflow-hidden border border-white/10 aspect-video">
                      <img src={img.url} alt={img.prompt} className="w-full h-full object-cover" />
                      <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                        <Download className="w-4 h-4 text-white" />
                      </div>
                    </div>
                  ))}
                </div>
              )}

              <div className="flex flex-col gap-2 pt-2 border-t border-white/5">
                <textarea 
                  value={imagePrompt}
                  onChange={(e) => setImagePrompt(e.target.value)}
                  placeholder="Mô tả ảnh muốn tạo thêm..."
                  className="w-full bg-slate-950 border border-white/10 rounded-lg px-3 py-2 text-[10px] outline-none h-16 resize-none focus:border-emerald-500"
                />
                <button 
                  onClick={handleGenerateImage}
                  disabled={isGeneratingImage || !imagePrompt}
                  className="w-full py-2 bg-slate-800 hover:bg-slate-700 disabled:opacity-50 text-white rounded-lg font-bold text-[10px] transition-all flex items-center justify-center gap-2"
                >
                  {isGeneratingImage ? <Loader2 className="w-3 h-3 animate-spin" /> : <Play className="w-3 h-3" />}
                  TẠO THỦ CÔNG
                </button>
              </div>
            </div>

            {/* Audit Status */}
            {result && (
              <div className="space-y-4 animate-in slide-in-from-left-2 duration-300">
                <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2"><CheckCircle2 className="w-3 h-3 text-emerald-500" /> Báo cáo tổng hợp</h3>
                <div className="grid grid-cols-2 gap-2">
                  {[
                    { label: 'Asset AI', val: 'Đã Nhúng', color: 'text-emerald-400' },
                    { label: 'Branding', val: 'Premium', color: 'text-purple-400' },
                    { label: 'SEO', val: 'Full Index', color: 'text-blue-400' },
                    { label: 'Speed', val: 'Hyper', color: 'text-amber-400' },
                  ].map((stat, i) => (
                    <div key={i} className="p-3 bg-white/5 rounded-xl border border-white/5">
                      <div className={`text-xs font-black ${stat.color}`}>{stat.val}</div>
                      <div className="text-[8px] text-slate-500 font-bold uppercase">{stat.label}</div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="bg-slate-900/50 rounded-2xl border border-white/5 overflow-hidden flex flex-col min-h-[200px]">
              <div className="p-3 border-b border-white/5 flex items-center gap-2 bg-slate-900/80"><MessageSquare className="w-3 h-3 text-indigo-400" /><span className="text-[10px] font-black text-slate-300 tracking-widest uppercase">Consultant Console</span></div>
              <div className="flex-1 overflow-y-auto p-4 space-y-3 text-[11px] h-32">
                {chatHistory.length === 0 && <p className="text-slate-600 italic font-medium">Hệ thống đang sẵn sàng...</p>}
                {chatHistory.map((msg, i) => (
                  <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                    <div className={`max-w-[90%] p-2 rounded-xl ${msg.role === 'user' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'bg-slate-800 text-slate-300'}`}>{msg.content}</div>
                  </div>
                ))}
              </div>
              <form onSubmit={handleChat} className="p-2 border-t border-white/5 flex gap-2 bg-slate-900/50">
                <input value={chatInput} onChange={(e) => setChatInput(e.target.value)} placeholder="Yêu cầu cụ thể..." className="flex-1 bg-slate-950 border border-white/10 rounded-lg px-3 py-1. text-[10px] outline-none" />
                <button className="p-1.5 bg-indigo-600 rounded-lg text-white hover:bg-indigo-500"><Play className="w-3 h-3 fill-current" /></button>
              </form>
            </div>
          </div>
        </aside>

        {/* Workspace */}
        <section className="flex-1 p-4 sm:p-6 grid grid-cols-1 lg:grid-cols-2 gap-6 overflow-y-auto sm:overflow-hidden bg-[#020617]">
          <div className="flex flex-col gap-4 h-[400px] sm:h-full min-h-[300px]">
            <Editor title="Buffer Nguồn" value={sourceCode} onChange={setSourceCode} />
          </div>

          <div className="flex flex-col gap-4 relative h-full min-h-[400px]">
            <div className="flex-1 flex flex-col bg-[#0b0f1a] rounded-3xl border border-white/5 overflow-hidden shadow-2xl">
              <div className="flex flex-col sm:flex-row items-center justify-between px-4 py-3 bg-[#131929] border-b border-white/5 gap-3">
                <div className="flex items-center gap-2 bg-slate-950/50 p-1 rounded-lg border border-white/10 w-full sm:w-auto">
                  <button onClick={() => setViewMode('code')} className={`flex-1 sm:flex-none flex items-center justify-center gap-2 px-4 py-1.5 text-[10px] font-black rounded-md transition-all ${viewMode === 'code' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-500'}`}><Code2 className="w-3.5 h-3.5" /> CODE</button>
                  <button onClick={() => setViewMode('preview')} className={`flex-1 sm:flex-none flex items-center justify-center gap-2 px-4 py-1.5 text-[10px] font-black rounded-md transition-all ${viewMode === 'preview' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-500'}`}><Eye className="w-3.5 h-3.5" /> LIVE PREVIEW</button>
                </div>

                {viewMode === 'preview' && (
                  <div className="flex items-center gap-2 bg-slate-950/50 p-1 rounded-lg border border-white/10">
                    <button onClick={() => setPreviewDevice('mobile')} className={`p-1.5 rounded transition-all ${previewDevice === 'mobile' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-500 hover:text-white'}`}><Smartphone className="w-3.5 h-3.5" /></button>
                    <button onClick={() => setPreviewDevice('tablet')} className={`p-1.5 rounded transition-all ${previewDevice === 'tablet' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-500 hover:text-white'}`}><TabletIcon className="w-3.5 h-3.5" /></button>
                    <button onClick={() => setPreviewDevice('desktop')} className={`p-1.5 rounded transition-all ${previewDevice === 'desktop' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-500 hover:text-white'}`}><Monitor className="w-3.5 h-3.5" /></button>
                  </div>
                )}
              </div>

              <div className="flex-1 relative overflow-hidden bg-[#0b0f1a] flex justify-center items-start pt-4 px-4 pb-4">
                {viewMode === 'code' ? (
                  <textarea value={upgradedCode} readOnly className="w-full h-full bg-transparent p-6 text-slate-300 code-font text-xs sm:text-sm outline-none resize-none leading-relaxed" placeholder="Code sẽ xuất hiện sau khi AI phân tích..." />
                ) : (
                  <div style={{ width: getPreviewWidth() }} className="h-full bg-white transition-all duration-500 shadow-2xl rounded-sm overflow-hidden flex flex-col relative">
                    {upgradedCode ? (
                      <iframe title="Live View" srcDoc={upgradedCode} className="w-full h-full border-none" sandbox="allow-scripts allow-forms" />
                    ) : (
                      <div className="w-full h-full flex flex-col items-center justify-center bg-[#0b0f1a] text-slate-700 text-center p-8">
                        <Images className="w-16 h-16 mb-4 opacity-10" />
                        <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-30">Phòng lab thiết kế sáng tạo</p>
                      </div>
                    )}
                  </div>
                )}

                {isProcessing && (
                  <div className="absolute inset-0 bg-slate-950/90 backdrop-blur-md z-30 flex flex-col items-center justify-center p-8 text-center animate-in fade-in duration-300">
                    <div className="relative mb-8">
                      <div className="w-24 h-24 border-2 border-indigo-500/10 rounded-full animate-ping"></div>
                      <div className="absolute inset-0 w-24 h-24 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
                      <div className="absolute inset-0 m-auto w-10 h-10 flex items-center justify-center">
                        {processingStage === 'text' ? <Code2 className="w-8 h-8 text-indigo-500 animate-pulse" /> : <ImageIcon className="w-8 h-8 text-emerald-500 animate-pulse" />}
                      </div>
                    </div>
                    <h4 className="text-2xl font-black text-white mb-2 tracking-tighter uppercase">
                      {processingStage === 'text' ? 'Đang tái cấu trúc Code...' : 'Đang thiết kế Asset AI...'}
                    </h4>
                    <p className="text-slate-500 text-xs max-w-xs leading-relaxed font-medium italic">
                      {processingStage === 'text' 
                        ? 'Xây dựng layout bento-grid và hệ thống typography chuyên nghiệp...' 
                        : 'Gemini Image Engine đang tạo các hình ảnh 1K độc bản for branding của bạn...'}
                    </p>
                    <div className="mt-8 flex gap-1.5">
                      <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                      <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                      <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce"></div>
                    </div>
                  </div>
                )}
              </div>
            </div>

            {upgradedCode && !isProcessing && (
              <div className="absolute bottom-10 right-10 z-40 flex flex-col gap-3 items-end">
                <button 
                  onClick={() => window.aistudio.openSelectKey()}
                  className="p-3 bg-slate-800 text-slate-300 hover:text-white rounded-full shadow-2xl border border-white/10 transition-all group active:scale-90"
                  title="Cài đặt API Key"
                >
                  <Key className="w-4 h-4 group-hover:rotate-12" />
                </button>
                <button onClick={() => {
                  const blob = new Blob([upgradedCode], { type: 'text/html' });
                  const url = URL.createObjectURL(blob);
                  const a = document.createElement('a');
                  a.href = url;
                  a.download = 'branding_visual_build.html';
                  a.click();
                }} className="flex items-center gap-2 p-4 bg-white text-slate-950 rounded-2xl font-black shadow-2xl hover:scale-105 active:scale-95 transition-all text-xs uppercase tracking-tighter border-none">
                  <Download className="w-4 h-4" /> Export build
                </button>
              </div>
            )}
          </div>
        </section>
      </main>

      <footer className="h-8 sm:h-10 border-t border-white/5 bg-slate-950 flex items-center justify-between px-4 sm:px-6">
        <div className="flex items-center gap-4 text-[8px] sm:text-[9px] text-slate-600 font-black uppercase tracking-widest">
           <span className="flex items-center gap-1.5"><div className="w-1.5 h-1.5 bg-indigo-500 rounded-full"></div> Forge Engine v5.0</span>
           <span className="hidden sm:inline">Visual Automation: Online</span>
        </div>
        <div className="text-[8px] sm:text-[9px] text-slate-700 font-bold tracking-widest">FORGE OS 2025 // FULL ASSET RECONSTRUCTION</div>
      </footer>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Editor } from './components/Editor';
import { geminiService } from './services/geminiService';
import { UpgradeFeature, UpgradeResult, ChatMessage, GeneratedImage } from './types';
import { 
  Sparkles, 
  Settings2, 
  Terminal, 
  Zap, 
  Layout, 
  Accessibility, 
  Cpu, 
  MessageSquare,
  Play,
  RotateCcw,
  Download,
  CheckCircle2,
  AlertCircle,
  Loader2,
  Eye,
  Code2,
  ExternalLink,
  ShieldCheck,
  Globe,
  Infinity,
  Layers,
  Activity,
  Image as ImageIcon,
  HelpCircle,
  X,
  Rocket,
  MousePointer2,
  Smartphone,
  Tablet as TabletIcon,
  Monitor,
  Menu,
  ChevronLeft,
  ChevronRight,
  Palette,
  Wind,
  Search,
  Key,
  Images
} from 'lucide-react';

const INITIAL_CODE = `<!DOCTYPE html>
<html>
<body>
    <h1>Premium Coffee Roasters</h1>
    <p>We source the finest beans from around the world.</p>
    <button>Shop Collection</button>
</body>
</html>`;

type DeviceType = 'mobile' | 'tablet' | 'desktop';

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }

  interface Window {
    aistudio: AIStudio;
  }
}

export default function App() {
  const [sourceCode, setSourceCode] = useState(INITIAL_CODE);
  const [upgradedCode, setUpgradedCode] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStage, setProcessingStage] = useState<'text' | 'images' | 'idle'>('idle');
  const [result, setResult] = useState<UpgradeResult | null>(null);
  const [viewMode, setViewMode] = useState<'code' | 'preview'>('code');
  const [autoPilot, setAutoPilot] = useState(true);
  const [showHelp, setShowHelp] = useState(true);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [previewDevice, setPreviewDevice] = useState<DeviceType>('desktop');
  const [imagePrompt, setImagePrompt] = useState('');
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [generatedImages, setGeneratedImages] = useState<GeneratedImage[]>([]);
  const [selectedFeatures, setSelectedFeatures] = useState<UpgradeFeature[]>([
    UpgradeFeature.SEMANTIC_HTML,
    UpgradeFeature.TAILWIND_CONVERSION,
    UpgradeFeature.IMAGE_OPTIMIZATION,
    UpgradeFeature.BRANDING_DESIGN,
    UpgradeFeature.PAGE_EFFECTS
  ]);

  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);

  const toggleFeature = (feature: UpgradeFeature) => {
    setSelectedFeatures(prev => 
      prev.includes(feature) ? prev.filter(f => f !== feature) : [...prev, feature]
    );
  };

  const processImagePlaceholders = async (code: string): Promise<string> => {
    const placeholderRegex = /\{\{AI_IMAGE_PROMPT:\s*["'](.+?)["']\s*\}\}/g;
    let finalCode = code;
    const matches = Array.from(code.matchAll(placeholderRegex));

    if (matches.length > 0) {
      setProcessingStage('images');
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) await window.aistudio.openSelectKey();

      // Clear old images for new build if in autopilot
      if (autoPilot) setGeneratedImages([]);

      for (const match of matches) {
        const fullPlaceholder = match[0];
        const prompt = match[1];
        try {
          const base64 = await geminiService.generateBrandingImage(prompt);

          // Add to global gallery
          setGeneratedImages(prev => [...prev, { url: base64, prompt: prompt }]);

          // Replace in code with professional styles
          finalCode = finalCode.replace(fullPlaceholder, `<img src="${base64}" alt="${prompt}" class="w-full h-full object-cover rounded-2xl shadow-2xl transition-all hover:scale-105 duration-700" loading="lazy" />`);
        } catch (e) {
          console.error("Failed to generate asset for:", prompt, e);
          finalCode = finalCode.replace(fullPlaceholder, `<div class="w-full aspect-video bg-slate-900 flex items-center justify-center text-slate-700 text-[10px] uppercase font-bold border border-white/5 rounded-2xl italic">Visual Asset Pending: ${prompt}</div>`);
        }
      }
    }
    return finalCode;
  };

  const handleUpgrade = async () => {
    if (!sourceCode.trim()) return;
    setIsProcessing(true);
    setProcessingStage('text');
    setViewMode('code');
    try {
      // 1. Generate text structure with branding and SEO logic
      const upgradeResult = await geminiService.upgradeHTML(sourceCode, { 
        features: selectedFeatures,
        autoPilot
      });

      // 2. Process image placeholders and sync with visual library
      const finalCode = await processImagePlaceholders(upgradeResult.upgradedCode);

      setResult(upgradeResult);
      setUpgradedCode(finalCode);
      setViewMode('preview');
    } catch (error) {
      console.error(error);
      alert("Automation Engine Failed.");
    } finally {
      setIsProcessing(false);
      setProcessingStage('idle');
    }
  };

  const handleGenerateImage = async () => {
    if (!imagePrompt.trim()) return;
    setIsGeneratingImage(true);
    try {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      if (!hasKey) await window.aistudio.openSelectKey();
      const imageUrl = await geminiService.generateBrandingImage(imagePrompt);
      setGeneratedImages(prev => [...prev, { url: imageUrl, prompt: imagePrompt }]);
      setImagePrompt('');
    } catch (error: any) {
      if (error.message?.includes("entity was not found")) {
        await window.aistudio.openSelectKey();
      } else {
        alert("Lỗi tạo hình ảnh: " + error.message);
      }
    } finally {
      setIsGeneratingImage(false);
    }
  };

  const handleChat = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || isChatLoading) return;
    const userMsg: ChatMessage = { role: 'user', content: chatInput };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatLoading(true);
    try {
      const response = await geminiService.chatAssistant(chatHistory, chatInput, upgradedCode || sourceCode);
      setChatHistory(prev => [...prev, { role: 'assistant', content: response || 'Architect busy...' }]);
    } catch (error) {
      setChatHistory(prev => [...prev, { role: 'assistant', content: 'Lỗi kết nối.' }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  const openInNewTab = () => {
    const blob = new Blob([upgradedCode], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    window.open(url, '_blank');
  };

  const getPreviewWidth = () => {
    switch(previewDevice) {
      case 'mobile': return '375px';
      case 'tablet': return '768px';
      default: return '100%';
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 selection:bg-indigo-500/30 overflow-hidden">
      {/* Help Modal */}
      {showHelp && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6 bg-slate-950/80 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="max-w-4xl w-full bg-[#0b0f1a] border border-white/10 rounded-3xl shadow-2xl overflow-hidden relative max-h-[90vh] overflow-y-auto">
            <button onClick={() => setShowHelp(false)} className="absolute top-6 right-6 p-2 text-slate-500 hover:text-white transition-colors z-10"><X className="w-6 h-6" /></button>
            <div className="p-8 sm:p-12">
              <div className="flex items-center gap-4 mb-8">
                <div className="p-3 bg-indigo-600 rounded-2xl"><Rocket className="w-8 h-8 text-white" /></div>
                <div>
                  <h2 className="text-2xl sm:text-3xl font-black tracking-tight text-white">Forge OS: Visual Multi-Sync</h2>
                  <p className="text-slate-400 font-medium text-sm sm:text-base">Hệ thống đồng bộ hóa mã nguồn và hình ảnh AI tự động 2025.</p>
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 mb-10">
                <div className="p-6 bg-white/5 rounded-2xl border border-white/5 group hover:border-indigo-500/30 transition-all">
                  <div className="w-10 h-10 bg-indigo-500/10 rounded-xl flex items-center justify-center mb-4"><Images className="w-5 h-5 text-indigo-400" /></div>
                  <h4 className="font-bold text-white mb-2 uppercase text-xs tracking-widest">Visual Sync 100%</h4>
                  <p className="text-[11px] text-slate-500 leading-relaxed">Hình ảnh được tạo tự động sẽ xuất hiện đồng thời trong cả mã nguồn và thư viện tài nguyên.</p>
                </div>
                <div className="p-6 bg-white/5 rounded-2xl border border-white/5 group hover:border-emerald-500/30 transition-all">
                  <div className="w-10 h-10 bg-emerald-500/10 rounded-xl flex items-center justify-center mb-4"><Palette className="w-5 h-5 text-emerald-400" /></div>
                  <h4 className="font-bold text-white mb-2 uppercase text-xs tracking-widest">Auto-Branding</h4>
                  <p className="text-[11px] text-slate-500 leading-relaxed">AI tự chọn phong cách hình ảnh phù hợp với ngành nghề kinh doanh của bạn.</p>
                </div>
                <div className="p-6 bg-white/5 rounded-2xl border border-white/5 group hover:border-blue-500/30 transition-all">
                  <div className="w-10 h-10 bg-blue-500/10 rounded-xl flex items-center justify-center mb-4"><Zap className="w-5 h-5 text-blue-400" /></div>
                  <h4 className="font-bold text-white mb-2 uppercase text-xs tracking-widest">Speed & Security</h4>
                  <p className="text-[11px] text-slate-500 leading-relaxed">Ảnh WebP nén cao, đảm bảo tốc độ tải trang dưới 1 giây và chuẩn bảo mật CSP.</p>
                </div>
              </div>

              <button onClick={() => setShowHelp(false)} className="w-full py-4 bg-white text-slate-950 rounded-2xl font-black uppercase tracking-widest hover:bg-slate-200 transition-all shadow-xl active:scale-[0.98]">Kích hoạt Pilot</button>
            </div>
          </div>
        </div>
      )}

      {/* Header */}
      <header className="h-16 border-b border-white/5 bg-slate-900/50 backdrop-blur-xl sticky top-0 z-50 px-4 sm:px-6 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 text-slate-400 hover:text-white sm:hidden"><Menu className="w-6 h-6" /></button>
          <div className="hidden sm:flex items-center gap-3">
            <div className="p-2 bg-indigo-500 rounded-lg shadow-lg shadow-indigo-500/20 animate-pulse"><Infinity className="w-5 h-5 text-white" /></div>
            <div>
              <h1 className="text-lg font-black tracking-tighter text-white leading-none">FORGE <span className="text-indigo-400">OS</span></h1>
              <div className="flex items-center gap-1 text-[8px] font-bold text-slate-500 uppercase tracking-widest mt-1"><Activity className="w-2 h-2 text-emerald-500" /> Multi-Sync Active</div>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-3 sm:gap-6">
          <button onClick={handleUpgrade} disabled={isProcessing} className="flex items-center gap-2 px-4 sm:px-8 py-2 bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-500 hover:to-purple-500 disabled:opacity-50 text-white rounded-full font-black transition-all text-xs sm:text-sm shadow-xl shadow-indigo-500/20 active:scale-95">
            {isProcessing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
            <span>{isProcessing ? 'SYNCHRONIZING...' : 'CHẠY AUTO-PILOT (ĐỒNG BỘ ẢNH)'}</span>
          </button>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden flex-col sm:flex-row">
        {/* Sidebar */}
        <aside className={`${sidebarOpen ? 'w-full sm:w-80' : 'w-0 sm:w-0'} border-r border-white/5 bg-[#0b0f1a] flex flex-col gap-6 overflow-y-auto transition-all duration-300 relative group/sidebar shrink-0 shadow-2xl z-20`}>
          <button onClick={() => setSidebarOpen(!sidebarOpen)} className="absolute -right-3 top-1/2 -translate-y-1/2 w-6 h-12 bg-[#0b0f1a] border border-white/10 rounded-full hidden sm:flex items-center justify-center text-slate-500 hover:text-white z-20 transition-all opacity-0 group-hover/sidebar:opacity-100">
            {sidebarOpen ? <ChevronLeft className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
          </button>

          <div className={`${!sidebarOpen && 'hidden'} p-6 space-y-6 pb-20`}>
            {/* Visual Assets Library (The Sync Target) */}
            <div className="p-4 rounded-2xl bg-indigo-500/5 border border-indigo-500/20 space-y-3 shadow-inner">
              <div className="flex items-center justify-between">
                <h4 className="text-[10px] font-black text-indigo-400 uppercase tracking-widest flex items-center gap-2">
                  <Images className="w-3.5 h-3.5" /> Thư viện Tài nguyên
                </h4>
                <span className="text-[9px] font-bold text-indigo-500/50 bg-indigo-500/5 px-2 py-0.5 rounded-full">{generatedImages.length} ASSETS</span>
              </div>

              {generatedImages.length > 0 ? (
                <div className="grid grid-cols-2 gap-2 max-h-56 overflow-y-auto pr-1 custom-scrollbar">
                  {generatedImages.map((img, i) => (
                    <div key={i} className="group relative rounded-lg overflow-hidden border border-white/10 aspect-square bg-slate-900 animate-in zoom-in-95 duration-500">
                      <img src={img.url} alt={img.prompt} className="w-full h-full object-cover transition-transform group-hover:scale-110" />
                      <div className="absolute inset-0 bg-indigo-600/60 opacity-0 group-hover:opacity-100 flex flex-col items-center justify-center gap-1 transition-all p-2 text-center">
                        <button 
                          onClick={() => {
                            const a = document.createElement('a');
                            a.href = img.url;
                            a.download = `forge_asset_${i}.webp`;
                            a.click();
                          }}
                          className="p-1.5 bg-white text-indigo-600 rounded-full shadow-lg"
                        >
                          <Download className="w-3 h-3" />
                        </button>
                        <span className="text-[7px] text-white font-bold leading-tight line-clamp-2 uppercase">{img.prompt}</span>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="h-24 border border-dashed border-white/5 rounded-xl flex flex-col items-center justify-center text-slate-600 gap-2 opacity-50">
                   <ImageIcon className="w-6 h-6" />
                   <span className="text-[8px] font-bold uppercase tracking-widest">Chưa có tài nguyên</span>
                </div>
              )}

              <div className="flex flex-col gap-2 pt-3 border-t border-white/5">
                <textarea 
                  value={imagePrompt}
                  onChange={(e) => setImagePrompt(e.target.value)}
                  placeholder="Yêu cầu tạo thêm ảnh..."
                  className="w-full bg-slate-950 border border-white/10 rounded-lg px-3 py-2 text-[10px] outline-none h-14 resize-none focus:border-indigo-500 transition-all placeholder:text-slate-800"
                />
                <button 
                  onClick={handleGenerateImage}
                  disabled={isGeneratingImage || !imagePrompt}
                  className="w-full py-2 bg-slate-800 hover:bg-slate-700 disabled:opacity-50 text-white rounded-lg font-bold text-[10px] transition-all flex items-center justify-center gap-2"
                >
                  {isGeneratingImage ? <Loader2 className="w-3 h-3 animate-spin" /> : <Play className="w-3 h-3" />}
                  TẠO THỦ CÔNG
                </button>
              </div>
            </div>

            {/* Audit Status */}
            {result && (
              <div className="space-y-4 animate-in slide-in-from-left-2 duration-300">
                <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2"><CheckCircle2 className="w-3 h-3 text-emerald-500" /> Trạng thái Nâng cấp</h3>
                <div className="grid grid-cols-2 gap-2">
                  {[
                    { label: 'Asset AI', val: 'Đã Đồng Bộ', color: 'text-emerald-400' },
                    { label: 'Branding', val: 'World Class', color: 'text-purple-400' },
                    { label: 'Cấu Trúc', val: 'Complex', color: 'text-blue-400' },
                    { label: 'Responsive', val: 'Full', color: 'text-amber-400' },
                  ].map((stat, i) => (
                    <div key={i} className="p-3 bg-white/5 rounded-xl border border-white/5">
                      <div className={`text-xs font-black ${stat.color}`}>{stat.val}</div>
                      <div className="text-[8px] text-slate-500 font-bold uppercase">{stat.label}</div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="bg-slate-900/50 rounded-2xl border border-white/5 overflow-hidden flex flex-col min-h-[180px]">
              <div className="p-3 border-b border-white/5 flex items-center gap-2 bg-slate-900/80"><MessageSquare className="w-3 h-3 text-indigo-400" /><span className="text-[10px] font-black text-slate-300 tracking-widest uppercase">Creative Assistant</span></div>
              <div className="flex-1 overflow-y-auto p-4 space-y-3 text-[11px] h-32 custom-scrollbar">
                {chatHistory.length === 0 && <p className="text-slate-600 italic font-medium">Hệ thống đang sẵn sàng xử lý...</p>}
                {chatHistory.map((msg, i) => (
                  <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                    <div className={`max-w-[90%] p-2 rounded-xl ${msg.role === 'user' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-800 text-slate-300'}`}>{msg.content}</div>
                  </div>
                ))}
              </div>
              <form onSubmit={handleChat} className="p-2 border-t border-white/5 flex gap-2 bg-slate-900/50">
                <input value={chatInput} onChange={(e) => setChatInput(e.target.value)} placeholder="Nhập yêu cầu..." className="flex-1 bg-slate-950 border border-white/10 rounded-lg px-3 py-1 text-[10px] outline-none placeholder:text-slate-800" />
                <button className="p-1.5 bg-indigo-600 rounded-lg text-white hover:bg-indigo-500"><Play className="w-3 h-3 fill-current" /></button>
              </form>
            </div>
          </div>
        </aside>

        {/* Workspace */}
        <section className="flex-1 p-4 sm:p-6 grid grid-cols-1 lg:grid-cols-2 gap-6 overflow-y-auto sm:overflow-hidden bg-[#020617]">
