import { 
  Sparkles, Settings2, Zap, MessageSquare, Play, Download, CheckCircle2, 
  Loader2, Eye, Code2, Infinity, Activity, Image as ImageIcon, X, Rocket, 
  Smartphone, Tablet as TabletIcon, Monitor, Menu, ChevronLeft, ChevronRight, 
  Palette, Search, Key, FolderOpen, FileCode, Plus, Trash2, Save
} from 'lucide-react';

const INITIAL_PROJECT: Project = {
  name: "New Project",
  activeFileId: "1",
  files: [
    {
      id: "1",
      name: "index.html",
      language: "html",
      content: "<!DOCTYPE html>\n<html>\n<body>\n  <h1>Welcome to Forge Architect</h1>\n  <p>Start your 100k line journey here.</p>\n</body>\n</html>"
    }
  ]
};

type DeviceType = 'mobile' | 'tablet' | 'desktop';

declare global {
  interface Window {
    readonly aistudio: {
      hasSelectedApiKey: () => Promise<boolean>;
      openSelectKey: () => Promise<void>;
    };
  }
}

export default function App() {
  const [project, setProject] = useState<Project>(INITIAL_PROJECT);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStage, setProcessingStage] = useState<'architect' | 'images' | 'idle'>('idle');
  const [viewMode, setViewMode] = useState<'code' | 'preview'>('code');
  const [showHelp, setShowHelp] = useState(true);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [previewDevice, setPreviewDevice] = useState<DeviceType>('desktop');
  const [generatedImages, setGeneratedImages] = useState<GeneratedImage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);

  const activeFile = useMemo(() => 
    project.files.find(f => f.id === project.activeFileId) || project.files[0]
  , [project]);

  const updateActiveFileContent = (newContent: string) => {
    setProject(prev => ({
      ...prev,
      files: prev.files.map(f => f.id === prev.activeFileId ? { ...f, content: newContent } : f)
    }));
  };

  const addNewFile = () => {
    const name = prompt("Enter file name (e.g., about.html, style.css):");
    if (!name) return;
    const id = Math.random().toString(36).substr(2, 9);
    const lang = name.endsWith('.css') ? 'css' : name.endsWith('.js') ? 'javascript' : 'html';
    const newFile: ProjectFile = { id, name, language: lang, content: "" };
    setProject(prev => ({ ...prev, files: [...prev, files, newFile], activeFileId: id }));
  };

  const deleteFile = (id: string) => {
    if (project.files.length <= 1) return;
    setProject(prev => {
      const filtered = prev.files.filter(f => f.id !== id);
      return { ...prev, files: filtered, activeFileId: filtered[0].id };
    });
  };

  const handleFullProjectUpgrade = async () => {
    setIsProcessing(true);
    setProcessingStage('architect');
    try {
      const result = await geminiService.architectProject(`Enhance this project named ${project.name} into a professional 100k line modular build.`);
      setProject(prev => ({
        ...prev,
        files: result.files,
        activeFileId: result.files[0].id
      }));
      setViewMode('preview');
    } catch (e) {
      alert("Project Refactoring Failed.");
    } finally {
      setIsProcessing(false);
      setProcessingStage('idle');
    }
  };

  const handleFileUpgrade = async () => {
    if (!activeFile) return;
    setIsProcessing(true);
    setProcessingStage('architect');
    try {
      const result = await geminiService.upgradeFile(activeFile, project.files);
      updateActiveFileContent(result.upgradedCode);

      // Auto-process image placeholders if any
      const placeholderRegex = /\{\{AI_IMAGE_PROMPT:\s*["'](.+?)["']\s*\}\}/g;
      const matches = Array.from(result.upgradedCode.matchAll(placeholderRegex));

      if (matches.length > 0) {
        setProcessingStage('images');
        let finalCode = result.upgradedCode;
        for (const match of matches) {
          const prompt = match[1];
          try {
            const b64 = await geminiService.generateBrandingImage(prompt);
            setGeneratedImages(prev => [...prev, { url: b64, prompt }]);
            finalCode = finalCode.replace(match[0], `<img src="${b64}" alt="${prompt}" class="rounded-2xl shadow-xl w-full" />`);
          } catch (err) { console.error(err); }
        }
        updateActiveFileContent(finalCode);
      }
      setViewMode('preview');
    } catch (e) {
      alert("File Upgrade Failed.");
    } finally {
      setIsProcessing(false);
      setProcessingStage('idle');
    }
  };

  const handleChat = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || isChatLoading) return;
    const userMsg: ChatMessage = { role: 'user', content: chatInput };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatLoading(true);
    try {
      const response = await geminiService.chatAssistant(chatHistory, chatInput, project);
      setChatHistory(prev => [...prev, { role: 'assistant', content: response || 'Architect thinking...' }]);
    } catch (error) {
      setChatHistory(prev => [...prev, { role: 'assistant', content: 'Connection Error.' }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  const getPreviewWidth = () => {
    switch(previewDevice) {
      case 'mobile': return '375px';
      case 'tablet': return '768px';
      default: return '100%';
    }
  };

  // Basic Multi-file preview logic: Inject all files into the iframe context
  const previewDoc = useMemo(() => {
    if (activeFile.language !== 'html') return "";
    let doc = activeFile.content;
    const styles = project.files.filter(f => f.language === 'css').map(f => `<style>${f.content}</style>`).join("\n");
    const scripts = project.files.filter(f => f.language === 'javascript').map(f => `<script>${f.content}</script>`).join("\n");
    return doc.replace("</head>", `${styles}</head>`).replace("</body>", `${scripts}</body>`);
  }, [project, activeFile]);

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 selection:bg-indigo-500/30 overflow-hidden font-inter">
      {/* Help Modal */}
      {showHelp && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-950/90 backdrop-blur-xl animate-in fade-in duration-500">
          <div className="max-w-4xl w-full bg-[#0b0f1a] border border-white/10 rounded-3xl shadow-2xl overflow-hidden p-10 text-center">
            <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center mx-auto mb-8 shadow-2xl shadow-indigo-600/20"><Rocket className="w-10 h-10 text-white" /></div>
            <h2 className="text-4xl font-black text-white mb-4 tracking-tighter">PROJECT ARCHITECT 2025</h2>
            <p className="text-slate-400 mb-8 max-w-2xl mx-auto">Nâng cấp quy mô xử lý lên tới 100.000 dòng code. Quản lý đa trang, đồng bộ asset AI và tối ưu hóa kiến trúc Modular cho doanh nghiệp.</p>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 mb-10">
              <div className="p-6 bg-white/5 rounded-2xl border border-white/5">
                <FolderOpen className="w-6 h-6 text-indigo-400 mx-auto mb-3" />
                <h4 className="font-bold text-white text-xs uppercase mb-2">Multi-File IDE</h4>
                <p className="text-[10px] text-slate-500">Quản lý không giới hạn số lượng trang và file tài nguyên trong một Project.</p>
              </div>
              <div className="p-6 bg-white/5 rounded-2xl border border-white/5">
                <Infinity className="w-6 h-6 text-emerald-400 mx-auto mb-3" />
                <h4 className="font-bold text-white text-xs uppercase mb-2">100k Line Scale</h4>
                <p className="text-[10px] text-slate-500">Xử lý khối dữ liệu HTML/JS cực lớn bằng công nghệ Block-Refactor của Gemini Pro.</p>
              </div>
              <div className="p-6 bg-white/5 rounded-2xl border border-white/5">
                <Zap className="w-6 h-6 text-amber-400 mx-auto mb-3" />
                <h4 className="font-bold text-white text-xs uppercase mb-2">Architect AI</h4>
                <p className="text-[10px] text-slate-500">AI tự động thiết kế cấu trúc thư mục và liên kết giữa các trang web.</p>
              </div>
            </div>
            <button onClick={() => setShowHelp(false)} className="px-12 py-4 bg-white text-slate-950 rounded-2xl font-black uppercase tracking-widest hover:scale-105 transition-all shadow-2xl active:scale-95">Bắt đầu Kiến trúc Project</button>
          </div>
        </div>
      )}

      {/* Header */}
      <header className="h-16 border-b border-white/5 bg-[#0b0f1a]/80 backdrop-blur-xl px-6 flex items-center justify-between sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="p-2 bg-indigo-600 rounded-xl shadow-lg shadow-indigo-600/20"><Infinity className="w-5 h-5 text-white" /></div>
          <div>
            <h1 className="text-lg font-black text-white tracking-tighter">ARCHITECT <span className="text-indigo-400">OS</span></h1>
            <div className="flex items-center gap-1.5 text-[8px] font-bold text-slate-500 uppercase tracking-[0.2em]"><Activity className="w-2.5 h-2.5 text-emerald-500" /> High-Scale Processing Engine</div>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <button onClick={handleFullProjectUpgrade} disabled={isProcessing} className="flex items-center gap-2 px-6 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-full font-black text-xs transition-all border border-white/5 active:scale-95 disabled:opacity-50">
            <Rocket className="w-3.5 h-3.5" /> REFACTOR ENTIRE PROJECT
          </button>
          <button onClick={handleFileUpgrade} disabled={isProcessing} className="flex items-center gap-2 px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-full font-black text-xs transition-all shadow-xl shadow-indigo-600/20 active:scale-95 disabled:opacity-50">
            {isProcessing ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Sparkles className="w-3.5 h-3.5" />}
            UPGRADE ACTIVE FILE
          </button>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden">
        {/* Project Explorer Sidebar */}
        <aside className={`${sidebarOpen ? 'w-72' : 'w-0'} bg-[#0b0f1a] border-r border-white/5 flex flex-col transition-all duration-300 relative group/sidebar`}>
           <button onClick={() => setSidebarOpen(!sidebarOpen)} className="absolute -right-3 top-1/2 -translate-y-1/2 w-6 h-12 bg-[#0b0f1a] border border-white/10 rounded-full flex items-center justify-center text-slate-500 hover:text-white z-50 transition-all opacity-0 group-hover/sidebar:opacity-100">
            {sidebarOpen ? <ChevronLeft className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
          </button>

          <div className={`${!sidebarOpen && 'hidden'} p-6 flex flex-col h-full gap-6`}>
            <div>
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2"><FolderOpen className="w-3 h-3" /> Explorer</h3>
                <button onClick={addNewFile} className="p-1 hover:bg-white/5 rounded-md text-slate-400 hover:text-white transition-colors"><Plus className="w-4 h-4" /></button>
              </div>
              <div className="space-y-1">
                {project.files.map(file => (
                  <div key={file.id} onClick={() => setProject(prev => ({...prev, activeFileId: file.id}))} className={`group flex items-center justify-between p-2.5 rounded-xl cursor-pointer transition-all ${project.activeFileId === file.id ? 'bg-indigo-600/10 border border-indigo-500/20 text-white' : 'hover:bg-white/5 text-slate-500'}`}>
                    <div className="flex items-center gap-3">
                      <FileCode className={`w-4 h-4 ${project.activeFileId === file.id ? 'text-indigo-400' : 'text-slate-600'}`} />
                      <span className="text-xs font-bold truncate max-w-[120px]">{file.name}</span>
                    </div>
                    <button onClick={(e) => { e.stopPropagation(); deleteFile(file.id); }} className="opacity-0 group-hover:opacity-100 p-1 hover:text-red-400 transition-all"><Trash2 className="w-3 h-3" /></button>
                  </div>
                ))}
              </div>
            </div>

            <div className="flex-1 flex flex-col min-h-0 bg-slate-900/50 rounded-2xl border border-white/5 overflow-hidden">
              <div className="p-3 bg-slate-900/80 border-b border-white/5 flex items-center justify-between">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><MessageSquare className="w-3 h-3" /> Architect AI</span>
                <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-4 text-[10px]">
                {chatHistory.map((msg, i) => (
                  <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                    <div className={`max-w-[85%] p-3 rounded-2xl ${msg.role === 'user' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'bg-slate-800 text-slate-300'}`}>
                      {msg.content}
                    </div>
                  </div>
                ))}
                {isChatLoading && <Loader2 className="w-4 h-4 animate-spin text-slate-500" />}
              </div>
              <form onSubmit={handleChat} className="p-2 border-t border-white/5 bg-[#0b0f1a]">
                <input value={chatInput} onChange={(e) => setChatInput(e.target.value)} placeholder="Hỏi kiến trúc sư..." className="w-full bg-slate-950 border border-white/10 rounded-lg px-3 py-2 text-[10px] outline-none focus:border-indigo-500" />
              </form>
            </div>
          </div>
        </aside>

        {/* Editor & Preview Area */}
        <section className="flex-1 flex flex-col p-6 gap-6 overflow-hidden">
          <div className="flex-1 grid grid-cols-1 lg:grid-cols-2 gap-6 min-h-0">
            {/* Editor Container */}
            <div className="flex flex-col h-full overflow-hidden bg-[#0b0f1a] rounded-3xl border border-white/5 shadow-2xl relative">
              <div className="p-4 bg-[#131929] border-b border-white/5 flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="p-1.5 bg-indigo-500/10 rounded-lg"><Code2 className="w-4 h-4 text-indigo-400" /></div>
                  <span className="text-[10px] font-black text-white uppercase tracking-widest">{activeFile.name}</span>
                </div>
                <div className="flex gap-1.5">
                  <div className="w-2.5 h-2.5 rounded-full bg-red-500/20 border border-red-500/40"></div>
                  <div className="w-2.5 h-2.5 rounded-full bg-amber-500/20 border border-amber-500/40"></div>
                  <div className="w-2.5 h-2.5 rounded-full bg-emerald-500/20 border border-emerald-500/40"></div>
                </div>
              </div>
              <textarea
                value={activeFile.content}
                onChange={(e) => updateActiveFileContent(e.target.value)}
                spellCheck={false}
                className="flex-1 p-8 bg-transparent text-slate-300 code-font text-xs sm:text-sm outline-none resize-none leading-relaxed placeholder:text-slate-800"
                placeholder="Kiến trúc 100k dòng lệnh bắt đầu tại đây..."
              />
            </div>

            {/* Preview Container */}
            <div className="flex flex-col h-full overflow-hidden bg-[#0b0f1a] rounded-3xl border border-white/5 shadow-2xl relative">
              <div className="p-4 bg-[#131929] border-b border-white/5 flex items-center justify-between">
                <div className="flex items-center gap-2 bg-slate-950/50 p-1 rounded-xl border border-white/10">
                  <button onClick={() => setViewMode('code')} className={`px-4 py-1.5 text-[9px] font-black rounded-lg transition-all ${viewMode === 'code' ? 'bg-indigo-600 text-white' : 'text-slate-500 hover:text-slate-300'}`}>SOURCE</button>
                  <button onClick={() => setViewMode('preview')} className={`px-4 py-1.5 text-[9px] font-black rounded-lg transition-all ${viewMode === 'preview' ? 'bg-indigo-600 text-white' : 'text-slate-500 hover:text-slate-300'}`}>PREVIEW</button>
                </div>
                <div className="flex items-center gap-2 bg-slate-950/50 p-1 rounded-xl border border-white/10">
                  <button onClick={() => setPreviewDevice('mobile')} className={`p-1.5 rounded-lg ${previewDevice === 'mobile' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Smartphone className="w-3.5 h-3.5" /></button>
                  <button onClick={() => setPreviewDevice('tablet')} className={`p-1.5 rounded-lg ${previewDevice === 'tablet' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><TabletIcon className="w-3.5 h-3.5" /></button>
                  <button onClick={() => setPreviewDevice('desktop')} className={`p-1.5 rounded-lg ${previewDevice === 'desktop' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Monitor className="w-3.5 h-3.5" /></button>
                </div>
              </div>

              <div className="flex-1 flex justify-center items-start overflow-hidden relative bg-[#020617] p-4 sm:p-8">
                {viewMode === 'preview' ? (
                  <div style={{ width: getPreviewWidth() }} className="h-full bg-white shadow-2xl transition-all duration-700 rounded-sm overflow-hidden animate-in fade-in zoom-in-95">
                    {previewDoc ? (
                      <iframe title="Project View" srcDoc={previewDoc} className="w-full h-full border-none" sandbox="allow-scripts allow-forms" />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center text-slate-800 font-bold uppercase text-xs tracking-widest text-center px-10">Chọn file HTML để xem trước project</div>
                    )}
                  </div>
                ) : (
                   <div className="w-full h-full flex flex-col items-center justify-center text-slate-800 opacity-20 select-none">
                    <Code2 className="w-24 h-24 mb-6" />
                    <span className="text-xl font-black uppercase tracking-[0.5em]">IDE ACTIVE</span>
                   </div>
                )}

                {isProcessing && (
                  <div className="absolute inset-0 bg-slate-950/95 backdrop-blur-xl z-50 flex flex-col items-center justify-center p-10 text-center animate-in fade-in">
                    <div className="relative mb-12">
                      <div className="w-32 h-32 border-2 border-indigo-500/10 rounded-full animate-ping"></div>
                      <div className="absolute inset-0 w-32 h-32 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin [animation-duration:1.5s]"></div>
                      <div className="absolute inset-0 m-auto w-14 h-14 flex items-center justify-center">
                         <Rocket className="w-10 h-10 text-indigo-500 animate-pulse" />
                      </div>
                    </div>
                    <h2 className="text-3xl font-black text-white mb-4 tracking-tighter uppercase italic">
                      {processingStage === 'architect' ? 'Kiến trúc quy mô 100k...' : 'Đồng bộ Visual Assets...'}
                    </h2>
                    <p className="text-slate-500 text-sm max-w-sm font-medium leading-relaxed">
                      Gemini đang xử lý khối dữ liệu cực lớn, tối ưu hóa Modular Pattern và đồng bộ hóa các tài nguyên đa trang...
                    </p>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Action Bar */}
          <div className="h-16 flex items-center justify-between px-6 bg-[#0b0f1a] border border-white/5 rounded-2xl shadow-xl">
             <div className="flex items-center gap-6">
                <div className="flex items-center gap-2">
                  <div className="w-2 h-2 rounded-full bg-emerald-500 shadow-lg shadow-emerald-500/50"></div>
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Architect Online</span>
                </div>
                <div className="h-4 w-px bg-white/5"></div>
                <div className="text-[10px] font-black text-slate-600 uppercase tracking-widest">Project: <span className="text-white">{project.name}</span></div>
                <div className="text-[10px] font-black text-slate-600 uppercase tracking-widest">Files: <span className="text-white">{project.files.length}</span></div>
             </div>

             <div className="flex items-center gap-3">
                <button onClick={() => window.aistudio.openSelectKey()} className="p-2.5 bg-slate-800 text-slate-400 hover:text-white rounded-xl border border-white/10 transition-all hover:scale-105" title="API Configuration"><Key className="w-4 h-4" /></button>
                <button className="flex items-center gap-2 px-6 py-2 bg-white text-slate-950 rounded-xl font-black text-[10px] uppercase tracking-tighter hover:bg-slate-200 transition-all active:scale-95">
                  <Save className="w-4 h-4" /> Save Project
                </button>
             </div>
          </div>
        </section>
      </main>

      {/* Footer Branding */}
      <footer className="h-8 border-t border-white/5 bg-[#020617] px-6 flex items-center justify-between text-[8px] font-black uppercase tracking-[0.2em] text-slate-700">
        <div className="flex items-center gap-4">
          <span>Forge Architect v6.0.1 (Experimental)</span>
          <span className="text-indigo-500/50">100k Line Ready</span>
        </div>
        <div>Forge OS © 2025 // Global Digital Architecture</div>
      </footer>
    </div>
  );
}

{
  "name": "Forge Project Architect 2025",
  "description": "A high-scale AI design system for building 100,000+ line web projects. Multi-page modular architecture, real-time sync, and Gemini Pro 3 integration.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React, { useState, useMemo, useEffect } from 'react';
import { Editor } from './components/Editor';
import { geminiService } from './services/geminiService';
import { Project, ProjectFile, UpgradeFeature, ChatMessage, GeneratedImage } from './types';
import { 
  Sparkles, Settings2, Zap, MessageSquare, Play, Download, CheckCircle2, 
  Loader2, Eye, Code2, Infinity, Activity, Image as ImageIcon, X, Rocket, 
  Smartphone, Tablet as TabletIcon, Monitor, Menu, ChevronLeft, ChevronRight, 
  Palette, Search, Key, FolderOpen, FileCode, Plus, Trash2, Save
} from 'lucide-react';

const INITIAL_PROJECT: Project = {
  name: "New Project",
  activeFileId: "1",
  files: [
    {
      id: "1",
      name: "index.html",
      language: "html",
      content: "<!DOCTYPE html>\n<html>\n<body>\n  <h1>Welcome to Forge Architect</h1>\n  <p>Start your 100k line journey here.</p>\n</body>\n</html>"
    }
  ]
};

type DeviceType = 'mobile' | 'tablet' | 'desktop';

declare global {
  interface Window {
    // Fix: Using the expected AIStudio type from the environment to resolve type mismatch and identical modifiers errors.
    aistudio: AIStudio;
  }
}

export default function App() {
  const [project, setProject] = useState<Project>(INITIAL_PROJECT);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStage, setProcessingStage] = useState<'architect' | 'images' | 'idle'>('idle');
  const [viewMode, setViewMode] = useState<'code' | 'preview'>('code');
  const [showHelp, setShowHelp] = useState(true);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [previewDevice, setPreviewDevice] = useState<DeviceType>('desktop');
  const [generatedImages, setGeneratedImages] = useState<GeneratedImage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);

  // Mandatory: Check for API key on mount for Pro and Image models
  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
        await window.aistudio.openSelectKey();
      }
    };
    checkKey();
  }, []);

  const activeFile = useMemo(() => 
    project.files.find(f => f.id === project.activeFileId) || project.files[0]
  , [project]);

  const updateActiveFileContent = (newContent: string) => {
    setProject(prev => ({
      ...prev,
      files: prev.files.map(f => f.id === prev.activeFileId ? { ...f, content: newContent } : f)
    }));
  };

  const addNewFile = () => {
    const name = prompt("Enter file name (e.g., about.html, style.css):");
    if (!name) return;
    const id = Math.random().toString(36).substr(2, 9);
    const lang = name.endsWith('.css') ? 'css' : name.endsWith('.js') ? 'javascript' : 'html';
    const newFile: ProjectFile = { id, name, language: lang, content: "" };
    // Fix: Corrected spread logic and removed undefined 'files' variable. Spreading prev.files instead of prev.
    setProject(prev => ({ ...prev, files: [...prev.files, newFile], activeFileId: id }));
  };

  const deleteFile = (id: string) => {
    if (project.files.length <= 1) return;
    setProject(prev => {
      const filtered = prev.files.filter(f => f.id !== id);
      return { ...prev, files: filtered, activeFileId: filtered[0].id };
    });
  };

  const handleFullProjectUpgrade = async () => {
    // Mandatory: Ensure API key is selected before using Pro models
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
    }

    setIsProcessing(true);
    setProcessingStage('architect');
    try {
      const result = await geminiService.architectProject(`Enhance this project named ${project.name} into a professional 100k line modular build.`);
      setProject(prev => ({
        ...prev,
        files: result.files,
        activeFileId: result.files[0].id
      }));
      setViewMode('preview');
    } catch (e) {
      alert("Project Refactoring Failed.");
    } finally {
      setIsProcessing(false);
      setProcessingStage('idle');
    }
  };

  const handleFileUpgrade = async () => {
    if (!activeFile) return;

    // Mandatory: Ensure API key is selected before using Pro models
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
    }

    setIsProcessing(true);
    setProcessingStage('architect');
    try {
      const result = await geminiService.upgradeFile(activeFile, project.files);
      updateActiveFileContent(result.upgradedCode);

      // Auto-process image placeholders if any
      const placeholderRegex = /\{\{AI_IMAGE_PROMPT:\s*["'](.+?)["']\s*\}\}/g;
      const matches = Array.from(result.upgradedCode.matchAll(placeholderRegex));

      if (matches.length > 0) {
        setProcessingStage('images');
        let finalCode = result.upgradedCode;
        for (const match of matches) {
          const prompt = match[1];
          try {
            const b64 = await geminiService.generateBrandingImage(prompt);
            setGeneratedImages(prev => [...prev, { url: b64, prompt }]);
            finalCode = finalCode.replace(match[0], `<img src="${b64}" alt="${prompt}" class="rounded-2xl shadow-xl w-full" />`);
          } catch (err) { console.error(err); }
        }
        updateActiveFileContent(finalCode);
      }
      setViewMode('preview');
    } catch (e) {
      alert("File Upgrade Failed.");
    } finally {
      setIsProcessing(false);
      setProcessingStage('idle');
    }
  };

  const handleChat = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || isChatLoading) return;

    // Mandatory: Ensure API key is selected before using Pro models
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
    }

    const userMsg: ChatMessage = { role: 'user', content: chatInput };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatLoading(true);
    try {
      const response = await geminiService.chatAssistant(chatHistory, chatInput, project);
      setChatHistory(prev => [...prev, { role: 'assistant', content: response || 'Architect thinking...' }]);
    } catch (error) {
      setChatHistory(prev => [...prev, { role: 'assistant', content: 'Connection Error.' }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  const getPreviewWidth = () => {
    switch(previewDevice) {
      case 'mobile': return '375px';
      case 'tablet': return '768px';
      default: return '100%';
    }
  };

  // Basic Multi-file preview logic: Inject all files into the iframe context
  const previewDoc = useMemo(() => {
    if (activeFile.language !== 'html') return "";
    let doc = activeFile.content;
    const styles = project.files.filter(f => f.language === 'css').map(f => `<style>${f.content}</style>`).join("\n");
    const scripts = project.files.filter(f => f.language === 'javascript').map(f => `<script>${f.content}</script>`).join("\n");
    return doc.replace("</head>", `${styles}</head>`).replace("</body>", `${scripts}</body>`);
  }, [project, activeFile]);

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 selection:bg-indigo-500/30 overflow-hidden font-inter">
      {/* Help Modal */}
      {showHelp && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-950/90 backdrop-blur-xl animate-in fade-in duration-500">
          <div className="max-w-4xl w-full bg-[#0b0f1a] border border-white/10 rounded-3xl shadow-2xl overflow-hidden p-10 text-center">
            <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center mx-auto mb-8 shadow-2xl shadow-indigo-600/20"><Rocket className="w-10 h-10 text-white" /></div>
            <h2 className="text-4xl font-black text-white mb-4 tracking-tighter">PROJECT ARCHITECT 2025</h2>
            <p className="text-slate-400 mb-8 max-w-2xl mx-auto">Nâng cấp quy mô xử lý lên tới 100.000 dòng code. Quản lý đa trang, đồng bộ asset AI và tối ưu hóa kiến trúc Modular cho doanh nghiệp.</p>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 mb-10">
              <div className="p-6 bg-white/5 rounded-2xl border border-white/5">
                <FolderOpen className="w-6 h-6 text-indigo-400 mx-auto mb-3" />
                <h4 className="font-bold text-white text-xs uppercase mb-2">Multi-File IDE</h4>
                <p className="text-[10px] text-slate-500">Quản lý không giới hạn số lượng trang và file tài nguyên trong một Project.</p>
              </div>
              <div className="p-6 bg-white/5 rounded-2xl border border-white/5">
                <Infinity className="w-6 h-6 text-emerald-400 mx-auto mb-3" />
                <h4 className="font-bold text-white text-xs uppercase mb-2">100k Line Scale</h4>
                <p className="text-[10px] text-slate-500">Xử lý khối dữ liệu HTML/JS cực lớn bằng công nghệ Block-Refactor của Gemini Pro.</p>
              </div>
              <div className="p-6 bg-white/5 rounded-2xl border border-white/5">
                <Zap className="w-6 h-6 text-amber-400 mx-auto mb-3" />
                <h4 className="font-bold text-white text-xs uppercase mb-2">Architect AI</h4>
                <p className="text-[10px] text-slate-500">AI tự động thiết kế cấu trúc thư mục và liên kết giữa các trang web.</p>
              </div>
            </div>
            <button onClick={() => setShowHelp(false)} className="px-12 py-4 bg-white text-slate-950 rounded-2xl font-black uppercase tracking-widest hover:scale-105 transition-all shadow-2xl active:scale-95">Bắt đầu Kiến trúc Project</button>
          </div>
        </div>
      )}

      {/* Header */}
      <header className="h-16 border-b border-white/5 bg-[#0b0f1a]/80 backdrop-blur-xl px-6 flex items-center justify-between sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="p-2 bg-indigo-600 rounded-xl shadow-lg shadow-indigo-600/20"><Infinity className="w-5 h-5 text-white" /></div>
          <div>
            <h1 className="text-lg font-black text-white tracking-tighter">ARCHITECT <span className="text-indigo-400">OS</span></h1>
            <div className="flex items-center gap-1.5 text-[8px] font-bold text-slate-500 uppercase tracking-[0.2em]"><Activity className="w-2.5 h-2.5 text-emerald-500" /> High-Scale Processing Engine</div>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <button onClick={handleFullProjectUpgrade} disabled={isProcessing} className="flex items-center gap-2 px-6 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-full font-black text-xs transition-all border border-white/5 active:scale-95 disabled:opacity-50">
            <Rocket className="w-3.5 h-3.5" /> REFACTOR ENTIRE PROJECT
          </button>
          <button onClick={handleFileUpgrade} disabled={isProcessing} className="flex items-center gap-2 px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-full font-black text-xs transition-all shadow-xl shadow-indigo-600/20 active:scale-95 disabled:opacity-50">
