import { GoogleGenAI, Type } from "@google/genai";
import { UpgradeResult, ProjectFile } from "../types";

const TEXT_MODEL = 'gemini-3-pro-preview';
const IMAGE_MODEL = 'gemini-3-pro-image-preview';

export class GeminiService {
  private getAI() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  // Handle mandatory API key selection error as per guidelines
  private async handlePotentialKeyError(error: any) {
    if (error?.message?.includes("Requested entity was not found.")) {
      if (window.aistudio) {
        await window.aistudio.openSelectKey();
      }
    }
    throw error;
  }

  async architectProject(prompt: string): Promise<{files: ProjectFile[]}> {
    const ai = this.getAI();
    const systemInstruction = `
      You are the "Forge Architect 2025". Your goal is to design a high-scale multi-page project (up to 100k lines scale).
      When the user describes a project, generate a structure of at least 3 essential files (e.g., index.html, styles.css, main.js).
      Focus on modularity, high-performance clean code, and modern branding.
      Return the project as a JSON array of files.
    `;

    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `Create a professional multi-page project based on: ${prompt}`,
        config: {
          systemInstruction,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              files: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    id: { type: Type.STRING },
                    name: { type: Type.STRING },
                    language: { type: Type.STRING },
                    content: { type: Type.STRING }
                  },
                  required: ["id", "name", "language", "content"]
                }
              }
            },
            required: ["files"]
          }
        }
      });

      // Use .text property as per guidelines
      return JSON.parse(response.text || '{"files": []}');
    } catch (e) {
      return this.handlePotentialKeyError(e);
    }
  }

  async upgradeFile(file: ProjectFile, allFiles: ProjectFile[]): Promise<UpgradeResult> {
    const ai = this.getAI();
    const context = allFiles.map(f => f.name).join(", ");

    const systemInstruction = `
      You are an expert full-stack refactorer. You are upgrading a single file: ${file.name}.
      Project Context includes: ${context}.
      Ensure this file is optimized for a 100,000 line scale project. Use modular patterns.
      If images are needed, use {{AI_IMAGE_PROMPT: "Description"}}.
      Return valid JSON.
    `;

    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `Upgrade this file contents:\n\n${file.content}`,
        config: {
          systemInstruction,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              upgradedCode: { type: Type.STRING },
              explanation: { type: Type.STRING },
              automationSummary: { type: Type.ARRAY, items: { type: Type.STRING } },
              stats: {
                type: Type.OBJECT,
                properties: {
                  linesAdded: { type: Type.INTEGER },
                  linesRemoved: { type: Type.INTEGER },
                  accessibilityScore: { type: Type.INTEGER },
                  estimatedPerformanceGain: { type: Type.STRING },
                  securityScore: { type: Type.INTEGER },
                  seoReady: { type: Type.BOOLEAN }
                },
                required: ["linesAdded", "linesRemoved", "accessibilityScore", "estimatedPerformanceGain", "securityScore", "seoReady"]
              }
            },
            required: ["upgradedCode", "explanation", "automationSummary", "stats"]
          }
        }
      });

      // Use .text property as per guidelines
      return JSON.parse(response.text || '{}');
    } catch (e) {
      return this.handlePotentialKeyError(e);
    }
  }

  async generateBrandingImage(prompt: string): Promise<string> {
    const ai = this.getAI(); 
    try {
      const response = await ai.models.generateContent({
        model: IMAGE_MODEL,
        contents: {
          parts: [{ text: `Professional website asset: ${prompt}. High resolution, 8k, modern 2025 aesthetic.` }]
        },
        config: {
          imageConfig: { aspectRatio: "16:9", imageSize: "1K" }
        }
      });

      // Find the image part as per guidelines
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
          return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
      throw new Error("Image Generation Failed: No image part found in response.");
    } catch (e) {
      return this.handlePotentialKeyError(e);
    }
  }

  async chatAssistant(history: { role: string, content: string }[], message: string, project: any) {
    const ai = this.getAI();
    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: {
          parts: [
            { text: `Current Project Files: ${project.files.map((f: any) => f.name).join(", ")}` },
            ...history.map(h => ({ text: `${h.role === 'user' ? 'User' : 'Assistant'}: ${h.content}` })),
            { text: `Request: ${message}` }
          ]
        },
        config: {
          systemInstruction: "You are the Project Architect. You help manage massive 100k line projects with multiple files."
        }
      });
      // Use .text property as per guidelines
      return response.text;
    } catch (e) {
      return this.handlePotentialKeyError(e);
    }
  }
}

export const geminiService = new GeminiService();

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { Editor } from './components/Editor';
import { geminiService } from './services/geminiService';
import { Project, ProjectFile, UpgradeFeature, ChatMessage, GeneratedImage } from './types';
import { 
  Sparkles, Settings2, Zap, MessageSquare, Play, Download, CheckCircle2, 
  Loader2, Eye, Code2, Infinity, Activity, Image as ImageIcon, X, Rocket, 
  Smartphone, Tablet as TabletIcon, Monitor, Menu, ChevronLeft, ChevronRight, 
  Palette, Search, Key, FolderOpen, FileCode, Plus, Trash2, Save, RefreshCw
} from 'lucide-react';

const INITIAL_PROJECT: Project = {
  name: "New Project",
  activeFileId: "1",
  files: [
    {
      id: "1",
      name: "index.html",
      language: "html",
      content: "<!DOCTYPE html>\n<html>\n<head>\n  <title>Forge Build</title>\n</head>\n<body>\n  <h1>Welcome to Forge Architect</h1>\n  <p>Start your journey with an AI generated hero image:</p>\n  <div class=\"hero\">\n    {{AI_IMAGE_PROMPT: \"A cinematic 8k photo of a futuristic coffee shop with neon lights and flying robots\"}}\n  </div>\n</body>\n</html>"
    }
  ]
};

type DeviceType = 'mobile' | 'tablet' | 'desktop';

declare global {
  interface Window {
    aistudio: AIStudio;
  }
}

export default function App() {
  const [project, setProject] = useState<Project>(INITIAL_PROJECT);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStage, setProcessingStage] = useState<'architect' | 'images' | 'idle'>('idle');
  const [viewMode, setViewMode] = useState<'code' | 'preview'>('code');
  const [showHelp, setShowHelp] = useState(true);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [previewDevice, setPreviewDevice] = useState<DeviceType>('desktop');
  const [generatedImages, setGeneratedImages] = useState<GeneratedImage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);
  const [hasPendingAssets, setHasPendingAssets] = useState(false);

  // Check for API key on mount
  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
        await window.aistudio.openSelectKey();
      }
    };
    checkKey();
  }, []);

  // Monitor for pending assets
  useEffect(() => {
    const placeholderRegex = /\{\{AI_IMAGE_PROMPT:\s*["'](.+?)["']\s*\}\}/g;
    const hasPending = project.files.some(f => placeholderRegex.test(f.content));
    setHasPendingAssets(hasPending);
  }, [project.files]);

  const activeFile = useMemo(() => 
    project.files.find(f => f.id === project.activeFileId) || project.files[0]
  , [project]);

  const updateActiveFileContent = (newContent: string) => {
    setProject(prev => ({
      ...prev,
      files: prev.files.map(f => f.id === prev.activeFileId ? { ...f, content: newContent } : f)
    }));
  };

  const addNewFile = () => {
    const name = prompt("Enter file name (e.g., about.html, style.css):");
    if (!name) return;
    const id = Math.random().toString(36).substr(2, 9);
    const lang = name.endsWith('.css') ? 'css' : name.endsWith('.js') ? 'javascript' : 'html';
    const newFile: ProjectFile = { id, name, language: lang, content: "" };
    setProject(prev => ({ ...prev, files: [...prev.files, newFile], activeFileId: id }));
  };

  const deleteFile = (id: string) => {
    if (project.files.length <= 1) return;
    setProject(prev => {
      const filtered = prev.files.filter(f => f.id !== id);
      return { ...prev, files: filtered, activeFileId: filtered[0].id };
    });
  };

  const syncVisualAssets = async () => {
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
    }

    setIsProcessing(true);
    setProcessingStage('images');

    try {
      const newFiles = [...project.files];
      const placeholderRegex = /\{\{AI_IMAGE_PROMPT:\s*["'](.+?)["']\s*\}\}/g;

      for (let i = 0; i < newFiles.length; i++) {
        let content = newFiles[i].content;
        const matches = Array.from(content.matchAll(placeholderRegex));

        for (const match of matches) {
          const fullTag = match[0];
          const prompt = match[1];
          try {
            const b64 = await geminiService.generateBrandingImage(prompt);
            setGeneratedImages(prev => [...prev, { url: b64, prompt }]);
            const imgTag = `<img src="${b64}" alt="${prompt}" class="rounded-2xl shadow-2xl w-full object-cover aspect-video hover:scale-[1.02] transition-transform duration-500" />`;
            content = content.replace(fullTag, imgTag);
          } catch (err) {
            console.error(`Failed to generate asset for: ${prompt}`, err);
          }
        }
        newFiles[i].content = content;
      }

      setProject(prev => ({ ...prev, files: newFiles }));
    } catch (e) {
      alert("Asset Synchronization Failed.");
    } finally {
      setIsProcessing(false);
      setProcessingStage('idle');
    }
  };

  const handleFullProjectUpgrade = async () => {
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
    }

    setIsProcessing(true);
    setProcessingStage('architect');
    try {
      const result = await geminiService.architectProject(`Enhance this project named ${project.name} into a professional modular build with 2025 aesthetics.`);
      setProject(prev => ({
        ...prev,
        files: result.files,
        activeFileId: result.files[0].id
      }));
      setViewMode('preview');
    } catch (e) {
      alert("Project Refactoring Failed.");
    } finally {
      setIsProcessing(false);
      setProcessingStage('idle');
    }
  };

  const handleFileUpgrade = async () => {
    if (!activeFile) return;
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
    }

    setIsProcessing(true);
    setProcessingStage('architect');
    try {
      const result = await geminiService.upgradeFile(activeFile, project.files);
      updateActiveFileContent(result.upgradedCode);
      setViewMode('preview');
    } catch (e) {
      alert("File Upgrade Failed.");
    } finally {
      setIsProcessing(false);
      setProcessingStage('idle');
    }
  };

  const handleChat = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || isChatLoading) return;
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
    }

    const userMsg: ChatMessage = { role: 'user', content: chatInput };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatLoading(true);
    try {
      const response = await geminiService.chatAssistant(chatHistory, chatInput, project);
      setChatHistory(prev => [...prev, { role: 'assistant', content: response || 'Architect thinking...' }]);
    } catch (error) {
      setChatHistory(prev => [...prev, { role: 'assistant', content: 'Connection Error.' }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  const getPreviewWidth = () => {
    switch(previewDevice) {
      case 'mobile': return '375px';
      case 'tablet': return '768px';
      default: return '100%';
    }
  };

  const previewDoc = useMemo(() => {
    if (activeFile.language !== 'html') return "";
