export class GeminiService {
  private getAI() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  // Explicitly return Promise<never> to fix type assignment errors in callers' catch blocks.
  // This informs TypeScript that the function never returns a value, it always throws.
  private async handlePotentialKeyError(error: any): Promise<never> {
    if (error?.message?.includes("Requested entity was not found.")) {
      if (window.aistudio) {
        await window.aistudio.openSelectKey();
      }
    }
    throw error;
  }

  async architectProject(prompt: string): Promise<{files: ProjectFile[]}> {
    const ai = this.getAI();
    const systemInstruction = `
      You are the "Forge Architect 2025". Your goal is to design a modular, high-scale multi-page project.
      When the user describes a project, generate a structure of essential files (index.html, styles.css, etc.).
      CRITICAL: Whenever a section needs a professional image, use the placeholder tag exactly like this: {{AI_IMAGE_PROMPT: "A detailed visual description"}}.
      Focus on modularity and high-performance clean code.
      Return the project as a JSON object with a 'files' array.
    `;

    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `Create a professional multi-page project based on: ${prompt}`,
        config: {
          systemInstruction,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              files: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    id: { type: Type.STRING },
                    name: { type: Type.STRING },
                    language: { type: Type.STRING },
                    content: { type: Type.STRING }
                  },
                  required: ["id", "name", "language", "content"]
                }
              }
            },
            required: ["files"]
          }
        }
      });

      return JSON.parse(response.text || '{"files": []}');
    } catch (e) {
      return this.handlePotentialKeyError(e);
    }
  }

  async upgradeFile(file: ProjectFile, allFiles: ProjectFile[]): Promise<UpgradeResult> {
    const ai = this.getAI();
    const context = allFiles.map(f => f.name).join(", ");

    const systemInstruction = `
      You are an expert full-stack refactorer. You are upgrading a single file: ${file.name}.
      Project Context includes: ${context}.
      Apply professional 2025 branding. 
      CRITICAL: For any new visual components, insert {{AI_IMAGE_PROMPT: "Description"}}. 
      Do not use external image URLs. Use Tailwind classes.
      Return valid JSON.
    `;

    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `Upgrade this file contents:\n\n${file.content}`,
        config: {
          systemInstruction,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              upgradedCode: { type: Type.STRING },
              explanation: { type: Type.STRING },
              automationSummary: { type: Type.ARRAY, items: { type: Type.STRING } },
              stats: {
                type: Type.OBJECT,
                properties: {
                  linesAdded: { type: Type.INTEGER },
                  linesRemoved: { type: Type.INTEGER },
                  accessibilityScore: { type: Type.INTEGER },
                  estimatedPerformanceGain: { type: Type.STRING },
                  securityScore: { type: Type.INTEGER },
                  seoReady: { type: Type.BOOLEAN }
                },
                required: ["linesAdded", "linesRemoved", "accessibilityScore", "estimatedPerformanceGain", "securityScore", "seoReady"]
              }
            },
            required: ["upgradedCode", "explanation", "automationSummary", "stats"]
          }
        }
      });

      return JSON.parse(response.text || '{}');
    } catch (e) {
      return this.handlePotentialKeyError(e);
    }
  }

  async generateBrandingImage(prompt: string): Promise<string> {
    const ai = this.getAI(); 
    try {
      const response = await ai.models.generateContent({
        model: IMAGE_MODEL,
        contents: {
          parts: [{ text: `High-quality website visual asset: ${prompt}. Professional, sharp focus, 8k, modern aesthetic, cinematic lighting.` }]
        },
        config: {
          imageConfig: { 
            aspectRatio: "16:9", 
            imageSize: "1K" 
          }
        }
      });

      // Find image part as per guidelines
      for (const part of response.candidates?.[0]?.content?.parts || []) {
        if (part.inlineData) {
          return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
      throw new Error("No image part returned from Gemini.");
    } catch (e) {
      return this.handlePotentialKeyError(e);
    }
  }

  async chatAssistant(history: { role: string, content: string }[], message: string, project: any) {
    const ai = this.getAI();
    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: {
          parts: [
            { text: `Current Project Files: ${project.files.map((f: any) => f.name).join(", ")}` },
            ...history.map(h => ({ text: `${h.role === 'user' ? 'User' : 'Assistant'}: ${h.content}` })),
            { text: `Request: ${message}` }
          ]
        },
        config: {
          systemInstruction: "You are the Project Architect. You assist in managing high-scale web projects. You can suggest adding {{AI_IMAGE_PROMPT: '...'}} for visual enhancements."
        }
      });
      return response.text;
    } catch (e) {
      return this.handlePotentialKeyError(e);
    }
  }
}

export const geminiService = new GeminiService();

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { Editor } from './components/Editor';
import { geminiService } from './services/geminiService';
import { Project, ProjectFile, UpgradeFeature, ChatMessage, GeneratedImage } from './types';
import { 
  Sparkles, Settings2, Zap, MessageSquare, Play, Download, CheckCircle2, 
  Loader2, Eye, Code2, Infinity, Activity, Image as ImageIcon, X, Rocket, 
  Smartphone, Tablet as TabletIcon, Monitor, Menu, ChevronLeft, ChevronRight, 
  Palette, Search, Key, FolderOpen, FileCode, Plus, Trash2, Save, RefreshCw
} from 'lucide-center';

const INITIAL_PROJECT: Project = {
  name: "New Project",
  activeFileId: "1",
  files: [
    {
      id: "1",
      name: "index.html",
      language: "html",
      content: "<!DOCTYPE html>\n<html>\n<head>\n  <title>Forge Build</title>\n</head>\n<body>\n  <h1>Welcome to Forge Architect</h1>\n  <p>Start your journey with an AI generated hero image:</p>\n  <div class=\"hero\">\n    {{AI_IMAGE_PROMPT: \"A cinematic 8k photo of a futuristic coffee shop with neon lights and flying robots\"}}\n  </div>\n</body>\n</html>"
    }
  ]
};

type DeviceType = 'mobile' | 'tablet' | 'desktop';

// Define the interface for AIStudio to provide type safety and resolve global declaration errors.
interface AIStudio {
  hasSelectedApiKey: () => Promise<boolean>;
  openSelectKey: () => Promise<void>;
}

declare global {
  interface Window {
    // Making aistudio optional to handle environments where it may not be present and fix modifier conflicts.
    aistudio?: AIStudio;
  }
}

export default function App() {
  const [project, setProject] = useState<Project>(INITIAL_PROJECT);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStage, setProcessingStage] = useState<'architect' | 'images' | 'idle'>('idle');
  const [viewMode, setViewMode] = useState<'code' | 'preview'>('code');
  const [showHelp, setShowHelp] = useState(true);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [previewDevice, setPreviewDevice] = useState<DeviceType>('desktop');
  const [generatedImages, setGeneratedImages] = useState<GeneratedImage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);
  const [hasPendingAssets, setHasPendingAssets] = useState(false);

  // Check for API key on mount using global window.aistudio
  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
        await window.aistudio.openSelectKey();
      }
    };
    checkKey();
  }, []);

  // Monitor for pending assets
  useEffect(() => {
    const placeholderRegex = /\{\{AI_IMAGE_PROMPT:\s*["'](.+?)["']\s*\}\}/g;
    const hasPending = project.files.some(f => placeholderRegex.test(f.content));
    setHasPendingAssets(hasPending);
  }, [project.files]);

  const activeFile = useMemo(() => 
    project.files.find(f => f.id === project.activeFileId) || project.files[0]
  , [project]);

  const updateActiveFileContent = (newContent: string) => {
    setProject(prev => ({
      ...prev,
      files: prev.files.map(f => f.id === prev.activeFileId ? { ...f, content: newContent } : f)
    }));
  };

  const addNewFile = () => {
    const name = prompt("Enter file name (e.g., about.html, style.css):");
    if (!name) return;
    const id = Math.random().toString(36).substr(2, 9);
    const lang = name.endsWith('.css') ? 'css' : name.endsWith('.js') ? 'javascript' : 'html';
    const newFile: ProjectFile = { id, name, language: lang, content: "" };
    setProject(prev => ({ ...prev, files: [...prev.files, newFile], activeFileId: id }));
  };

  const deleteFile = (id: string) => {
    if (project.files.length <= 1) return;
    setProject(prev => {
      const filtered = prev.files.filter(f => f.id !== id);
      return { ...prev, files: filtered, activeFileId: filtered[0].id };
    });
  };

  const syncVisualAssets = async () => {
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
    }

    setIsProcessing(true);
    setProcessingStage('images');

    try {
      const newFiles = [...project.files];
      const placeholderRegex = /\{\{AI_IMAGE_PROMPT:\s*["'](.+?)["']\s*\}\}/g;

      for (let i = 0; i < newFiles.length; i++) {
        let content = newFiles[i].content;
        const matches = Array.from(content.matchAll(placeholderRegex));

        for (const match of matches) {
          const fullTag = match[0];
          const prompt = match[1];
          try {
            const b64 = await geminiService.generateBrandingImage(prompt);
            setGeneratedImages(prev => [...prev, { url: b64, prompt }]);
            const imgTag = `<img src="${b64}" alt="${prompt}" class="rounded-2xl shadow-2xl w-full object-cover aspect-video hover:scale-[1.02] transition-transform duration-500" />`;
            content = content.replace(fullTag, imgTag);
          } catch (err) {
            console.error(`Failed to generate asset for: ${prompt}`, err);
          }
        }
        newFiles[i].content = content;
      }

      setProject(prev => ({ ...prev, files: newFiles }));
    } catch (e) {
      alert("Asset Synchronization Failed.");
    } finally {
      setIsProcessing(false);
      setProcessingStage('idle');
    }
  };

  const handleFullProjectUpgrade = async () => {
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
    }

    setIsProcessing(true);
    setProcessingStage('architect');
    try {
      const result = await geminiService.architectProject(`Enhance this project named ${project.name} into a professional modular build with 2025 aesthetics.`);
      setProject(prev => ({
        ...prev,
        files: result.files,
        activeFileId: result.files[0].id
      }));
      setViewMode('preview');
    } catch (e) {
      alert("Project Refactoring Failed.");
    } finally {
      setIsProcessing(false);
      setProcessingStage('idle');
    }
  };

  const handleFileUpgrade = async () => {
    if (!activeFile) return;
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
    }

    setIsProcessing(true);
    setProcessingStage('architect');
    try {
      const result = await geminiService.upgradeFile(activeFile, project.files);
      updateActiveFileContent(result.upgradedCode);
      setViewMode('preview');
    } catch (e) {
      alert("File Upgrade Failed.");
    } finally {
      setIsProcessing(false);
      setProcessingStage('idle');
    }
  };

  const handleChat = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || isChatLoading) return;
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
    }

    const userMsg: ChatMessage = { role: 'user', content: chatInput };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatLoading(true);
    try {
      const response = await geminiService.chatAssistant(chatHistory, chatInput, project);
      setChatHistory(prev => [...prev, { role: 'assistant', content: response || 'Architect thinking...' }]);
    } catch (error) {
      setChatHistory(prev => [...prev, { role: 'assistant', content: 'Connection Error.' }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  const getPreviewWidth = () => {
    switch(previewDevice) {
      case 'mobile': return '375px';
      case 'tablet': return '768px';
      default: return '100%';
    }
  };

  const previewDoc = useMemo(() => {
    if (activeFile.language !== 'html') return "";
    let doc = activeFile.content;
    const styles = project.files.filter(f => f.language === 'css').map(f => `<style>${f.content}</style>`).join("\n");
    const scripts = project.files.filter(f => f.language === 'javascript').map(f => `<script>${f.content}</script>`).join("\n");
    return doc.replace("</head>", `${styles}</head>`).replace("</body>", `${scripts}</body>`);
  }, [project.files, activeFile]);

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 selection:bg-indigo-500/30 overflow-hidden font-inter">
      {/* Help Modal */}
      {showHelp && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-950/90 backdrop-blur-xl animate-in fade-in duration-500">
          <div className="max-w-4xl w-full bg-[#0b0f1a] border border-white/10 rounded-3xl shadow-2xl overflow-hidden p-10 text-center relative">
            <button onClick={() => setShowHelp(false)} className="absolute top-6 right-6 text-slate-500 hover:text-white transition-colors"><X className="w-6 h-6" /></button>
            <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center mx-auto mb-8 shadow-2xl shadow-indigo-600/20"><Rocket className="w-10 h-10 text-white" /></div>
            <h2 className="text-4xl font-black text-white mb-4 tracking-tighter uppercase">Visual Synchronizer 2025</h2>
            <p className="text-slate-400 mb-8 max-w-2xl mx-auto">Tự động thiết kế và đồng bộ hóa tài nguyên hình ảnh AI cho toàn bộ Project của bạn. Sử dụng gemini-3-pro-image-preview cho chất lượng visual đỉnh cao.</p>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 mb-10">
              <div className="p-6 bg-white/5 rounded-2xl border border-white/5 group hover:border-indigo-500/30 transition-all">
                <ImageIcon className="w-6 h-6 text-indigo-400 mx-auto mb-3" />
                <h4 className="font-bold text-white text-xs uppercase mb-2">Auto-Asset Engine</h4>
                {/* Fixed: Escape curly braces with a string literal to prevent JSX interpretation as an object literal. */}
                <p className="text-[10px] text-slate-500">Quét các tag {'{{AI_IMAGE_PROMPT}}'} và thay thế bằng ảnh AI thực tế chỉ với một click.</p>
              </div>
              <div className="p-6 bg-white/5 rounded-2xl border border-white/5 group hover:border-emerald-500/30 transition-all">
                <Palette className="w-6 h-6 text-emerald-400 mx-auto mb-3" />
                <h4 className="font-bold text-white text-xs uppercase mb-2">High-Res 1K Output</h4>
                <p className="text-[10px] text-slate-500">Hình ảnh được tạo ra với độ phân giải cao, phù hợp cho landing page chuyên nghiệp.</p>
              </div>
              <div className="p-6 bg-white/5 rounded-2xl border border-white/5 group hover:border-amber-500/30 transition-all">
                <RefreshCw className="w-6 h-6 text-amber-400 mx-auto mb-3" />
                <h4 className="font-bold text-white text-xs uppercase mb-2">Real-time Sync</h4>
                <p className="text-[10px] text-slate-500">Đồng bộ hóa tức thì giữa mã nguồn, thư viện asset và giao diện preview live.</p>
              </div>
            </div>
            <button onClick={() => setShowHelp(false)} className="px-12 py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest hover:scale-105 transition-all shadow-2xl active:scale-95">Khởi tạo Visual Architect</button>
          </div>
        </div>
      )}

      {/* Header */}
      <header className="h-16 border-b border-white/5 bg-[#0b0f1a]/80 backdrop-blur-xl px-6 flex items-center justify-between sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="p-2 bg-indigo-600 rounded-xl shadow-lg shadow-indigo-600/20"><Infinity className="w-5 h-5 text-white" /></div>
          <div>
            <h1 className="text-lg font-black text-white tracking-tighter">ARCHITECT <span className="text-indigo-400">OS</span></h1>
            <div className="flex items-center gap-1.5 text-[8px] font-bold text-slate-500 uppercase tracking-[0.2em]"><Activity className="w-2.5 h-2.5 text-emerald-500" /> Visual Sync v2.0.5</div>
          </div>
        </div>

        <div className="flex items-center gap-3">
          {hasPendingAssets && (
             <button onClick={syncVisualAssets} disabled={isProcessing} className="flex items-center gap-2 px-6 py-2 bg-amber-600 hover:bg-amber-500 text-white rounded-full font-black text-xs transition-all shadow-lg shadow-amber-600/20 animate-pulse active:scale-95 disabled:opacity-50">
              <RefreshCw className={`w-3.5 h-3.5 ${isProcessing && 'animate-spin'}`} /> SYNC ASSETS
            </button>
          )}
          <button onClick={handleFullProjectUpgrade} disabled={isProcessing} className="flex items-center gap-2 px-6 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-full font-black text-xs transition-all border border-white/5 active:scale-95 disabled:opacity-50">
            <Rocket className="w-3.5 h-3.5" /> PROJECT REFACTOR
          </button>
          <button onClick={handleFileUpgrade} disabled={isProcessing} className="flex items-center gap-2 px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-full font-black text-xs transition-all shadow-xl shadow-indigo-600/20 active:scale-95 disabled:opacity-50">
            {isProcessing ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Sparkles className="w-3.5 h-3.5" />}
            UPGRADE FILE
          </button>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden">
        {/* Project Explorer Sidebar */}
        <aside className={`${sidebarOpen ? 'w-72' : 'w-0'} bg-[#0b0f1a] border-r border-white/5 flex flex-col transition-all duration-300 relative group/sidebar`}>
           <button onClick={() => setSidebarOpen(!sidebarOpen)} className="absolute -right-3 top-1/2 -translate-y-1/2 w-6 h-12 bg-[#0b0f1a] border border-white/10 rounded-full flex items-center justify-center text-slate-500 hover:text-white z-50 transition-all opacity-0 group-hover/sidebar:opacity-100 shadow-xl">
            {sidebarOpen ? <ChevronLeft className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
          </button>

          <div className={`${!sidebarOpen && 'hidden'} p-6 flex flex-col h-full gap-6`}>
            <div>
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2"><FolderOpen className="w-3 h-3" /> Project Files</h3>
                <button onClick={addNewFile} className="p-1 hover:bg-white/5 rounded-md text-slate-400 hover:text-white transition-colors"><Plus className="w-4 h-4" /></button>
              </div>
              <div className="space-y-1">
                {project.files.map(file => (
                  <div key={file.id} onClick={() => setProject(prev => ({...prev, activeFileId: file.id}))} className={`group flex items-center justify-between p-2.5 rounded-xl cursor-pointer transition-all ${project.activeFileId === file.id ? 'bg-indigo-600/10 border border-indigo-500/20 text-white shadow-inner' : 'hover:bg-white/5 text-slate-500'}`}>
                    <div className="flex items-center gap-3">
                      <FileCode className={`w-4 h-4 ${project.activeFileId === file.id ? 'text-indigo-400' : 'text-slate-600'}`} />
                      <span className="text-xs font-bold truncate max-w-[120px]">{file.name}</span>
                    </div>
                    <button onClick={(e) => { e.stopPropagation(); deleteFile(file.id); }} className="opacity-0 group-hover:opacity-100 p-1 hover:text-red-400 transition-all"><Trash2 className="w-3 h-3" /></button>
                  </div>
                ))}
              </div>
            </div>

            {/* Visual Asset Gallery */}
            <div>
              <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2 mb-4"><ImageIcon className="w-3 h-3" /> Asset Library</h3>
              <div className="grid grid-cols-2 gap-2 max-h-48 overflow-y-auto pr-1">
                {generatedImages.length > 0 ? generatedImages.map((img, i) => (
                  <div key={i} className="group relative rounded-lg overflow-hidden border border-white/10 aspect-square bg-slate-900 animate-in zoom-in-95">
                    <img src={img.url} alt={img.prompt} className="w-full h-full object-cover group-hover:scale-110 transition-transform" />
                    <div className="absolute inset-0 bg-indigo-600/60 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                      <Download onClick={() => {
                        const a = document.createElement('a');
                        a.href = img.url;
                        a.download = `forge_asset_${i}.png`;
                        a.click();
                      }} className="w-4 h-4 text-white cursor-pointer hover:scale-110 transition-transform" />
                    </div>
                  </div>
                )) : (
                  <div className="col-span-2 py-8 border border-dashed border-white/5 rounded-xl text-center text-[9px] text-slate-700 uppercase font-black tracking-widest opacity-50">No Assets Yet</div>
                )}
              </div>
            </div>

            <div className="flex-1 flex flex-col min-h-0 bg-slate-900/50 rounded-2xl border border-white/5 overflow-hidden">
              <div className="p-3 bg-slate-900/80 border-b border-white/5 flex items-center justify-between">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><MessageSquare className="w-3 h-3" /> Architect Chat</span>
                <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-4 text-[10px]">
                {chatHistory.map((msg, i) => (
                  <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                    <div className={`max-w-[85%] p-3 rounded-2xl ${msg.role === 'user' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-800 text-slate-300'}`}>
                      {msg.content}
                    </div>
                  </div>
                ))}
                {isChatLoading && <Loader2 className="w-4 h-4 animate-spin text-slate-500" />}
              </div>
              <form onSubmit={handleChat} className="p-2 border-t border-white/5 bg-[#0b0f1a]">
                <input value={chatInput} onChange={(e) => setChatInput(e.target.value)} placeholder="Consult the architect..." className="w-full bg-slate-950 border border-white/10 rounded-lg px-3 py-2 text-[10px] outline-none focus:border-indigo-500 transition-all placeholder:text-slate-800" />
              </form>
            </div>
          </div>
        </aside>

        {/* Editor & Preview Area */}
        <section className="flex-1 flex flex-col p-6 gap-6 overflow-hidden">
          <div className="flex-1 grid grid-cols-1 lg:grid-cols-2 gap-6 min-h-0">
            {/* Editor Container */}
            <div className="flex flex-col h-full overflow-hidden bg-[#0b0f1a] rounded-3xl border border-white/5 shadow-2xl relative">
              <div className="p-4 bg-[#131929] border-b border-white/5 flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="p-1.5 bg-indigo-500/10 rounded-lg"><Code2 className="w-4 h-4 text-indigo-400" /></div>
                  <span className="text-[10px] font-black text-white uppercase tracking-widest">{activeFile.name}</span>
                </div>
                {hasPendingAssets && (
                   <span className="flex items-center gap-1.5 px-2 py-0.5 bg-amber-500/10 border border-amber-500/20 rounded-full text-[8px] font-black text-amber-500 animate-pulse">PENDING ASSETS</span>
                )}
              </div>
              <textarea
                value={activeFile.content}
                onChange={(e) => updateActiveFileContent(e.target.value)}
                spellCheck={false}
                className="flex-1 p-8 bg-transparent text-slate-300 code-font text-xs sm:text-sm outline-none resize-none leading-relaxed placeholder:text-slate-800 selection:bg-indigo-500/30"
                placeholder="Paste code or type {{AI_IMAGE_PROMPT: '...'}} to generate visuals..."
              />
            </div>

            {/* Preview Container */}
            <div className="flex flex-col h-full overflow-hidden bg-[#0b0f1a] rounded-3xl border border-white/5 shadow-2xl relative">
              <div className="p-4 bg-[#131929] border-b border-white/5 flex items-center justify-between">
                <div className="flex items-center gap-2 bg-slate-950/50 p-1 rounded-xl border border-white/10">
                  <button onClick={() => setViewMode('code')} className={`px-4 py-1.5 text-[9px] font-black rounded-lg transition-all ${viewMode === 'code' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>SOURCE</button>
                  <button onClick={() => setViewMode('preview')} className={`px-4 py-1.5 text-[9px] font-black rounded-lg transition-all ${viewMode === 'preview' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>LIVE VIEW</button>
                </div>
                <div className="flex items-center gap-2 bg-slate-950/50 p-1 rounded-xl border border-white/10">
                  <button onClick={() => setPreviewDevice('mobile')} className={`p-1.5 rounded-lg ${previewDevice === 'mobile' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Smartphone className="w-3.5 h-3.5" /></button>
                  <button onClick={() => setPreviewDevice('tablet')} className={`p-1.5 rounded-lg ${previewDevice === 'tablet' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><TabletIcon className="w-3.5 h-3.5" /></button>
                  <button onClick={() => setPreviewDevice('desktop')} className={`p-1.5 rounded-lg ${previewDevice === 'desktop' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Monitor className="w-3.5 h-3.5" /></button>
                </div>
              </div>

              <div className="flex-1 flex justify-center items-start overflow-hidden relative bg-[#020617] p-4 sm:p-8">
                {viewMode === 'preview' ? (
                  <div style={{ width: getPreviewWidth() }} className="h-full bg-white shadow-2xl transition-all duration-700 rounded-sm overflow-hidden animate-in fade-in zoom-in-95">
                    {previewDoc ? (
                      <iframe title="Project View" srcDoc={previewDoc} className="w-full h-full border-none bg-white" sandbox="allow-scripts allow-forms" />
                    ) : (
                      <div className="w-full h-full flex flex-col items-center justify-center text-slate-800 bg-white">
                         <Search className="w-12 h-12 mb-4 opacity-10" />
                         <p className="text-[10px] font-black uppercase tracking-widest opacity-30">Waiting for HTML content</p>
                      </div>
                    )}
                  </div>
                ) : (
                   <div className="w-full h-full flex flex-col items-center justify-center text-slate-800 opacity-20 select-none">
                    <Infinity className="w-24 h-24 mb-6 animate-pulse" />
                    <span className="text-xl font-black uppercase tracking-[0.5em]">ARCHITECT MODE</span>
                   </div>
                )}

                {isProcessing && (
                  <div className="absolute inset-0 bg-slate-950/95 backdrop-blur-xl z-50 flex flex-col items-center justify-center p-10 text-center animate-in fade-in">
                    <div className="relative mb-12">
                      <div className="w-32 h-32 border-2 border-indigo-500/10 rounded-full animate-ping"></div>
                      <div className="absolute inset-0 w-32 h-32 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin [animation-duration:1.5s]"></div>
                      <div className="absolute inset-0 m-auto w-14 h-14 flex items-center justify-center">
                         {processingStage === 'architect' ? <Rocket className="w-10 h-10 text-indigo-500 animate-pulse" /> : <ImageIcon className="w-10 h-10 text-amber-500 animate-pulse" />}
                      </div>
                    </div>
                    <h2 className="text-3xl font-black text-white mb-4 tracking-tighter uppercase italic">
                      {processingStage === 'architect' ? 'Project Architecture Sync...' : 'Synchronizing Visual Assets...'}
                    </h2>
                    <p className="text-slate-400 text-sm max-w-sm font-medium leading-relaxed">
                      {processingStage === 'architect' 
                        ? 'Gemini Architect đang tái cấu trúc Project 100k dòng, tối ưu hóa Modular Pattern và đồng bộ hóa đa trang...' 
                        : 'Gemini Image Engine đang tạo các hình ảnh 1K độc bản dựa trên prompt của bạn và nhúng trực tiếp vào source...'}
                    </p>
                    <div className="mt-12 flex gap-3">
                      <div className="w-2 h-2 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                      <div className="w-2 h-2 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                      <div className="w-2 h-2 bg-indigo-500 rounded-full animate-bounce"></div>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Action Bar */}
          <div className="h-16 flex items-center justify-between px-6 bg-[#0b0f1a] border border-white/5 rounded-2xl shadow-xl">
             <div className="flex items-center gap-6">
                <div className="flex items-center gap-2">
                  <div className="w-2 h-2 rounded-full bg-emerald-500 shadow-lg shadow-emerald-500/50"></div>
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Architect Engine v5.0</span>
                </div>
                <div className="h-4 w-px bg-white/5"></div>
                <div className="text-[10px] font-black text-slate-600 uppercase tracking-widest">Active: <span className="text-white ml-1">{activeFile.name}</span></div>
             </div>

             <div className="flex items-center gap-3">
                <button onClick={() => window.aistudio?.openSelectKey()} className="p-2.5 bg-slate-800 text-slate-400 hover:text-white rounded-xl border border-white/10 transition-all hover:scale-105 shadow-lg" title="API Configuration"><Key className="w-4 h-4" /></button>
                <button className="flex items-center gap-2 px-6 py-2 bg-white text-slate-950 rounded-xl font-black text-[10px] uppercase tracking-tighter hover:bg-slate-200 transition-all active:scale-95 shadow-lg">
                  <Save className="w-4 h-4" /> Save Snapshot
                </button>
             </div>
          </div>
        </section>
      </main>

      {/* Footer Branding */}
      <footer className="h-10 border-t border-white/5 bg-[#020617] px-6 flex items-center justify-between text-[8px] font-black uppercase tracking-[0.2em] text-slate-700">
        <div className="flex items-center gap-6">
          <span className="flex items-center gap-2"><div className="w-1.5 h-1.5 bg-indigo-500 rounded-full"></div> Forge Architect Pro v6.2</span>
          <span className="text-indigo-500/50">Multi-Page Hybrid Engine Ready</span>
        </div>
        <div>FORGE OS // VISUAL SYNCHRONIZATION // © 2025 DIGITAL ARCHITECTURE</div>
      </footer>
    </div>
  );
}

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { Editor } from './components/Editor';
import { geminiService } from './services/geminiService';
import { Project, ProjectFile, UpgradeFeature, ChatMessage, GeneratedImage } from './types';
import { 
  Sparkles, Settings2, Zap, MessageSquare, Play, Download, CheckCircle2, 
  Loader2, Eye, Code2, Infinity, Activity, Image as ImageIcon, X, Rocket, 
  Smartphone, Tablet as TabletIcon, Monitor, Menu, ChevronLeft, ChevronRight, 
  Palette, Search, Key, FolderOpen, FileCode, Plus, Trash2, Save, RefreshCw
} from 'lucide-react';

const INITIAL_PROJECT: Project = {
  name: "New Project",
  activeFileId: "1",
  files: [
    {
      id: "1",
      name: "index.html",
      language: "html",
      content: "<!DOCTYPE html>\n<html>\n<head>\n  <title>Forge Build</title>\n</head>\n<body>\n  <h1>Welcome to Forge Architect</h1>\n  <p>Start your journey with an AI generated hero image:</p>\n  <div class=\"hero\">\n    {{AI_IMAGE_PROMPT: \"A cinematic 8k photo of a futuristic coffee shop with neon lights and flying robots\"}}\n  </div>\n</body>\n</html>"
    }
  ]
};

type DeviceType = 'mobile' | 'tablet' | 'desktop';

// Define the interface for AIStudio to provide type safety and resolve global declaration errors.
interface AIStudio {
  hasSelectedApiKey: () => Promise<boolean>;
  openSelectKey: () => Promise<void>;
}

declare global {
  interface Window {
    // Making aistudio optional to handle environments where it may not be present and fix modifier conflicts.
    aistudio?: AIStudio;
  }
}

export default function App() {
  const [project, setProject] = useState<Project>(INITIAL_PROJECT);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStage, setProcessingStage] = useState<'architect' | 'images' | 'idle'>('idle');
  const [viewMode, setViewMode] = useState<'code' | 'preview'>('code');
  const [showHelp, setShowHelp] = useState(true);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [previewDevice, setPreviewDevice] = useState<DeviceType>('desktop');
  const [generatedImages, setGeneratedImages] = useState<GeneratedImage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);
  const [hasPendingAssets, setHasPendingAssets] = useState(false);

  // Check for API key on mount using global window.aistudio
  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
        await window.aistudio.openSelectKey();
      }
    };
    checkKey();
  }, []);

  // Monitor for pending assets
  useEffect(() => {
    const placeholderRegex = /\{\{AI_IMAGE_PROMPT:\s*["'](.+?)["']\s*\}\}/g;
    const hasPending = project.files.some(f => placeholderRegex.test(f.content));
    setHasPendingAssets(hasPending);
  }, [project.files]);

  const activeFile = useMemo(() => 
    project.files.find(f => f.id === project.activeFileId) || project.files[0]
  , [project]);

  const updateActiveFileContent = (newContent: string) => {
    setProject(prev => ({
      ...prev,
      files: prev.files.map(f => f.id === prev.activeFileId ? { ...f, content: newContent } : f)
    }));
  };

  const addNewFile = () => {
    const name = prompt("Enter file name (e.g., about.html, style.css):");
    if (!name) return;
    const id = Math.random().toString(36).substr(2, 9);
    const lang = name.endsWith('.css') ? 'css' : name.endsWith('.js') ? 'javascript' : 'html';
    const newFile: ProjectFile = { id, name, language: lang, content: "" };
    setProject(prev => ({ ...prev, files: [...prev.files, newFile], activeFileId: id }));
  };

  const deleteFile = (id: string) => {
    if (project.files.length <= 1) return;
    setProject(prev => {
      const filtered = prev.files.filter(f => f.id !== id);
      return { ...prev, files: filtered, activeFileId: filtered[0].id };
    });
  };

  const syncVisualAssets = async (targetFiles?: ProjectFile[]) => {
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
    }

    setIsProcessing(true);
    setProcessingStage('images');

    try {
      const newFiles = targetFiles ? [...targetFiles] : [...project.files];
      const placeholderRegex = /\{\{AI_IMAGE_PROMPT:\s*["'](.+?)["']\s*\}\}/g;

      for (let i = 0; i < newFiles.length; i++) {
        let content = newFiles[i].content;
        const matches = Array.from(content.matchAll(placeholderRegex));

        for (const match of matches) {
          const fullTag = match[0];
          const prompt = match[1];
          try {
            const b64 = await geminiService.generateBrandingImage(prompt);
            setGeneratedImages(prev => [...prev, { url: b64, prompt }]);
            const imgTag = `<img src="${b64}" alt="${prompt}" class="rounded-2xl shadow-2xl w-full object-cover aspect-video hover:scale-[1.02] transition-transform duration-500" />`;
            content = content.replace(fullTag, imgTag);
          } catch (err) {
            console.error(`Failed to generate asset for: ${prompt}`, err);
          }
        }
        newFiles[i].content = content;
      }

      setProject(prev => ({ ...prev, files: newFiles }));
    } catch (e) {
      alert("Asset Synchronization Failed.");
    } finally {
      setIsProcessing(false);
      setProcessingStage('idle');
    }
  };

  const handleFullProjectUpgrade = async () => {
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
    }

    setIsProcessing(true);
    setProcessingStage('architect');
    try {
      const result = await geminiService.architectProject(`Enhance this project named ${project.name} into a professional modular build with 2025 aesthetics.`);
      // After architecture is set, automatically sync any placeholders
      await syncVisualAssets(result.files);
      setProject(prev => ({
        ...prev,
        files: prev.files, // project state will be updated by syncVisualAssets
        activeFileId: result.files[0].id
      }));
      setViewMode('preview');
    } catch (e) {
      alert("Project Refactoring Failed.");
    } finally {
      setIsProcessing(false);
      setProcessingStage('idle');
    }
  };

  const handleFileUpgrade = async () => {
    if (!activeFile) return;
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
    }

    setIsProcessing(true);
    setProcessingStage('architect');
    try {
      const result = await geminiService.upgradeFile(activeFile, project.files);
      const updatedFiles = project.files.map(f => f.id === activeFile.id ? { ...f, content: result.upgradedCode } : f);
      // Auto-sync images for this specific upgrade
      await syncVisualAssets(updatedFiles);
      setViewMode('preview');
    } catch (e) {
      alert("File Upgrade Failed.");
    } finally {
      setIsProcessing(false);
      setProcessingStage('idle');
    }
  };

  const handleChat = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || isChatLoading) return;
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
    }

    const userMsg: ChatMessage = { role: 'user', content: chatInput };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatLoading(true);
    try {
      const response = await geminiService.chatAssistant(chatHistory, chatInput, project);
      setChatHistory(prev => [...prev, { role: 'assistant', content: response || 'Architect thinking...' }]);
    } catch (error) {
      setChatHistory(prev => [...prev, { role: 'assistant', content: 'Connection Error.' }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  const getPreviewWidth = () => {
    switch(previewDevice) {
      case 'mobile': return '375px';
      case 'tablet': return '768px';
      default: return '100%';
    }
  };

  const previewDoc = useMemo(() => {
    if (activeFile.language !== 'html') return "";
    let doc = activeFile.content;
    const styles = project.files.filter(f => f.language === 'css').map(f => `<style>${f.content}</style>`).join("\n");
    const scripts = project.files.filter(f => f.language === 'javascript').map(f => `<script>${f.content}</script>`).join("\n");
    return doc.replace("</head>", `${styles}</head>`).replace("</body>", `${scripts}</body>`);
  }, [project.files, activeFile]);

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 selection:bg-indigo-500/30 overflow-hidden font-inter">
      {/* Help Modal */}
      {showHelp && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-950/90 backdrop-blur-xl animate-in fade-in duration-500">
          <div className="max-w-4xl w-full bg-[#0b0f1a] border border-white/10 rounded-3xl shadow-2xl overflow-hidden p-10 text-center relative">
            <button onClick={() => setShowHelp(false)} className="absolute top-6 right-6 text-slate-500 hover:text-white transition-colors"><X className="w-6 h-6" /></button>
            <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center mx-auto mb-8 shadow-2xl shadow-indigo-600/20"><Rocket className="w-10 h-10 text-white" /></div>
            <h2 className="text-4xl font-black text-white mb-4 tracking-tighter uppercase">Visual Synchronizer 2025</h2>
            <p className="text-slate-400 mb-8 max-w-2xl mx-auto">Tự động thiết kế và đồng bộ hóa tài nguyên hình ảnh AI cho toàn bộ Project của bạn. Sử dụng gemini-3-pro-image-preview cho chất lượng visual đỉnh cao.</p>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 mb-10">
              <div className="p-6 bg-white/5 rounded-2xl border border-white/5 group hover:border-indigo-500/30 transition-all">
                <ImageIcon className="w-6 h-6 text-indigo-400 mx-auto mb-3" />
                <h4 className="font-bold text-white text-xs uppercase mb-2">Auto-Asset Engine</h4>
                <p className="text-[10px] text-slate-500">Quét các tag {'{{AI_IMAGE_PROMPT}}'} và thay thế bằng ảnh AI thực tế chỉ với một click hoặc tự động sau khi nâng cấp.</p>
              </div>
              <div className="p-6 bg-white/5 rounded-2xl border border-white/5 group hover:border-emerald-500/30 transition-all">
                <Palette className="w-6 h-6 text-emerald-400 mx-auto mb-3" />
                <h4 className="font-bold text-white text-xs uppercase mb-2">High-Res 1K Output</h4>
                <p className="text-[10px] text-slate-500">Hình ảnh được tạo ra với độ phân giải cao, phù hợp cho landing page chuyên nghiệp.</p>
              </div>
              <div className="p-6 bg-white/5 rounded-2xl border border-white/5 group hover:border-amber-500/30 transition-all">
                <RefreshCw className="w-6 h-6 text-amber-400 mx-auto mb-3" />
                <h4 className="font-bold text-white text-xs uppercase mb-2">Real-time Sync</h4>
                <p className="text-[10px] text-slate-500">Đồng bộ hóa tức thì giữa mã nguồn, thư viện asset và giao diện preview live.</p>
              </div>
            </div>
            <button onClick={() => setShowHelp(false)} className="px-12 py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest hover:scale-105 transition-all shadow-2xl active:scale-95">Khởi tạo Visual Architect</button>
          </div>
        </div>
      )}

      {/* Header */}
      <header className="h-16 border-b border-white/5 bg-[#0b0f1a]/80 backdrop-blur-xl px-6 flex items-center justify-between sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="p-2 bg-indigo-600 rounded-xl shadow-lg shadow-indigo-600/20"><Infinity className="w-5 h-5 text-white" /></div>
          <div>
            <h1 className="text-lg font-black text-white tracking-tighter">ARCHITECT <span className="text-indigo-400">OS</span></h1>
            <div className="flex items-center gap-1.5 text-[8px] font-bold text-slate-500 uppercase tracking-[0.2em]"><Activity className="w-2.5 h-2.5 text-emerald-500" /> Visual Sync v2.0.5</div>
          </div>
        </div>

        <div className="flex items-center gap-3">
          {hasPendingAssets && (
             <button onClick={() => syncVisualAssets()} disabled={isProcessing} className="flex items-center gap-2 px-6 py-2 bg-amber-600 hover:bg-amber-500 text-white rounded-full font-black text-xs transition-all shadow-lg shadow-amber-600/20 animate-pulse active:scale-95 disabled:opacity-50">
              <RefreshCw className={`w-3.5 h-3.5 ${isProcessing && 'animate-spin'}`} /> SYNC ASSETS
            </button>
          )}
          <button onClick={handleFullProjectUpgrade} disabled={isProcessing} className="flex items-center gap-2 px-6 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-full font-black text-xs transition-all border border-white/5 active:scale-95 disabled:opacity-50">
            <Rocket className="w-3.5 h-3.5" /> PROJECT REFACTOR
          </button>
          <button onClick={handleFileUpgrade} disabled={isProcessing} className="flex items-center gap-2 px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-full font-black text-xs transition-all shadow-xl shadow-indigo-600/20 active:scale-95 disabled:opacity-50">
            {isProcessing ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Sparkles className="w-3.5 h-3.5" />}
            UPGRADE FILE
          </button>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden">
        {/* Project Explorer Sidebar */}
        <aside className={`${sidebarOpen ? 'w-72' : 'w-0'} bg-[#0b0f1a] border-r border-white/5 flex flex-col transition-all duration-300 relative group/sidebar`}>
           <button onClick={() => setSidebarOpen(!sidebarOpen)} className="absolute -right-3 top-1/2 -translate-y-1/2 w-6 h-12 bg-[#0b0f1a] border border-white/10 rounded-full flex items-center justify-center text-slate-500 hover:text-white z-50 transition-all opacity-0 group-hover/sidebar:opacity-100 shadow-xl">
            {sidebarOpen ? <ChevronLeft className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
          </button>

          <div className={`${!sidebarOpen && 'hidden'} p-6 flex flex-col h-full gap-6`}>
            <div>
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2"><FolderOpen className="w-3 h-3" /> Project Files</h3>
                <button onClick={addNewFile} className="p-1 hover:bg-white/5 rounded-md text-slate-400 hover:text-white transition-colors"><Plus className="w-4 h-4" /></button>
              </div>
              <div className="space-y-1">
                {project.files.map(file => (
                  <div key={file.id} onClick={() => setProject(prev => ({...prev, activeFileId: file.id}))} className={`group flex items-center justify-between p-2.5 rounded-xl cursor-pointer transition-all ${project.activeFileId === file.id ? 'bg-indigo-600/10 border border-indigo-500/20 text-white shadow-inner' : 'hover:bg-white/5 text-slate-500'}`}>
                    <div className="flex items-center gap-3">
                      <FileCode className={`w-4 h-4 ${project.activeFileId === file.id ? 'text-indigo-400' : 'text-slate-600'}`} />
                      <span className="text-xs font-bold truncate max-w-[120px]">{file.name}</span>
                    </div>
                    <button onClick={(e) => { e.stopPropagation(); deleteFile(file.id); }} className="opacity-0 group-hover:opacity-100 p-1 hover:text-red-400 transition-all"><Trash2 className="w-3 h-3" /></button>
                  </div>
                ))}
              </div>
            </div>

            {/* Visual Asset Gallery */}
            <div>
              <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2 mb-4"><ImageIcon className="w-3 h-3" /> Asset Library</h3>
              <div className="grid grid-cols-2 gap-2 max-h-48 overflow-y-auto pr-1">
                {generatedImages.length > 0 ? generatedImages.map((img, i) => (
                  <div key={i} className="group relative rounded-lg overflow-hidden border border-white/10 aspect-square bg-slate-900 animate-in zoom-in-95">
                    <img src={img.url} alt={img.prompt} className="w-full h-full object-cover group-hover:scale-110 transition-transform" />
                    <div className="absolute inset-0 bg-indigo-600/60 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                      <Download onClick={() => {
                        const a = document.createElement('a');
                        a.href = img.url;
                        a.download = `forge_asset_${i}.png`;
                        a.click();
                      }} className="w-4 h-4 text-white cursor-pointer hover:scale-110 transition-transform" />
                    </div>
                  </div>
                )) : (
                  <div className="col-span-2 py-8 border border-dashed border-white/5 rounded-xl text-center text-[9px] text-slate-700 uppercase font-black tracking-widest opacity-50">No Assets Yet</div>
                )}
              </div>
            </div>

            <div className="flex-1 flex flex-col min-h-0 bg-slate-900/50 rounded-2xl border border-white/5 overflow-hidden">
              <div className="p-3 bg-slate-900/80 border-b border-white/5 flex items-center justify-between">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><MessageSquare className="w-3 h-3" /> Architect Chat</span>
                <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-4 text-[10px]">
                {chatHistory.map((msg, i) => (
                  <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                    <div className={`max-w-[85%] p-3 rounded-2xl ${msg.role === 'user' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-800 text-slate-300'}`}>
                      {msg.content}
                    </div>
                  </div>
                ))}
                {isChatLoading && <Loader2 className="w-4 h-4 animate-spin text-slate-500" />}
              </div>
              <form onSubmit={handleChat} className="p-2 border-t border-white/5 bg-[#0b0f1a]">
                <input value={chatInput} onChange={(e) => setChatInput(e.target.value)} placeholder="Consult the architect..." className="w-full bg-slate-950 border border-white/10 rounded-lg px-3 py-2 text-[10px] outline-none focus:border-indigo-500 transition-all placeholder:text-slate-800" />
              </form>
            </div>
          </div>
        </aside>

        {/* Editor & Preview Area */}
        <section className="flex-1 flex flex-col p-6 gap-6 overflow-hidden">
          <div className="flex-1 grid grid-cols-1 lg:grid-cols-2 gap-6 min-h-0">
            {/* Editor Container */}
            <div className="flex flex-col h-full overflow-hidden bg-[#0b0f1a] rounded-3xl border border-white/5 shadow-2xl relative">
              <div className="p-4 bg-[#131929] border-b border-white/5 flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="p-1.5 bg-indigo-500/10 rounded-lg"><Code2 className="w-4 h-4 text-indigo-400" /></div>
                  <span className="text-[10px] font-black text-white uppercase tracking-widest">{activeFile.name}</span>
                </div>
                {hasPendingAssets && (
                   <span className="flex items-center gap-1.5 px-2 py-0.5 bg-amber-500/10 border border-amber-500/20 rounded-full text-[8px] font-black text-amber-500 animate-pulse">PENDING ASSETS</span>
                )}
              </div>
              <textarea
                value={activeFile.content}
                onChange={(e) => updateActiveFileContent(e.target.value)}
                spellCheck={false}
                className="flex-1 p-8 bg-transparent text-slate-300 code-font text-xs sm:text-sm outline-none resize-none leading-relaxed placeholder:text-gray-800 selection:bg-indigo-500/30"
                placeholder="Paste code or type {{AI_IMAGE_PROMPT: '...'}} to generate visuals..."
              />
            </div>

            {/* Preview Container */}
            <div className="flex flex-col h-full overflow-hidden bg-[#0b0f1a] rounded-3xl border border-white/5 shadow-2xl relative">
              <div className="p-4 bg-[#131929] border-b border-white/5 flex items-center justify-between">
                <div className="flex items-center gap-2 bg-slate-950/50 p-1 rounded-xl border border-white/10">
                  <button onClick={() => setViewMode('code')} className={`px-4 py-1.5 text-[9px] font-black rounded-lg transition-all ${viewMode === 'code' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>SOURCE</button>
                  <button onClick={() => setViewMode('preview')} className={`px-4 py-1.5 text-[9px] font-black rounded-lg transition-all ${viewMode === 'preview' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>LIVE VIEW</button>
                </div>
                <div className="flex items-center gap-2 bg-slate-950/50 p-1 rounded-xl border border-white/10">
                  <button onClick={() => setPreviewDevice('mobile')} className={`p-1.5 rounded-lg ${previewDevice === 'mobile' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Smartphone className="w-3.5 h-3.5" /></button>
                  <button onClick={() => setPreviewDevice('tablet')} className={`p-1.5 rounded-lg ${previewDevice === 'tablet' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><TabletIcon className="w-3.5 h-3.5" /></button>
                  <button onClick={() => setPreviewDevice('desktop')} className={`p-1.5 rounded-lg ${previewDevice === 'desktop' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Monitor className="w-3.5 h-3.5" /></button>
                </div>
              </div>

              <div className="flex-1 flex justify-center items-start overflow-hidden relative bg-[#020617] p-4 sm:p-8">
                {viewMode === 'preview' ? (
                  <div style={{ width: getPreviewWidth() }} className="h-full bg-white shadow-2xl transition-all duration-700 rounded-sm overflow-hidden animate-in fade-in zoom-in-95">
                    {previewDoc ? (
                      <iframe title="Project View" srcDoc={previewDoc} className="w-full h-full border-none bg-white" sandbox="allow-scripts allow-forms" />
                    ) : (
                      <div className="w-full h-full flex flex-col items-center justify-center text-slate-800 bg-white">
                         <Search className="w-12 h-12 mb-4 opacity-10" />
                         <p className="text-[10px] font-black uppercase tracking-widest opacity-30">Waiting for HTML content</p>
                      </div>
                    )}
                  </div>
                ) : (
                   <div className="w-full h-full flex flex-col items-center justify-center text-slate-800 opacity-20 select-none">
                    <Infinity className="w-24 h-24 mb-6 animate-pulse" />
                    <span className="text-xl font-black uppercase tracking-[0.5em]">ARCHITECT MODE</span>
                   </div>
                )}

                {isProcessing && (
                  <div className="absolute inset-0 bg-slate-950/95 backdrop-blur-xl z-50 flex flex-col items-center justify-center p-10 text-center animate-in fade-in">
                    <div className="relative mb-12">
                      <div className="w-32 h-32 border-2 border-indigo-500/10 rounded-full animate-ping"></div>
                      <div className="absolute inset-0 w-32 h-32 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin [animation-duration:1.5s]"></div>
                      <div className="absolute inset-0 m-auto w-14 h-14 flex items-center justify-center">
                         {processingStage === 'architect' ? <Rocket className="w-10 h-10 text-indigo-500 animate-pulse" /> : <ImageIcon className="w-10 h-10 text-amber-500 animate-pulse" />}
                      </div>
                    </div>
                    <h2 className="text-3xl font-black text-white mb-4 tracking-tighter uppercase italic">
                      {processingStage === 'architect' ? 'Project Architecture Sync...' : 'Synchronizing Visual Assets...'}
                    </h2>
                    <p className="text-slate-400 text-sm max-w-sm font-medium leading-relaxed">
                      {processingStage === 'architect' 
                        ? 'Gemini Architect đang tái cấu trúc Project 100k dòng, tối ưu hóa Modular Pattern và đồng bộ hóa đa trang...' 
                        : 'Gemini Image Engine đang tạo các hình ảnh 1K độc bản dựa trên prompt của bạn và nhúng trực tiếp vào source...'}
                    </p>
                    <div className="mt-12 flex gap-3">
                      <div className="w-2 h-2 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                      <div className="w-2 h-2 bg-indigo-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                      <div className="w-2 h-2 bg-indigo-500 rounded-full animate-bounce"></div>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Action Bar */}
          <div className="h-16 flex items-center justify-between px-6 bg-[#0b0f1a] border border-white/5 rounded-2xl shadow-xl">
             <div className="flex items-center gap-6">
                <div className="flex items-center gap-2">
                  <div className="w-2 h-2 rounded-full bg-emerald-500 shadow-lg shadow-emerald-500/50"></div>
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Architect Engine v5.0</span>
                </div>
                <div className="h-4 w-px bg-white/5"></div>
                <div className="text-[10px] font-black text-slate-600 uppercase tracking-widest">Active: <span className="text-white ml-1">{activeFile.name}</span></div>
             </div>

             <div className="flex items-center gap-3">
                <button onClick={() => window.aistudio?.openSelectKey()} className="p-2.5 bg-slate-800 text-slate-400 hover:text-white rounded-xl border border-white/10 transition-all hover:scale-105 shadow-lg" title="API Configuration"><Key className="w-4 h-4" /></button>
                <button className="flex items-center gap-2 px-6 py-2 bg-white text-slate-950 rounded-xl font-black text-[10px] uppercase tracking-tighter hover:bg-slate-200 transition-all active:scale-95 shadow-lg">
                  <Save className="w-4 h-4" /> Save Snapshot
                </button>
             </div>
          </div>
        </section>
      </main>

      {/* Footer Branding */}
      <footer className="h-10 border-t border-white/5 bg-[#020617] px-6 flex items-center justify-between text-[8px] font-black uppercase tracking-[0.2em] text-slate-700">
        <div className="flex items-center gap-6">
          <span className="flex items-center gap-2"><div className="w-1.5 h-1.5 bg-indigo-500 rounded-full"></div> Forge Architect Pro v6.2</span>
          <span className="text-indigo-500/50">Multi-Page Hybrid Engine Ready</span>
        </div>
        <div>FORGE OS // VISUAL SYNCHRONIZATION // © 2025 DIGITAL ARCHITECTURE</div>
      </footer>
    </div>
  );
}

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { Editor } from './components/Editor';
import { geminiService } from './services/geminiService';
import { Project, ProjectFile, UpgradeFeature, ChatMessage, GeneratedImage } from './types';
import { 
  Sparkles, Settings2, Zap, MessageSquare, Play, Download, CheckCircle2, 
  Loader2, Eye, Code2, Infinity, Activity, Image as ImageIcon, X, Rocket, 
  Smartphone, Tablet as TabletIcon, Monitor, Menu, ChevronLeft, ChevronRight, 
  Palette, Search, Key, FolderOpen, FileCode, Plus, Trash2, Save, RefreshCw
} from 'lucide-react';

const INITIAL_PROJECT: Project = {
  name: "New Project",
  activeFileId: "1",
  files: [
    {
      id: "1",
      name: "index.html",
      language: "html",
      content: "<!DOCTYPE html>\n<html>\n<head>\n  <title>Forge Build</title>\n</head>\n<body>\n  <h1>Welcome to Forge Architect</h1>\n  <p>Start your journey with an AI generated hero image:</p>\n  <div class=\"hero\">\n    {{AI_IMAGE_PROMPT: \"A cinematic 8k photo of a futuristic coffee shop with neon lights and flying robots\"}}\n  </div>\n</body>\n</html>"
    }
  ]
};

type DeviceType = 'mobile' | 'tablet' | 'desktop';

// Removed redundant window.aistudio and AIStudio interface declarations to fix subsequent property declaration errors.
// These are assumed to be pre-configured and accessible globally in the execution context.

export default function App() {
  const [project, setProject] = useState<Project>(INITIAL_PROJECT);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingStage, setProcessingStage] = useState<'architect' | 'images' | 'idle'>('idle');
  const [viewMode, setViewMode] = useState<'code' | 'preview'>('code');
  const [showHelp, setShowHelp] = useState(true);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [previewDevice, setPreviewDevice] = useState<DeviceType>('desktop');
  const [generatedImages, setGeneratedImages] = useState<GeneratedImage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);
  const [hasPendingAssets, setHasPendingAssets] = useState(false);

  // Check for API key on mount using global window.aistudio
  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore: window.aistudio is injected by the environment
      if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
        // @ts-ignore: window.aistudio is injected by the environment
        await window.aistudio.openSelectKey();
      }
    };
    checkKey();
  }, []);

  // Monitor for pending assets
  useEffect(() => {
    const placeholderRegex = /\{\{AI_IMAGE_PROMPT:\s*["'](.+?)["']\s*\}\}/g;
    const hasPending = project.files.some(f => placeholderRegex.test(f.content));
    setHasPendingAssets(hasPending);
  }, [project.files]);

  const activeFile = useMemo(() => 
    project.files.find(f => f.id === project.activeFileId) || project.files[0]
  , [project]);

  const updateActiveFileContent = (newContent: string) => {
    setProject(prev => ({
      ...prev,
      files: prev.files.map(f => f.id === prev.activeFileId ? { ...f, content: newContent } : f)
    }));
  };

  const addNewFile = () => {
    const name = prompt("Enter file name (e.g., about.html, style.css):");
    if (!name) return;
    const id = Math.random().toString(36).substr(2, 9);
    const lang = name.endsWith('.css') ? 'css' : name.endsWith('.js') ? 'javascript' : 'html';
    const newFile: ProjectFile = { id, name, language: lang, content: "" };
    setProject(prev => ({ ...prev, files: [...prev.files, newFile], activeFileId: id }));
  };

  const deleteFile = (id: string) => {
    if (project.files.length <= 1) return;
    setProject(prev => {
      const filtered = prev.files.filter(f => f.id !== id);
      return { ...prev, files: filtered, activeFileId: filtered[0].id };
    });
  };

  const syncVisualAssets = async (targetFiles?: ProjectFile[]) => {
    // @ts-ignore: window.aistudio is injected by the environment
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      // @ts-ignore: window.aistudio is injected by the environment
      await window.aistudio.openSelectKey();
    }

    setIsProcessing(true);
    setProcessingStage('images');

    try {
      const newFiles = targetFiles ? [...targetFiles] : [...project.files];
      const placeholderRegex = /\{\{AI_IMAGE_PROMPT:\s*["'](.+?)["']\s*\}\}/g;

      for (let i = 0; i < newFiles.length; i++) {
        let content = newFiles[i].content;
        const matches = Array.from(content.matchAll(placeholderRegex));

        for (const match of matches) {
          const fullTag = match[0];
          const prompt = match[1];
          try {
            const b64 = await geminiService.generateBrandingImage(prompt);
            setGeneratedImages(prev => [...prev, { url: b64, prompt }]);
            const imgTag = `<img src="${b64}" alt="${prompt}" class="rounded-2xl shadow-2xl w-full object-cover aspect-video hover:scale-[1.02] transition-transform duration-500" />`;
            content = content.replace(fullTag, imgTag);
          } catch (err) {
            console.error(`Failed to generate asset for: ${prompt}`, err);
          }
        }
        newFiles[i].content = content;
      }

      setProject(prev => ({ ...prev, files: newFiles }));
    } catch (e) {
      alert("Asset Synchronization Failed.");
    } finally {
      setIsProcessing(false);
      setProcessingStage('idle');
    }
  };

  const handleFullProjectUpgrade = async () => {
    // @ts-ignore: window.aistudio is injected by the environment
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      // @ts-ignore: window.aistudio is injected by the environment
      await window.aistudio.openSelectKey();
    }

    setIsProcessing(true);
    setProcessingStage('architect');
    try {
      const result = await geminiService.architectProject(`Enhance this project named ${project.name} into a professional modular build with 2025 aesthetics.`);
      // After architecture is set, automatically sync any placeholders
      await syncVisualAssets(result.files);
      setProject(prev => ({
        ...prev,
        files: prev.files, // project state will be updated by syncVisualAssets
        activeFileId: result.files[0].id
      }));
      setViewMode('preview');
    } catch (e) {
      alert("Project Refactoring Failed.");
    } finally {
      setIsProcessing(false);
      setProcessingStage('idle');
    }
  };

  const handleFileUpgrade = async () => {
    if (!activeFile) return;
    // @ts-ignore: window.aistudio is injected by the environment
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      // @ts-ignore: window.aistudio is injected by the environment
      await window.aistudio.openSelectKey();
    }

    setIsProcessing(true);
    setProcessingStage('architect');
    try {
      const result = await geminiService.upgradeFile(activeFile, project.files);
      const updatedFiles = project.files.map(f => f.id === activeFile.id ? { ...f, content: result.upgradedCode } : f);
      // Auto-sync images for this specific upgrade
      await syncVisualAssets(updatedFiles);
      setViewMode('preview');
    } catch (e) {
      alert("File Upgrade Failed.");
    } finally {
      setIsProcessing(false);
      setProcessingStage('idle');
    }
  };

  const handleChat = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || isChatLoading) return;
    // @ts-ignore: window.aistudio is injected by the environment
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      // @ts-ignore: window.aistudio is injected by the environment
      await window.aistudio.openSelectKey();
    }

    const userMsg: ChatMessage = { role: 'user', content: chatInput };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatLoading(true);
    try {
      const response = await geminiService.chatAssistant(chatHistory, chatInput, project);
      setChatHistory(prev => [...prev, { role: 'assistant', content: response || 'Architect thinking...' }]);
    } catch (error) {
      setChatHistory(prev => [...prev, { role: 'assistant', content: 'Connection Error.' }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  const getPreviewWidth = () => {
    switch(previewDevice) {
      case 'mobile': return '375px';
      case 'tablet': return '768px';
      default: return '100%';
    }
  };

  const previewDoc = useMemo(() => {
    if (activeFile.language !== 'html') return "";
    let doc = activeFile.content;
    const styles = project.files.filter(f => f.language === 'css').map(f => `<style>${f.content}</style>`).join("\n");
    const scripts = project.files.filter(f => f.language === 'javascript').map(f => `<script>${f.content}</script>`).join("\n");
    return doc.replace("</head>", `${styles}</head>`).replace("</body>", `${scripts}</body>`);
  }, [project.files, activeFile]);

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 selection:bg-indigo-500/30 overflow-hidden font-inter">
      {/* Help Modal */}
      {showHelp && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-950/90 backdrop-blur-xl animate-in fade-in duration-500">
          <div className="max-w-4xl w-full bg-[#0b0f1a] border border-white/10 rounded-3xl shadow-2xl overflow-hidden p-10 text-center relative">
            <button onClick={() => setShowHelp(false)} className="absolute top-6 right-6 text-slate-500 hover:text-white transition-colors"><X className="w-6 h-6" /></button>
            <div className="w-20 h-20 bg-indigo-600 rounded-3xl flex items-center justify-center mx-auto mb-8 shadow-2xl shadow-indigo-600/20"><Rocket className="w-10 h-10 text-white" /></div>
            <h2 className="text-4xl font-black text-white mb-4 tracking-tighter uppercase">Visual Synchronizer 2025</h2>
            <p className="text-slate-400 mb-8 max-w-2xl mx-auto">Tự động thiết kế và đồng bộ hóa tài nguyên hình ảnh AI cho toàn bộ Project của bạn. Sử dụng gemini-3-pro-image-preview cho chất lượng visual đỉnh cao.</p>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 mb-10">
              <div className="p-6 bg-white/5 rounded-2xl border border-white/5 group hover:border-indigo-500/30 transition-all">
                <ImageIcon className="w-6 h-6 text-indigo-400 mx-auto mb-3" />
                <h4 className="font-bold text-white text-xs uppercase mb-2">Auto-Asset Engine</h4>
                <p className="text-[10px] text-slate-500">Quét các tag {'{{AI_IMAGE_PROMPT}}'} và thay thế bằng ảnh AI thực tế chỉ với một click hoặc tự động sau khi nâng cấp.</p>
              </div>
              <div className="p-6 bg-white/5 rounded-2xl border border-white/5 group hover:border-emerald-500/30 transition-all">
                <Palette className="w-6 h-6 text-emerald-400 mx-auto mb-3" />
                <h4 className="font-bold text-white text-xs uppercase mb-2">High-Res 1K Output</h4>
                <p className="text-[10px] text-slate-500">Hình ảnh được tạo ra với độ phân giải cao, phù hợp cho landing page chuyên nghiệp.</p>
              </div>
              <div className="p-6 bg-white/5 rounded-2xl border border-white/5 group hover:border-amber-500/30 transition-all">
                <RefreshCw className="w-6 h-6 text-amber-400 mx-auto mb-3" />
                <h4 className="font-bold text-white text-xs uppercase mb-2">Real-time Sync</h4>
                <p className="text-[10px] text-slate-500">Đồng bộ hóa tức thì giữa mã nguồn, thư viện asset và giao diện preview live.</p>
              </div>
            </div>
            <button onClick={() => setShowHelp(false)} className="px-12 py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest hover:scale-105 transition-all shadow-2xl active:scale-95">Khởi tạo Visual Architect</button>
          </div>
        </div>
      )}

      {/* Header */}
      <header className="h-16 border-b border-white/5 bg-[#0b0f1a]/80 backdrop-blur-xl px-6 flex items-center justify-between sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="p-2 bg-indigo-600 rounded-xl shadow-lg shadow-indigo-600/20"><Infinity className="w-5 h-5 text-white" /></div>
          <div>
            <h1 className="text-lg font-black text-white tracking-tighter">ARCHITECT <span className="text-indigo-400">OS</span></h1>
            <div className="flex items-center gap-1.5 text-[8px] font-bold text-slate-500 uppercase tracking-[0.2em]"><Activity className="w-2.5 h-2.5 text-emerald-500" /> Visual Sync v2.0.5</div>
          </div>
        </div>

        <div className="flex items-center gap-3">
          {hasPendingAssets && (
             <button onClick={() => syncVisualAssets()} disabled={isProcessing} className="flex items-center gap-2 px-6 py-2 bg-amber-600 hover:bg-amber-500 text-white rounded-full font-black text-xs transition-all shadow-lg shadow-amber-600/20 animate-pulse active:scale-95 disabled:opacity-50">
              <RefreshCw className={`w-3.5 h-3.5 ${isProcessing && 'animate-spin'}`} /> SYNC ASSETS
            </button>
          )}
          <button onClick={handleFullProjectUpgrade} disabled={isProcessing} className="flex items-center gap-2 px-6 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-full font-black text-xs transition-all border border-white/5 active:scale-95 disabled:opacity-50">
            <Rocket className="w-3.5 h-3.5" /> PROJECT REFACTOR
          </button>
          <button onClick={handleFileUpgrade} disabled={isProcessing} className="flex items-center gap-2 px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-full font-black text-xs transition-all shadow-xl shadow-indigo-600/20 active:scale-95 disabled:opacity-50">
            {isProcessing ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Sparkles className="w-3.5 h-3.5" />}
            UPGRADE FILE
          </button>
        </div>
      </header>

