import { GoogleGenAI, Type } from "@google/genai";
import { Block } from "../types";

const TEXT_MODEL = 'gemini-3-pro-preview';

export class GeminiService {
  private getAI() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  private async handlePotentialKeyError(error: any): Promise<never> {
    if (error?.message?.includes("Requested entity was not found.")) {
      // @ts-ignore
      if (window.aistudio) await window.aistudio.openSelectKey();
    }
    throw error;
  }

  async parseToBlocks(prompt: string, existingHtml?: string): Promise<{ blocks: Block[], globalCss: string }> {
    const ai = this.getAI();
    const systemInstruction = `
      You are the "Omni-Builder Architect". Your task is to transform user requests or legacy HTML into a modern, responsive website structure.
      Rules:
      1. Break the website into logical blocks (Header, Hero, Features, Testimonials, Footer, etc.).
      2. Each block should use Tailwind CSS for styling.
      3. For images, use this format: <img src="https://image.pollinations.ai/prompt/{english_visual_description}?width=800&height=600&seed={random_number}" alt="..." />.
      4. Ensure all blocks look consistent.
      5. Return ONLY a JSON object with 'blocks' (array of {id, type, name, html}) and 'globalCss' string.
    `;

    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `Input: ${prompt}\n\nExisting HTML: ${existingHtml || 'None'}`,
        config: {
          systemInstruction,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              blocks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    id: { type: Type.STRING },
                    type: { type: Type.STRING },
                    name: { type: Type.STRING },
                    html: { type: Type.STRING }
                  },
                  required: ["id", "type", "name", "html"]
                }
              },
              globalCss: { type: Type.STRING }
            },
            required: ["blocks", "globalCss"]
          }
        }
      });

      return JSON.parse(response.text || '{"blocks": [], "globalCss": ""}');
    } catch (e) {
      return this.handlePotentialKeyError(e);
    }
  }

  async chatAssistant(history: { role: string, content: string }[], message: string) {
    const ai = this.getAI();
    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: [
          ...history.map(h => ({ role: h.role === 'user' ? 'user' : 'model', parts: [{ text: h.content }] })),
          { role: 'user', parts: [{ text: message }] }
        ],
        config: {
          systemInstruction: "You are a senior UI/UX designer. Help the user refine their landing page blocks."
        }
      });
      return response.text;
    } catch (e) {
      return this.handlePotentialKeyError(e);
    }
  }
}

export const geminiService = new GeminiService();

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { geminiService } from './services/geminiService';
import { Block, OmniState, ChatMessage } from './types';
