import { GoogleGenAI, Type } from "@google/genai";
import { Block } from "../types";

const TEXT_MODEL = 'gemini-3-pro-preview';

export class GeminiService {
  private getAI() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  private async handlePotentialKeyError(error: any): Promise<never> {
    if (error?.message?.includes("Requested entity was not found.")) {
      // @ts-ignore
      if (window.aistudio) await window.aistudio.openSelectKey();
    }
    throw error;
  }

  async parseToBlocks(prompt: string, existingHtml?: string): Promise<{ blocks: Block[], globalCss: string }> {
    const ai = this.getAI();
    const systemInstruction = `
      You are the "Omni-Builder Architect". Your task is to transform user requests or legacy HTML into a modern, responsive website structure.
      Rules:
      1. Break the website into logical blocks (Header, Hero, Features, Testimonials, Footer, etc.).
      2. Each block should use Tailwind CSS for styling.
      3. For images, use this format: <img src="https://image.pollinations.ai/prompt/{detailed_english_visual_description}?width=1280&height=720&nologo=true&seed={random_number}" alt="..." />.
      4. Return ONLY a JSON object with 'blocks' (array of {id, type, name, html}) and 'globalCss' string.
    `;

    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `Input: ${prompt}\n\nExisting HTML: ${existingHtml || 'None'}`,
        config: {
          systemInstruction,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              blocks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    id: { type: Type.STRING },
                    type: { type: Type.STRING },
                    name: { type: Type.STRING },
                    html: { type: Type.STRING }
                  },
                  required: ["id", "type", "name", "html"]
                }
              },
              globalCss: { type: Type.STRING }
            },
            required: ["blocks", "globalCss"]
          }
        }
      });

      return JSON.parse(response.text || '{"blocks": [], "globalCss": ""}');
    } catch (e) {
      return this.handlePotentialKeyError(e);
    }
  }

  async refineBlockVisuals(block: Block): Promise<string> {
    const ai = this.getAI();
    const systemInstruction = `
      You are a Visual Prompt Engineer. Analyze the HTML content of the following block and update all <img> tags to have a more descriptive, high-quality visual prompt in the src (Pollinations.ai format).
      The prompt inside {detailed_description} MUST be in English, highly descriptive (mention lighting, style, 8k, cinematic, etc.), and perfectly match the context of the block.
      Example: src="https://image.pollinations.ai/prompt/cinematic_8k_photo_of_luxury_running_shoes_on_a_neon_track_high_resolution?width=1280&height=720&nologo=true&seed=123"
      Return ONLY the updated HTML string for the block.
    `;

    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `Block Name: ${block.name}\nHTML Content: ${block.html}`,
        config: { systemInstruction }
      });
      return response.text || block.html;
    } catch (e) {
      console.error("Refine visuals error:", e);
      return block.html;
    }
  }

  async chatAssistant(history: { role: string, content: string }[], message: string) {
    const ai = this.getAI();
    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: [
          ...history.map(h => ({ role: h.role === 'user' ? 'user' : 'model', parts: [{ text: h.content }] })),
          { role: 'user', parts: [{ text: message }] }
        ],
        config: {
          systemInstruction: "You are a senior UI/UX designer. Help the user refine their landing page blocks. Suggest specific Pollinations.ai image prompts if helpful."
        }
      });
      return response.text;
    } catch (e) {
      return this.handlePotentialKeyError(e);
    }
  }
}

export const geminiService = new GeminiService();

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { geminiService } from './services/geminiService';
import { Block, OmniState, ChatMessage } from './types';
import { 
  Sparkles, Zap, MessageSquare, Download, CheckCircle2, 
  Loader2, Eye, Code2, Infinity, Rocket, 
  Smartphone, Tablet as TabletIcon, Monitor, Plus, Trash2, 
  Save, RefreshCw, X, ChevronRight, Layout, Palette, Type,
  Share2, ShieldCheck, DownloadCloud, Image as ImageIcon
} from 'lucide-react';

const INITIAL_STATE: OmniState = {
  projectName: "My Landing Page",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#4f46e5",
  fontFamily: "Inter"
};

export default function App() {
  const [state, setState] = useState<OmniState>(INITIAL_STATE);
  const [isProcessing, setIsProcessing] = useState(false);
  const [syncingBlocks, setSyncingBlocks] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'tablet' | 'desktop'>('desktop');
  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);
  const [inputSource, setInputSource] = useState('');

  const previewRefs = {
    mobile: useRef<HTMLIFrameElement>(null),
    tablet: useRef<HTMLIFrameElement>(null),
    desktop: useRef<HTMLIFrameElement>(null)
  };

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
        // @ts-ignore
        await window.aistudio.openSelectKey();
      }
    };
    checkKey();
  }, []);

  const fullHtml = useMemo(() => {
    const content = state.blocks.map(b => b.html).join('\n');
    return `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <script src="https://cdn.tailwindcss.com"></script>
        <link href="https://fonts.googleapis.com/css2?family=${state.fontFamily}:wght@400;700&display=swap" rel="stylesheet">
        <style>
          body { font-family: '${state.fontFamily}', sans-serif; scroll-behavior: smooth; }
          :root { --accent: ${state.accentColor}; }
          ${state.globalCss}
          img { transition: opacity 0.5s ease-in-out; }
          img:not([src]) { opacity: 0; }
        </style>
      </head>
      <body class="bg-white text-gray-900">
        ${content}
      </body>
      </html>
    `;
  }, [state]);

  const handleBuild = async () => {
    if (!inputSource.trim()) return;
    setIsProcessing(true);
    try {
      const result = await geminiService.parseToBlocks(inputSource);
      setState(prev => ({
        ...prev,
        blocks: result.blocks,
        globalCss: result.globalCss,
        selectedBlockId: result.blocks[0]?.id || null
      }));
      setViewMode('preview');
      // Tự động kích hoạt hàng đợi tạo ảnh sau khi xây dựng xong
      setTimeout(() => autoRefineAllVisuals(result.blocks), 1000);
    } catch (e) {
      alert("Xây dựng thất bại. Vui lòng kiểm tra lại API Key.");
    } finally {
      setIsProcessing(false);
    }
  };

  const autoRefineAllVisuals = async (targetBlocks?: Block[]) => {
    const blocksToProcess = targetBlocks || state.blocks;
    if (blocksToProcess.length === 0) return;

    for (const block of blocksToProcess) {
      setSyncingBlocks(prev => new Set(prev).add(block.id));
      try {
        const refinedHtml = await geminiService.refineBlockVisuals(block);
        setState(prev => ({
          ...prev,
          blocks: prev.blocks.map(b => b.id === block.id ? { ...b, html: refinedHtml } : b)
        }));
      } catch (err) {
        console.error(`Lỗi tinh chỉnh ảnh cho khối ${block.name}:`, err);
      } finally {
        setSyncingBlocks(prev => {
          const next = new Set(prev);
          next.delete(block.id);
          return next;
        });
      }
      // Nghỉ một chút giữa các khối để tránh Rate Limit nếu có
      await new Promise(r => setTimeout(r, 500));
    }
  };

  const handleBlockChange = (id: string, newHtml: string) => {
    setState(prev => ({
      ...prev,
      blocks: prev.blocks.map(b => b.id === id ? { ...b, html: newHtml } : b)
    }));
  };

  const handleSyncScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const scrollTop = e.currentTarget.scrollTop;
    Object.values(previewRefs).forEach(ref => {
      if (ref.current && ref.current.contentWindow) {
        ref.current.contentWindow.scrollTo(0, scrollTop);
      }
    });
  };

  const refreshImage = (blockId: string) => {
    setState(prev => {
      const block = prev.blocks.find(b => b.id === blockId);
      if (!block) return prev;
      const newHtml = block.html.replace(/seed=\d+/g, `seed=${Math.floor(Math.random() * 100000)}`);
      return {
        ...prev,
        blocks: prev.blocks.map(b => b.id === blockId ? { ...b, html: newHtml } : b)
      };
    });
  };

  const handleExport = async () => {
    setIsProcessing(true);
    try {
      const parser = new DOMParser();
      const doc = parser.parseFromString(fullHtml, 'text/html');
      const images = Array.from(doc.querySelectorAll('img'));

      for (const img of images) {
        if (img.src.includes('pollinations.ai')) {
          try {
            const res = await fetch(img.src);
            const blob = await res.blob();
            const base64 = await new Promise<string>((resolve) => {
              const reader = new FileReader();
              reader.onloadend = () => resolve(reader.result as string);
              reader.readAsDataURL(blob);
            });
            img.src = base64;
          } catch (err) {
            console.error("Lỗi đóng băng ảnh:", err);
          }
        }
      }

      const finalHtml = doc.documentElement.outerHTML;
      const blob = new Blob([finalHtml], { type: 'text/html' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${state.projectName.toLowerCase().replace(/\s+/g, '-')}-frozen.html`;
      a.click();
    } finally {
      setIsProcessing(false);
    }
  };

  const handleChat = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || isChatLoading) return;
    const userMsg: ChatMessage = { role: 'user', content: chatInput };
    setChatHistory(prev => [...prev, userMsg]);
    setChatInput('');
    setIsChatLoading(true);
    try {
      const response = await geminiService.chatAssistant(chatHistory, chatInput);
      setChatHistory(prev => [...prev, { role: 'assistant', content: response || 'Tôi đang suy nghĩ...' }]);
    } catch (error) {
      setChatHistory(prev => [...prev, { role: 'assistant', content: 'Lỗi kết nối AI.' }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden">
      {/* Header */}
      <header className="h-16 border-b border-white/5 bg-[#0b0f1a]/80 backdrop-blur-xl px-6 flex items-center justify-between z-50">
        <div className="flex items-center gap-4">
          <div className="p-2 bg-indigo-600 rounded-xl shadow-lg shadow-indigo-600/20"><Infinity className="w-5 h-5 text-white" /></div>
          <div>
            <h1 className="text-lg font-black text-white tracking-tighter uppercase">Omni <span className="text-indigo-400">Builder</span></h1>
            <div className="flex items-center gap-1.5 text-[8px] font-bold text-slate-500 uppercase tracking-widest italic">Visual Sync Engine 2.1</div>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <button 
            onClick={() => autoRefineAllVisuals()} 
            disabled={syncingBlocks.size > 0 || state.blocks.length === 0}
            className="flex items-center gap-2 px-6 py-2 bg-amber-600/10 hover:bg-amber-600/20 text-amber-500 rounded-full font-black text-xs transition-all border border-amber-500/20 active:scale-95 disabled:opacity-30"
          >
            {syncingBlocks.size > 0 ? <RefreshCw className="w-3.5 h-3.5 animate-spin" /> : <ImageIcon className="w-3.5 h-3.5" />}
            {syncingBlocks.size > 0 ? `SYNCING (${syncingBlocks.size})` : 'REFINE ALL VISUALS'}
          </button>
