import { GoogleGenAI, Type } from "@google/genai";
import { Block } from "../types";

const TEXT_MODEL = 'gemini-3-pro-preview';
const IMAGE_MODEL = 'gemini-3-pro-image-preview';

export class GeminiService {
  private getAI() {
    // Luôn khởi tạo instance mới để lấy API Key cập nhật nhất từ context
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  private async handlePotentialKeyError(error: any): Promise<never> {
    if (error?.message?.includes("Requested entity was not found.") || error?.message?.includes("API_KEY_INVALID")) {
      // @ts-ignore
      if (window.aistudio) await window.aistudio.openSelectKey();
    }
    throw error;
  }

  async parseToBlocks(prompt: string, existingHtml?: string): Promise<{ blocks: Block[], globalCss: string }> {
    const ai = this.getAI();
    const systemInstruction = `
      You are the "Omni-Builder Architect". Transform requests into a modular website structure.
      Rules:
      1. Break into logical blocks using Tailwind CSS.
      2. For EVERY image location, use an <img> tag with a 'data-ai-prompt' attribute containing a highly detailed visual description in English.
      3. Example: <img data-ai-prompt="cinematic 8k photo of a futuristic electric car driving through a neon city at night, rain on asphalt" class="w-full h-full object-cover rounded-2xl" src="" />
      4. Do NOT use external URLs like pollinations.ai. Leave 'src' empty.
      5. Return ONLY a JSON object with 'blocks' and 'globalCss'.
    `;

    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `Input Request: ${prompt}\n\nExisting HTML: ${existingHtml || 'None'}`,
        config: {
          systemInstruction,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              blocks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    id: { type: Type.STRING },
                    type: { type: Type.STRING },
                    name: { type: Type.STRING },
                    html: { type: Type.STRING }
                  },
                  required: ["id", "type", "name", "html"]
                }
              },
              globalCss: { type: Type.STRING }
            },
            required: ["blocks", "globalCss"]
          }
        }
      });

      return JSON.parse(response.text || '{"blocks": [], "globalCss": ""}');
    } catch (e) {
      return this.handlePotentialKeyError(e);
    }
  }

  async generateAiImage(prompt: string): Promise<string> {
    const ai = this.getAI();
    try {
      const response = await ai.models.generateContent({
        model: IMAGE_MODEL,
        contents: {
          parts: [{ text: `${prompt}, high resolution, commercial photography, studio lighting, 8k, highly detailed` }]
        },
        config: {
          imageConfig: {
            aspectRatio: "16:9",
            imageSize: "1K"
          }
        }
      });

      const candidate = response.candidates?.[0];
      if (!candidate) throw new Error("No image generated");

      for (const part of candidate.content.parts) {
        if (part.inlineData) {
          return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
      throw new Error("No image data found in response");
    } catch (e) {
      console.error("Gemini Image Generation Error:", e);
      return this.handlePotentialKeyError(e);
    }
  }

  async chatAssistant(history: { role: string, content: string }[], message: string) {
    const ai = this.getAI();
    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: [
          ...history.map(h => ({ role: h.role === 'user' ? 'user' : 'model', parts: [{ text: h.content }] })),
          { role: 'user', parts: [{ text: message }] }
        ],
        config: {
          systemInstruction: "You are a senior UI/UX designer. Assist users with building their landing pages. Suggest high-quality image prompts."
        }
      });
      return response.text;
    } catch (e) {
      return this.handlePotentialKeyError(e);
    }
  }
}

export const geminiService = new GeminiService();

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { geminiService } from './services/geminiService';
import { Block, OmniState, ChatMessage } from './types';
import { 
  Sparkles, Zap, MessageSquare, Download, CheckCircle2, 
  Loader2, Eye, Code2, Infinity, Rocket, 
  Smartphone, Tablet as TabletIcon, Monitor, Plus, Trash2, 
  Save, RefreshCw, X, ChevronRight, Layout, Palette, Type,
  Share2, ShieldCheck, DownloadCloud, Image as ImageIcon, AlertCircle,
  Key
} from 'lucide-react';

const INITIAL_STATE: OmniState = {
  projectName: "AI Enterprise Landing",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#6366f1",
  fontFamily: "Inter"
};

export default function App() {
  const [state, setState] = useState<OmniState>(INITIAL_STATE);
  const [isProcessing, setIsProcessing] = useState(false);
  const [syncingBlocks, setSyncingBlocks] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'tablet' | 'desktop'>('desktop');
  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);

  const previewRefs = {
    mobile: useRef<HTMLIFrameElement>(null),
    tablet: useRef<HTMLIFrameElement>(null),
    desktop: useRef<HTMLIFrameElement>(null)
  };

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
        // @ts-ignore
        await window.aistudio.openSelectKey();
      }
    };
    checkKey();
  }, []);

  const fullHtml = useMemo(() => {
    const content = state.blocks.map(b => b.html).join('\n');
    return `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <script src="https://cdn.tailwindcss.com"></script>
        <link href="https://fonts.googleapis.com/css2?family=${state.fontFamily}:wght@400;700&display=swap" rel="stylesheet">
        <style>
          body { font-family: '${state.fontFamily}', sans-serif; scroll-behavior: smooth; margin: 0; padding: 0; }
          :root { --accent: ${state.accentColor}; }
          ${state.globalCss}
          img:not([src]), img[src=""] {
            background: #1e293b;
            min-height: 300px;
            display: flex;
            align-items: center;
            justify-content: center;
            position: relative;
            content: "Generating Image...";
            color: #475569;
            font-size: 10px;
            text-transform: uppercase;
            letter-spacing: 0.1em;
          }
        </style>
      </head>
      <body>
        ${content || '<div class="h-screen flex items-center justify-center text-gray-700 font-bold uppercase tracking-widest bg-slate-900">Workspace Empty</div>'}
      </body>
      </html>
    `;
  }, [state, previewKey]);

  const processBlockImages = async (targetBlocks?: Block[]) => {
    const blocksToProcess = targetBlocks || state.blocks;
    if (blocksToProcess.length === 0) return;

    for (const block of blocksToProcess) {
      const parser = new DOMParser();
      const doc = parser.parseFromString(block.html, 'text/html');
      const imgTags = Array.from(doc.querySelectorAll('img[data-ai-prompt]'));

      if (imgTags.length === 0) continue;

      setSyncingBlocks(prev => new Set(prev).add(block.id));

      let updatedHtml = block.html;
      for (const img of imgTags) {
        const prompt = img.getAttribute('data-ai-prompt');
        if (prompt) {
          try {
            const base64Image = await geminiService.generateAiImage(prompt);
            // Cập nhật trực tiếp vào HTML của block
            updatedHtml = updatedHtml.replace(
              img.outerHTML,
              img.outerHTML.replace('src=""', `src="${base64Image}"`).replace(`data-ai-prompt="${prompt}"`, '')
            );

            // Cập nhật state ngay lập tức để người dùng thấy ảnh hiện ra dần dần
            setState(prev => ({
              ...prev,
              blocks: prev.blocks.map(b => b.id === block.id ? { ...b, html: updatedHtml } : b)
            }));
            setPreviewKey(k => k + 1);
          } catch (err) {
            console.error("Image generation failed for prompt:", prompt, err);
          }
        }
      }

      setSyncingBlocks(prev => {
        const next = new Set(prev);
        next.delete(block.id);
        return next;
      });

      await new Promise(r => setTimeout(r, 500));
    }
  };

  const handleBuild = async () => {
    if (!inputSource.trim()) return;
    setIsProcessing(true);
    try {
      const result = await geminiService.parseToBlocks(inputSource);
      setState(prev => ({
        ...prev,
        blocks: result.blocks,
        globalCss: result.globalCss,
        selectedBlockId: result.blocks[0]?.id || null
      }));
      setViewMode('preview');
      setPreviewKey(k => k + 1);

      // Khởi chạy hàng đợi tạo ảnh Gemini Pro Image
      setTimeout(() => processBlockImages(result.blocks), 1000);
    } catch (e) {
      alert("Xây dựng thất bại. Vui lòng kiểm tra API Key và quyền truy cập Gemini Pro Image.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleBlockChange = (id: string, newHtml: string) => {
    setState(prev => ({
      ...prev,
      blocks: prev.blocks.map(b => b.id === id ? { ...b, html: newHtml } : b)
    }));
  };

  const handleSyncScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const scrollTop = e.currentTarget.scrollTop;
    Object.values(previewRefs).forEach(ref => {
      if (ref.current && ref.current.contentWindow) {
        ref.current.contentWindow.scrollTo(0, scrollTop);
      }
    });
  };

  const openKeyDialog = async () => {
    // @ts-ignore
    if (window.aistudio) await window.aistudio.openSelectKey();
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden">
      <header className="h-16 border-b border-white/5 bg-[#0b0f1a]/95 backdrop-blur-xl px-6 flex items-center justify-between z-50">
        <div className="flex items-center gap-4">
          <div className="p-2 bg-indigo-600 rounded-xl shadow-lg shadow-indigo-600/30"><Infinity className="w-5 h-5 text-white" /></div>
          <div>
            <h1 className="text-lg font-black text-white tracking-tighter uppercase">Omni <span className="text-indigo-400">Gen-3</span></h1>
            <div className="flex items-center gap-1.5 text-[8px] font-bold text-emerald-500 uppercase tracking-widest italic animate-pulse">Gemini Pro Image Engine Active</div>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <button 
            onClick={openKeyDialog}
            className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-full font-black text-[10px] transition-all border border-white/5"
          >
            <Key className="w-3 h-3" /> API KEY
          </button>

          <div className="h-6 w-px bg-white/5 mx-2"></div>

          <button 
            onClick={() => processBlockImages()} 
            disabled={syncingBlocks.size > 0 || state.blocks.length === 0}
            className="flex items-center gap-2 px-6 py-2 bg-amber-600/10 hover:bg-amber-600/20 text-amber-500 rounded-full font-black text-xs transition-all border border-amber-500/20 active:scale-95 disabled:opacity-30"
          >
            {syncingBlocks.size > 0 ? <RefreshCw className="w-3.5 h-3.5 animate-spin" /> : <Sparkles className="w-3.5 h-3.5" />}
            {syncingBlocks.size > 0 ? `IMAGINING (${syncingBlocks.size})...` : 'GENERATE AI IMAGES'}
          </button>

          <button onClick={() => setViewMode(viewMode === 'edit' ? 'preview' : 'edit')} className="flex items-center gap-2 px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-full font-black text-xs transition-all shadow-lg shadow-indigo-600/20 active:scale-95">
            {viewMode === 'edit' ? <Eye className="w-3.5 h-3.5" /> : <Code2 className="w-3.5 h-3.5" />}
            {viewMode === 'edit' ? 'PREVIEW MODE' : 'EDITOR MODE'}
          </button>

          <button onClick={() => {
            const blob = new Blob([fullHtml], { type: 'text/html' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `gemini-pro-site.html`;
            a.click();
          }} className="flex items-center gap-2 px-6 py-2 bg-emerald-600 hover:bg-emerald-500 text-white rounded-full font-black text-xs transition-all shadow-xl shadow-emerald-600/20 active:scale-95">
            <DownloadCloud className="w-3.5 h-3.5" /> EXPORT
          </button>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden">
        <aside className="w-72 bg-[#0b0f1a] border-r border-white/5 flex flex-col p-6 gap-6">
          <div className="flex-1 flex flex-col overflow-hidden">
            <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2 mb-4"><Layout className="w-3 h-3" /> Page Modules</h3>
            <div className="space-y-2 overflow-y-auto pr-2 custom-scrollbar flex-1">
              {state.blocks.map(block => (
                <div 
                  key={block.id} 
                  onClick={() => setState(prev => ({ ...prev, selectedBlockId: block.id }))}
                  className={`group flex items-center justify-between p-4 rounded-2xl cursor-pointer transition-all ${state.selectedBlockId === block.id ? 'bg-indigo-600/10 border border-indigo-500/30 text-white shadow-xl' : 'hover:bg-white/5 text-slate-500'}`}
                >
                  <div className="flex items-center gap-3">
                    {syncingBlocks.has(block.id) ? (
                      <div className="relative">
                        <Loader2 className="w-4 h-4 text-amber-500 animate-spin" />
                        <Sparkles className="absolute -top-1 -right-1 w-2 h-2 text-amber-300 animate-pulse" />
                      </div>
                    ) : (
                      <CheckCircle2 className={`w-4 h-4 ${state.selectedBlockId === block.id ? 'text-indigo-400' : 'text-slate-700'}`} />
                    )}
                    <span className="text-[11px] font-black uppercase truncate tracking-tight">{block.name}</span>
                  </div>
                  <button onClick={(e) => { e.stopPropagation(); setState(prev => ({ ...prev, blocks: prev.blocks.filter(b => b.id !== block.id) })); }} className="opacity-0 group-hover:opacity-100 transition-opacity p-1 hover:text-red-400">
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                </div>
              ))}
              {state.blocks.length === 0 && (
                <div className="flex flex-col items-center justify-center py-10 opacity-20">
                  <Rocket className="w-10 h-10 mb-4" />
                  <span className="text-[10px] font-bold uppercase tracking-widest italic text-center">Empty State</span>
                </div>
              )}
            </div>
          </div>

          <div className="h-48 bg-slate-900/50 rounded-3xl border border-white/5 p-4 flex flex-col gap-3">
             <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-widest">
               <ShieldCheck className="w-3 h-3 text-emerald-500" /> Image Status
             </div>
             <div className="flex-1 flex flex-col justify-center items-center gap-2 text-center">
                {syncingBlocks.size > 0 ? (
                  <>
                    <div className="text-[10px] text-amber-500 font-bold animate-pulse">GENERATING HIGH-RES IMAGES...</div>
                    <div className="w-full bg-slate-800 h-1.5 rounded-full overflow-hidden">
                      <div className="bg-amber-500 h-full animate-[shimmer_2s_infinite]" style={{ width: '60%' }}></div>
                    </div>
                  </>
                ) : (
                  <div className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">All Assets Synchronized</div>
                )}
             </div>
          </div>
        </aside>

        <section className="flex-1 flex flex-col overflow-hidden bg-[#020617]">
          {viewMode === 'edit' ? (
            <div className="flex-1 flex flex-col p-6 gap-6">
              <div className="flex-1 bg-[#0b0f1a] rounded-3xl border border-white/5 shadow-2xl flex flex-col overflow-hidden">
                <div className="p-4 bg-[#131929] border-b border-white/5 flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <Code2 className="w-4 h-4 text-indigo-400" />
                    <span className="text-[10px] font-black text-white uppercase tracking-widest">
                      {state.blocks.find(b => b.id === state.selectedBlockId)?.name || 'Design Canvas'}
                    </span>
                  </div>
                </div>
                {state.blocks.length > 0 ? (
                  <textarea
                    value={state.blocks.find(b => b.id === state.selectedBlockId)?.html || ''}
                    onChange={(e) => handleBlockChange(state.selectedBlockId!, e.target.value)}
                    className="flex-1 p-8 bg-transparent text-slate-300 code-font text-sm outline-none resize-none leading-relaxed selection:bg-indigo-500/30 custom-scrollbar"
                    placeholder="Modify block HTML..."
                  />
                ) : (
                  <div className="flex-1 flex flex-col items-center justify-center p-12 text-center">
                    <div className="relative mb-8">
                       <div className="w-24 h-24 bg-indigo-600/10 rounded-full animate-pulse flex items-center justify-center">
                          <Zap className="w-12 h-12 text-indigo-500" />
                       </div>
                       <Sparkles className="absolute -top-2 -right-2 w-6 h-6 text-amber-500 animate-bounce" />
                    </div>
                    <h2 className="text-3xl font-black text-white mb-4 uppercase tracking-tighter italic">Launch Your Project</h2>
                    <textarea 
                      value={inputSource}
                      onChange={(e) => setInputSource(e.target.value)}
                      placeholder="Enter a prompt: 'Luxury Real Estate Landing Page with high-res property images'..."
                      className="w-full max-w-xl h-40 bg-slate-900 border border-white/10 rounded-2xl p-6 text-sm outline-none focus:border-indigo-500 mb-6 shadow-inner transition-all"
                    />
                    <button onClick={handleBuild} disabled={isProcessing} className="px-12 py-5 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest hover:scale-105 transition-all shadow-2xl shadow-indigo-600/30 active:scale-95 disabled:opacity-50">
                      {isProcessing ? 'SYNCHRONIZING CORE...' : 'INITIALIZE BUILD ENGINE'}
                    </button>
                    <p className="mt-6 text-[10px] text-slate-600 font-bold uppercase tracking-[0.2em]">Gemini 3 Pro + Gemini Image Engine 2025</p>
                  </div>
                )}
              </div>
            </div>
          ) : (
            <div className="flex-1 flex flex-col overflow-hidden">
              <div className="h-14 border-b border-white/5 bg-[#0b0f1a] px-6 flex items-center justify-center gap-8">
                <button onClick={() => setPreviewDevice('mobile')} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black tracking-widest transition-all ${previewDevice === 'mobile' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}><Smartphone className="w-3.5 h-3.5" /> MOBILE</button>
                <button onClick={() => setPreviewDevice('tablet')} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black tracking-widest transition-all ${previewDevice === 'tablet' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}><TabletIcon className="w-3.5 h-3.5" /> TABLET</button>
                <button onClick={() => setPreviewDevice('desktop')} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black tracking-widest transition-all ${previewDevice === 'desktop' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}><Monitor className="w-3.5 h-3.5" /> DESKTOP</button>
              </div>
              <div 
                className="flex-1 overflow-y-auto p-12 bg-[#020617] flex gap-12 justify-center items-start scroll-smooth custom-scrollbar relative"
                onScroll={handleSyncScroll}
              >
                <div key={previewKey} className={`flex-shrink-0 bg-white shadow-[0_0_100px_rgba(0,0,0,0.5)] transition-all duration-700 rounded-sm overflow-hidden border border-white/5 ${previewDevice === 'desktop' ? 'w-[1200px]' : previewDevice === 'tablet' ? 'w-[768px] border-8 border-slate-900' : 'w-[375px] rounded-[3.5rem] border-[12px] border-slate-900'}`}>
                  <iframe ref={previewRefs.desktop} title="Live View" srcDoc={fullHtml} className={`w-full ${previewDevice === 'desktop' ? 'h-[800px]' : previewDevice === 'tablet' ? 'h-[1024px]' : 'h-[667px]'} border-none bg-slate-900 transition-opacity duration-500`} sandbox="allow-scripts" />
                </div>
              </div>
            </div>
          )}
        </section>

        <aside className="w-72 bg-[#0b0f1a] border-l border-white/5 flex flex-col p-6 gap-6">
           <div>
            <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2 mb-4"><Palette className="w-3 h-3" /> Brand Attributes</h3>
            <div className="space-y-4">
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Primary Hue</label>
                <div className="flex items-center gap-3 bg-slate-950 p-2 rounded-2xl border border-white/10">
                  <input type="color" value={state.accentColor} onChange={(e) => setState(prev => ({ ...prev, accentColor: e.target.value }))} className="w-10 h-10 bg-transparent border-none cursor-pointer rounded-xl overflow-hidden" />
                  <span className="text-xs font-mono font-black text-white">{state.accentColor.toUpperCase()}</span>
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Typography</label>
                <select value={state.fontFamily} onChange={(e) => setState(prev => ({ ...prev, fontFamily: e.target.value }))} className="w-full bg-slate-950 border border-white/10 rounded-2xl p-4 text-xs font-black outline-none focus:border-indigo-500 transition-all text-white">
                  <option value="Inter">INTER (SANS)</option>
                  <option value="Roboto">ROBOTO</option>
                  <option value="Playfair Display">PLAYFAIR (SERIF)</option>
                  <option value="Fira Code">FIRA CODE (MONO)</option>
                </select>
              </div>
            </div>
          </div>

          <div className="mt-auto p-5 bg-indigo-600/5 border border-indigo-500/20 rounded-[2rem] relative overflow-hidden group">
             <div className="absolute -top-4 -right-4 p-4 opacity-5 group-hover:scale-150 transition-transform"><Infinity className="w-20 h-20" /></div>
             <div className="flex items-center gap-3 mb-3 relative z-10">
                <ShieldCheck className="w-4 h-4 text-emerald-400" />
                <span className="text-[10px] font-black text-white uppercase tracking-tighter">Enterprise Standard</span>
             </div>
             <p className="text-[10px] text-slate-500 leading-relaxed italic relative z-10 font-medium">
               Toàn bộ hình ảnh được tạo dưới dạng Base64 độ phân giải cao (1K). Khi Export, file của bạn sẽ là một gói duy nhất, sẵn sàng hoạt động mà không cần mạng.
             </p>
          </div>
        </aside>
      </main>

      {isProcessing && (
        <div className="absolute inset-0 bg-slate-950/98 backdrop-blur-3xl z-[100] flex flex-col items-center justify-center p-10 text-center animate-in fade-in duration-700">
          <div className="relative mb-16 scale-150">
            <div className="w-20 h-20 border-2 border-indigo-500/10 rounded-full animate-ping"></div>
            <div className="absolute inset-0 w-20 h-20 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin [animation-duration:0.6s]"></div>
            <div className="absolute inset-0 m-auto w-8 h-8 flex items-center justify-center">
               <Zap className="w-6 h-6 text-indigo-500 animate-pulse" />
            </div>
          </div>
          <h2 className="text-4xl font-black text-white mb-6 tracking-tighter uppercase italic">Constructing Architecture...</h2>
          <div className="flex items-center gap-3 text-slate-500 text-xs font-black uppercase tracking-[0.3em] animate-pulse">
            <Sparkles className="w-4 h-4 text-amber-500" /> GEMINI PRO INTELLIGENCE ACTIVE <Sparkles className="w-4 h-4 text-amber-500" />
          </div>
        </div>
      )}
    </div>
  );
}

export interface Block {
  id: string;
  type: string;
  name: string;
  html: string;
  css?: string;
}

export interface LogEntry {
  id: string;
  timestamp: string;
  type: 'info' | 'success' | 'error' | 'warning';
  message: string;
  details?: string;
}

export interface OmniState {
  projectName: string;
  blocks: Block[];
  selectedBlockId: string | null;
  globalCss: string;
  accentColor: string;
  fontFamily: string;
  logs: LogEntry[];
}

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
}

export interface GeneratedImage {
  url: string;
  prompt: string;
}

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { geminiService } from './services/geminiService';
import { Block, OmniState, ChatMessage, LogEntry } from './types';
import { 
  Sparkles, Zap, MessageSquare, Download, CheckCircle2, 
  Loader2, Eye, Code2, Infinity, Rocket, 
  Smartphone, Tablet as TabletIcon, Monitor, Plus, Trash2, 
  Save, RefreshCw, X, ChevronRight, Layout, Palette, Type,
  Share2, ShieldCheck, DownloadCloud, Image as ImageIcon, AlertCircle,
  Key, Terminal as TerminalIcon, Bug, History, Trash
} from 'lucide-react';

const INITIAL_STATE: OmniState = {
  projectName: "AI Enterprise Landing",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#6366f1",
  fontFamily: "Inter",
  logs: []
};

export default function App() {
  const [state, setState] = useState<OmniState>(INITIAL_STATE);
  const [isProcessing, setIsProcessing] = useState(false);
  const [syncingBlocks, setSyncingBlocks] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'tablet' | 'desktop'>('desktop');
  const [chatInput, setChatInput] = useState('');
  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
  const [isChatLoading, setIsChatLoading] = useState(false);
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);

  const previewRefs = {
    mobile: useRef<HTMLIFrameElement>(null),
    tablet: useRef<HTMLIFrameElement>(null),
    desktop: useRef<HTMLIFrameElement>(null)
  };

  const addLog = (type: LogEntry['type'], message: string, details?: string) => {
    const newLog: LogEntry = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toLocaleTimeString(),
      type,
      message,
      details
    };
    setState(prev => ({
      ...prev,
      logs: [newLog, ...prev.logs].slice(0, 100) // Keep last 100 logs
    }));
  };

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
        addLog('warning', 'API Key chưa được chọn. Vui lòng chọn key để tiếp tục.');
        // @ts-ignore
        await window.aistudio.openSelectKey();
      } else {
        addLog('success', 'Gemini API Engine đã sẵn sàng.');
      }
    };
    checkKey();
  }, []);

  const fullHtml = useMemo(() => {
    const content = state.blocks.map(b => b.html).join('\n');
    return `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <script src="https://cdn.tailwindcss.com"></script>
        <link href="https://fonts.googleapis.com/css2?family=${state.fontFamily}:wght@400;700&display=swap" rel="stylesheet">
        <style>
          body { font-family: '${state.fontFamily}', sans-serif; scroll-behavior: smooth; margin: 0; padding: 0; }
          :root { --accent: ${state.accentColor}; }
          ${state.globalCss}
          img:not([src]), img[src=""] {
            background: #1e293b;
            min-height: 300px;
            display: flex;
            align-items: center;
            justify-content: center;
            position: relative;
            content: "Generating Image...";
            color: #475569;
            font-size: 10px;
            text-transform: uppercase;
            letter-spacing: 0.1em;
          }
        </style>
      </head>
      <body>
        ${content || '<div class="h-screen flex items-center justify-center text-gray-700 font-bold uppercase tracking-widest bg-slate-900">Workspace Empty</div>'}
      </body>
      </html>
    `;
  }, [state, previewKey]);

  const processBlockImages = async (targetBlocks?: Block[]) => {
    const blocksToProcess = targetBlocks || state.blocks;
    if (blocksToProcess.length === 0) return;

    addLog('info', `Bắt đầu xử lý hình ảnh cho ${blocksToProcess.length} blocks...`);

    for (const block of blocksToProcess) {
      const parser = new DOMParser();
      const doc = parser.parseFromString(block.html, 'text/html');
      const imgTags = Array.from(doc.querySelectorAll('img[data-ai-prompt]'));

      if (imgTags.length === 0) continue;

      setSyncingBlocks(prev => new Set(prev).add(block.id));
      addLog('info', `Đang tạo ảnh cho block: ${block.name} (${imgTags.length} ảnh)`);

      let updatedHtml = block.html;
      for (const img of imgTags) {
        const prompt = img.getAttribute('data-ai-prompt');
        if (prompt) {
          try {
            const base64Image = await geminiService.generateAiImage(prompt);
            updatedHtml = updatedHtml.replace(
              img.outerHTML,
              img.outerHTML.replace('src=""', `src="${base64Image}"`).replace(`data-ai-prompt="${prompt}"`, '')
            );

            setState(prev => ({
              ...prev,
              blocks: prev.blocks.map(b => b.id === block.id ? { ...b, html: updatedHtml } : b)
            }));
            setPreviewKey(k => k + 1);
            addLog('success', `Đã tạo ảnh thành công cho block ${block.name}`, `Prompt: ${prompt.substring(0, 50)}...`);
          } catch (err: any) {
            addLog('error', `Lỗi tạo ảnh Gemini Pro Image: ${err.message}`, `Prompt: ${prompt}`);
          }
        }
      }

      setSyncingBlocks(prev => {
        const next = new Set(prev);
        next.delete(block.id);
        return next;
      });

      await new Promise(r => setTimeout(r, 500));
    }
    addLog('success', 'Hoàn tất quy trình xử lý tài nguyên hình ảnh.');
  };

  const handleBuild = async () => {
    if (!inputSource.trim()) return;
    setIsProcessing(true);
    addLog('info', 'Bắt đầu khởi tạo kiến trúc trang web với Gemini-3-Pro...');

    try {
      const result = await geminiService.parseToBlocks(inputSource);
      setState(prev => ({
        ...prev,
        blocks: result.blocks,
        globalCss: result.globalCss,
        selectedBlockId: result.blocks[0]?.id || null
      }));
      setViewMode('preview');
      setPreviewKey(k => k + 1);

      addLog('success', `Đã tạo thành công ${result.blocks.length} module cấu trúc.`);

      // Khởi chạy hàng đợi tạo ảnh Gemini Pro Image
      setTimeout(() => processBlockImages(result.blocks), 1000);
    } catch (e: any) {
      addLog('error', 'Xây dựng cấu trúc thất bại', e.message);
      alert("Xây dựng thất bại. Vui lòng kiểm tra Developer Log.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleBlockChange = (id: string, newHtml: string) => {
    setState(prev => ({
      ...prev,
      blocks: prev.blocks.map(b => b.id === id ? { ...b, html: newHtml } : b)
    }));
  };

  const handleSyncScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const scrollTop = e.currentTarget.scrollTop;
    Object.values(previewRefs).forEach(ref => {
      if (ref.current && ref.current.contentWindow) {
        ref.current.contentWindow.scrollTo(0, scrollTop);
      }
    });
  };

  const openKeyDialog = async () => {
    addLog('info', 'Mở hội thoại chọn API Key...');
    // @ts-ignore
    if (window.aistudio) await window.aistudio.openSelectKey();
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden relative">
      <header className="h-16 border-b border-white/5 bg-[#0b0f1a]/95 backdrop-blur-xl px-6 flex items-center justify-between z-50">
        <div className="flex items-center gap-4">
          <div className="p-2 bg-indigo-600 rounded-xl shadow-lg shadow-indigo-600/30"><Infinity className="w-5 h-5 text-white" /></div>
          <div>
            <h1 className="text-lg font-black text-white tracking-tighter uppercase">Omni <span className="text-indigo-400">Gen-3</span></h1>
            <div className="flex items-center gap-1.5 text-[8px] font-bold text-emerald-500 uppercase tracking-widest italic animate-pulse">Gemini Pro Image Engine Active</div>
          </div>
        </div>

        <div className="flex items-center gap-3">
