              >
                <div key={previewKey} className={`flex-shrink-0 bg-white shadow-[0_0_100px_rgba(0,0,0,0.5)] transition-all duration-700 rounded-sm overflow-hidden border border-white/5 ${previewDevice === 'desktop' ? 'w-[1200px]' : previewDevice === 'tablet' ? 'w-[768px] border-8 border-slate-900' : 'w-[375px] rounded-[3.5rem] border-[12px] border-slate-900'}`}>
                  <iframe ref={previewRefs.desktop} title="Live View" srcDoc={fullHtml} className={`w-full ${previewDevice === 'desktop' ? 'h-[800px]' : previewDevice === 'tablet' ? 'h-[1024px]' : 'h-[667px]'} border-none bg-slate-900 transition-opacity duration-500`} sandbox="allow-scripts" />
                </div>
              </div>

              {/* Collapsible Terminal */}
              {showTerminal && (
                <div className="absolute bottom-0 left-0 right-0 h-64 bg-[#0b0f1a] border-t border-white/10 z-[60] flex flex-col shadow-2xl animate-in slide-in-from-bottom duration-300">
                  <div className="h-10 bg-[#131929] border-b border-white/5 flex items-center justify-between px-6">
                    <div className="flex items-center gap-3">
                      <TerminalIcon className="w-3.5 h-3.5 text-indigo-400" />
                      <span className="text-[10px] font-black text-white uppercase tracking-widest">Developer Engine Console</span>
                    </div>
                    <div className="flex items-center gap-3">
                       <button onClick={() => setState(prev => ({ ...prev, logs: [] }))} className="p-1.5 hover:bg-white/5 rounded-lg text-slate-500 hover:text-red-400 transition-colors" title="Clear Console"><Trash className="w-3.5 h-3.5" /></button>
                       <button onClick={() => setShowTerminal(false)} className="p-1.5 hover:bg-white/5 rounded-lg text-slate-500 hover:text-white transition-colors"><X className="w-3.5 h-3.5" /></button>
                    </div>
                  </div>
                  <div className="flex-1 overflow-y-auto p-4 space-y-2 code-font custom-scrollbar bg-slate-950">
                    {state.logs.length > 0 ? state.logs.map(log => (
                      <div key={log.id} className="text-[11px] flex gap-4 hover:bg-white/5 p-1 rounded transition-colors group">
                        <span className="text-slate-600 font-bold shrink-0">[{log.timestamp}]</span>
                        <span className={`font-black uppercase shrink-0 w-16 ${
                          log.type === 'error' ? 'text-red-500' : 
                          log.type === 'success' ? 'text-emerald-500' : 
                          log.type === 'warning' ? 'text-amber-500' : 'text-blue-400'
                        }`}>{log.type}</span>
                        <div className="flex-1">
                          <div className="text-slate-300 font-medium">{log.message}</div>
                          {log.details && <div className="text-slate-600 mt-1 italic group-hover:text-slate-500 transition-colors">{log.details}</div>}
                        </div>
                      </div>
                    )) : (
                      <div className="h-full flex items-center justify-center opacity-20 italic text-xs uppercase tracking-widest font-black">Console Idle... No active events.</div>
                    )}
                  </div>
                </div>
              )}
            </div>
          )}
        </section>

        <aside className="w-72 bg-[#0b0f1a] border-l border-white/5 flex flex-col p-6 gap-6">
           <div>
            <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2 mb-4"><Palette className="w-3 h-3" /> Brand Attributes</h3>
            <div className="space-y-4">
              <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Primary Hue</label>
                <div className="flex items-center gap-3 bg-slate-950 p-2 rounded-2xl border border-white/10">
                  <input type="color" value={state.accentColor} onChange={(e) => setState(prev => ({ ...prev, accentColor: e.target.value }))} className="w-10 h-10 bg-transparent border-none cursor-pointer rounded-xl overflow-hidden" />
                  <span className="text-xs font-mono font-black text-white">{state.accentColor.toUpperCase()}</span>
                </div>
