              <div className="space-y-2">
                <label className="text-[10px] font-bold text-slate-500 uppercase">Typography</label>
                <select value={state.fontFamily} onChange={(e) => setState(prev => ({ ...prev, fontFamily: e.target.value }))} className="w-full bg-slate-950 border border-white/10 rounded-2xl p-4 text-xs font-black outline-none focus:border-indigo-500 transition-all text-white">
                  <option value="Inter">INTER (SANS)</option>
                  <option value="Roboto">ROBOTO</option>
                  <option value="Playfair Display">PLAYFAIR (SERIF)</option>
                  <option value="Fira Code">FIRA CODE (MONO)</option>
                </select>
