                  <button onClick={(e) => { e.stopPropagation(); setState(prev => ({ ...prev, blocks: prev.blocks.filter(b => b.id !== block.id) })); addLog('warning', `Đã xóa module: ${block.name}`); }} className="opacity-0 group-hover:opacity-100 transition-opacity p-1 hover:text-red-400">
                    <Trash2 className="w-3.5 h-3.5" />
