                <button onClick={() => setPreviewDevice('mobile')} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black tracking-widest transition-all ${previewDevice === 'mobile' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-500 hover:text-slate-300'}`}><Smartphone className="w-3.5 h-3.5" /> MOBILE</button>
                <button onClick={() => setPreviewDevice('tablet')} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black tracking-widest transition-all ${previewDevice === 'tablet' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-500 hover:text-slate-300'}`}><TabletIcon className="w-3.5 h-3.5" /> TABLET</button>
                <button onClick={() => setPreviewDevice('desktop')} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black tracking-widest transition-all ${previewDevice === 'desktop' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'text-slate-500 hover:text-slate-300'}`}><Monitor className="w-3.5 h-3.5" /> DESKTOP</button>
              </div>
              <div 
                className="flex-1 overflow-y-auto p-12 bg-[#020617] flex gap-12 justify-center items-start scroll-smooth custom-scrollbar relative"
                onScroll={handleSyncScroll}
              >
                <div key={previewKey} className={`flex-shrink-0 bg-white shadow-[0_0_100px_rgba(0,0,0,0.7)] transition-all duration-700 rounded-sm overflow-hidden border border-white/5 ${previewDevice === 'desktop' ? 'w-[1200px]' : previewDevice === 'tablet' ? 'w-[768px] border-8 border-slate-900' : 'w-[375px] rounded-[3.5rem] border-[12px] border-slate-900'}`}>
                  <iframe ref={previewRefs.desktop} title="Live View" srcDoc={fullHtml} className={`w-full ${previewDevice === 'desktop' ? 'h-[800px]' : previewDevice === 'tablet' ? 'h-[1024px]' : 'h-[667px]'} border-none bg-slate-950 transition-opacity duration-500`} sandbox="allow-scripts" />
                </div>
              </div>

              {showTerminal && (
                <div className="absolute bottom-0 left-0 right-0 h-72 bg-[#0b0f1a] border-t border-white/10 z-[60] flex flex-col shadow-2xl animate-in slide-in-from-bottom duration-300">
                  <div className="h-10 bg-[#131929] border-b border-white/5 flex items-center justify-between px-6">
                    <div className="flex items-center gap-3">
                      <TerminalIcon className="w-3.5 h-3.5 text-indigo-400" />
                      <span className="text-[10px] font-black text-white uppercase tracking-widest">Developer Engine Console</span>
                    </div>
                    <div className="flex items-center gap-3">
                       <button onClick={() => setState(prev => ({ ...prev, logs: [] }))} className="p-1.5 hover:bg-white/5 rounded-lg text-slate-500 hover:text-red-400 transition-colors" title="Clear Console"><Trash className="w-3.5 h-3.5" /></button>
                       <button onClick={() => setShowTerminal(false)} className="p-1.5 hover:bg-white/5 rounded-lg text-slate-500 hover:text-white transition-colors"><X className="w-3.5 h-3.5" /></button>
                    </div>
                  </div>
                  <div className="flex-1 overflow-y-auto p-4 space-y-2 code-font custom-scrollbar bg-slate-950">
                    {state.logs.length > 0 ? state.logs.map(log => (
                      <div key={log.id} className="text-[11px] flex gap-4 hover:bg-white/5 p-1.5 rounded transition-colors group border-l-2 border-transparent hover:border-indigo-500/50">
                        <span className="text-slate-600 font-bold shrink-0 w-20">[{log.timestamp}]</span>
                        <span className={`font-black uppercase shrink-0 w-16 ${
                          log.type === 'error' ? 'text-red-500' : 
                          log.type === 'success' ? 'text-emerald-500' : 
                          log.type === 'warning' ? 'text-amber-500' : 'text-blue-400'
