}

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { geminiService } from './services/geminiService';
import { Block, OmniState, ChatMessage, LogEntry } from './types';
import { 
  Sparkles, Zap, MessageSquare, Download, CheckCircle2, 
  Loader2, Eye, Code2, Infinity, Rocket, 
  Smartphone, Tablet as TabletIcon, Monitor, Plus, Trash2, 
  Save, RefreshCw, X, ChevronRight, Layout, Palette, Type,
  Share2, ShieldCheck, DownloadCloud, Image as ImageIcon, AlertCircle,
  Key, Terminal as TerminalIcon, Bug, History, Trash
} from 'lucide-react';

const INITIAL_STATE: OmniState = {
  projectName: "AI Enterprise Landing",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#6366f1",
  fontFamily: "Inter",
  logs: []
};

export default function App() {
  const [state, setState] = useState<OmniState>(INITIAL_STATE);
  const [isProcessing, setIsProcessing] = useState(false);
  const [syncingBlocks, setSyncingBlocks] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'tablet' | 'desktop'>('desktop');
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);

  const previewRefs = {
    mobile: useRef<HTMLIFrameElement>(null),
    tablet: useRef<HTMLIFrameElement>(null),
    desktop: useRef<HTMLIFrameElement>(null)
  };

  const addLog = (type: LogEntry['type'], message: string, details?: string) => {
    const newLog: LogEntry = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toLocaleTimeString(),
      type,
      message,
      details
    };
    setState(prev => ({
      ...prev,
      logs: [newLog, ...prev.logs].slice(0, 100)
    }));
  };

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
        addLog('warning', 'API Key chưa được chọn. Vui lòng chọn key để tiếp tục.');
        // @ts-ignore
        await window.aistudio.openSelectKey();
      } else {
        addLog('success', 'Gemini API Engine đã sẵn sàng.');
      }
    };
    checkKey();
  }, []);

  const fullHtml = useMemo(() => {
    const content = state.blocks.map(b => b.html).join('\n');
    return `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <script src="https://cdn.tailwindcss.com"></script>
        <link href="https://fonts.googleapis.com/css2?family=${state.fontFamily}:wght@400;700&display=swap" rel="stylesheet">
        <style>
          body { font-family: '${state.fontFamily}', sans-serif; scroll-behavior: smooth; margin: 0; padding: 0; background-color: white; }
          :root { --accent: ${state.accentColor}; }
          ${state.globalCss}
          /* Placeholder CSS cải tiến: Không dùng thuộc tính content để tránh chặn ảnh thật */
          img:not([src]), img[src=""], img[src="about:blank"] {
            background-color: #1e293b;
            min-height: 240px;
            min-width: 240px;
            display: block;
            position: relative;
            background-image: linear-gradient(45deg, #0f172a 25%, transparent 25%, transparent 75%, #0f172a 75%, #0f172a), 
                              linear-gradient(45deg, #0f172a 25%, transparent 25%, transparent 75%, #0f172a 75%, #0f172a);
            background-size: 20px 20px;
            background-position: 0 0, 10px 10px;
          }
          /* Hiệu ứng khi đang tải */
          img[data-ai-prompt] {
            filter: grayscale(1) blur(2px);
            opacity: 0.5;
          }
        </style>
      </head>
      <body>
        ${content || '<div class="h-screen flex items-center justify-center text-gray-500 font-bold uppercase tracking-widest bg-slate-900">Workspace Empty</div>'}
      </body>
      </html>
    `;
  }, [state.blocks, state.accentColor, state.fontFamily, state.globalCss, previewKey]);

  const processBlockImages = async (targetBlocks?: Block[]) => {
    const blocksToProcess = targetBlocks || state.blocks;
    if (blocksToProcess.length === 0) return;

    addLog('info', `Bắt đầu hàng đợi đồng bộ ảnh AI cho ${blocksToProcess.length} blocks.`);

    for (const block of blocksToProcess) {
      const parser = new DOMParser();
      const doc = parser.parseFromString(block.html, 'text/html');
      const imgTags = Array.from(doc.querySelectorAll('img[data-ai-prompt]'));

      if (imgTags.length === 0) continue;

      setSyncingBlocks(prev => new Set(prev).add(block.id));
      addLog('info', `Đang vẽ ${imgTags.length} ảnh cho module: ${block.name}`);

      for (const img of imgTags) {
        const prompt = img.getAttribute('data-ai-prompt');
        if (prompt) {
          try {
            const base64Image = await geminiService.generateAiImage(prompt);

            // Cập nhật thuộc tính ảnh trực tiếp trên DOM node
            img.setAttribute('src', base64Image);
            img.removeAttribute('data-ai-prompt');

            // Lấy lại HTML đã cập nhật
            const updatedHtml = doc.body.innerHTML;

            setState(prev => ({
              ...prev,
              blocks: prev.blocks.map(b => b.id === block.id ? { ...b, html: updatedHtml } : b)
            }));

            // Cập nhật preview
            setPreviewKey(k => k + 1);
            addLog('success', `Đã nhúng ảnh (Base64 length: ${base64Image.length}) vào ${block.name}`);
          } catch (err: any) {
            addLog('error', `Lỗi tạo ảnh cho block ${block.name}`, err.message);
          }
        }
      }

      setSyncingBlocks(prev => {
        const next = new Set(prev);
        next.delete(block.id);
        return next;
      });

      await new Promise(r => setTimeout(r, 300));
    }
    addLog('success', 'Hoàn tất tất cả các tác vụ xử lý tài nguyên.');
  };

  const handleBuild = async () => {
    if (!inputSource.trim()) return;
    setIsProcessing(true);
    addLog('info', 'Đang yêu cầu Gemini xây dựng cấu trúc website...');

    try {
      const result = await geminiService.parseToBlocks(inputSource);
      setState(prev => ({
        ...prev,
        blocks: result.blocks,
        globalCss: result.globalCss,
        selectedBlockId: result.blocks[0]?.id || null
      }));
      setViewMode('preview');
      setPreviewKey(k => k + 1);

      addLog('success', `Đã dựng xong ${result.blocks.length} module.`);

      // Khởi động việc tạo ảnh ngay lập tức
      setTimeout(() => processBlockImages(result.blocks), 500);
    } catch (e: any) {
      addLog('error', 'Xây dựng thất bại', e.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleBlockChange = (id: string, newHtml: string) => {
    setState(prev => ({
      ...prev,
      blocks: prev.blocks.map(b => b.id === id ? { ...b, html: newHtml } : b)
    }));
  };

  const handleSyncScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const scrollTop = e.currentTarget.scrollTop;
    Object.values(previewRefs).forEach(ref => {
      if (ref.current && ref.current.contentWindow) {
        ref.current.contentWindow.scrollTo(0, scrollTop);
      }
    });
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden relative">
      <header className="h-16 border-b border-white/5 bg-[#0b0f1a]/95 backdrop-blur-xl px-6 flex items-center justify-between z-50">
        <div className="flex items-center gap-4">
          <div className="p-2 bg-indigo-600 rounded-xl shadow-lg shadow-indigo-600/30"><Infinity className="w-5 h-5 text-white" /></div>
          <div>
            <h1 className="text-lg font-black text-white tracking-tighter uppercase">Omni <span className="text-indigo-400">Gen-3</span></h1>
            <div className="flex items-center gap-1.5 text-[8px] font-bold text-emerald-500 uppercase tracking-widest italic animate-pulse">Gemini Pro Image Engine Active</div>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <button 
            onClick={() => setShowTerminal(!showTerminal)}
            className={`flex items-center gap-2 px-4 py-2 rounded-full font-black text-[10px] transition-all border ${showTerminal ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'bg-slate-800 border-white/5 text-slate-300 hover:bg-slate-700'}`}
          >
            <TerminalIcon className="w-3 h-3" /> {showTerminal ? 'CLOSE LOG' : 'DEV LOG'}
          </button>

          <button onClick={() => setViewMode(viewMode === 'edit' ? 'preview' : 'edit')} className="flex items-center gap-2 px-6 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-full font-black text-xs transition-all border border-white/5 active:scale-95">
            {viewMode === 'edit' ? <Eye className="w-3.5 h-3.5" /> : <Code2 className="w-3.5 h-3.5" />}
            {viewMode === 'edit' ? 'PREVIEW' : 'EDITOR'}
          </button>

          <button onClick={() => {
            const blob = new Blob([fullHtml], { type: 'text/html' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `omnigen-export.html`;
            a.click();
            addLog('success', 'Đã xuất file HTML hoàn chỉnh.');
          }} className="flex items-center gap-2 px-6 py-2 bg-emerald-600 hover:bg-emerald-500 text-white rounded-full font-black text-xs transition-all shadow-xl shadow-emerald-600/20 active:scale-95">
            <DownloadCloud className="w-3.5 h-3.5" /> EXPORT
          </button>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden">
        <aside className="w-64 bg-[#0b0f1a] border-r border-white/5 flex flex-col p-4 gap-4 shrink-0">
          <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2 mb-2"><Layout className="w-3 h-3" /> Page Modules</h3>
          <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar space-y-2">
            {state.blocks.map(block => (
              <div 
                key={block.id} 
                onClick={() => setState(prev => ({ ...prev, selectedBlockId: block.id }))}
                className={`group p-3 rounded-xl cursor-pointer transition-all border ${state.selectedBlockId === block.id ? 'bg-indigo-600/10 border-indigo-500/30 text-white shadow-lg' : 'bg-transparent border-transparent hover:bg-white/5 text-slate-500'}`}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 min-w-0">
                    {syncingBlocks.has(block.id) ? (
                      <Loader2 className="w-3 h-3 text-amber-500 animate-spin shrink-0" />
                    ) : (
                      <CheckCircle2 className={`w-3 h-3 shrink-0 ${state.selectedBlockId === block.id ? 'text-indigo-400' : 'text-slate-700'}`} />
                    )}
                    <span className="text-[10px] font-black uppercase truncate tracking-tight">{block.name}</span>
                  </div>
                  <button onClick={(e) => { e.stopPropagation(); setState(prev => ({ ...prev, blocks: prev.blocks.filter(b => b.id !== block.id) })); }} className="opacity-0 group-hover:opacity-100 p-1 hover:text-red-400"><Trash2 className="w-3 h-3" /></button>
                </div>
              </div>
            ))}
          </div>

          <div className="p-4 bg-slate-900/50 rounded-2xl border border-white/5 text-center">
             <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-2">Sync Status</div>
             {syncingBlocks.size > 0 ? (
               <div className="flex flex-col items-center gap-2">
                 <RefreshCw className="w-4 h-4 text-amber-500 animate-spin" />
                 <span className="text-[9px] font-bold text-amber-500 animate-pulse uppercase">Vẽ ảnh AI...</span>
               </div>
             ) : (
               <div className="flex flex-col items-center gap-2 opacity-50">
                 <ShieldCheck className="w-4 h-4 text-emerald-500" />
                 <span className="text-[9px] font-bold text-emerald-500 uppercase">Đã đồng bộ</span>
               </div>
             )}
          </div>
        </aside>

        <section className="flex-1 flex flex-col overflow-hidden bg-[#020617]">
          {viewMode === 'edit' ? (
            <div className="flex-1 flex flex-col p-6 overflow-hidden">
               {state.blocks.length > 0 ? (
                  <div className="flex-1 bg-[#0b0f1a] rounded-3xl border border-white/5 shadow-2xl flex flex-col overflow-hidden">
                    <div className="p-3 bg-[#131929] border-b border-white/5 flex items-center justify-between px-6">
                       <div className="flex items-center gap-3">
                          <Code2 className="w-4 h-4 text-indigo-400" />
                          <span className="text-[10px] font-black text-white uppercase tracking-widest">{state.blocks.find(b => b.id === state.selectedBlockId)?.name}</span>
                       </div>
                    </div>
                    <textarea
                      value={state.blocks.find(b => b.id === state.selectedBlockId)?.html || ''}
                      onChange={(e) => handleBlockChange(state.selectedBlockId!, e.target.value)}
                      className="flex-1 p-8 bg-transparent text-slate-300 code-font text-sm outline-none resize-none custom-scrollbar"
                    />
                  </div>
               ) : (
                  <div className="flex-1 flex flex-col items-center justify-center text-center max-w-2xl mx-auto">
                    <div className="w-20 h-20 bg-indigo-600/10 rounded-full flex items-center justify-center mb-8 animate-pulse">
                       <Zap className="w-10 h-10 text-indigo-500" />
                    </div>
                    <h2 className="text-3xl font-black text-white mb-4 uppercase tracking-tighter">Omni Builder v3</h2>
                    <p className="text-slate-500 text-sm mb-8 leading-relaxed">Mô tả dự án của bạn, Gemini sẽ tự động thiết kế cấu trúc và tạo hình ảnh 4K nhúng trực tiếp dưới dạng Base64.</p>
                    <textarea 
                      value={inputSource}
                      onChange={(e) => setInputSource(e.target.value)}
                      placeholder="Ví dụ: Landing page dịch vụ spa sang trọng với hình ảnh 4K..."
                      className="w-full h-32 bg-slate-900 border border-white/10 rounded-2xl p-6 text-sm outline-none focus:border-indigo-500 mb-6 text-white"
                    />
                    <button onClick={handleBuild} disabled={isProcessing} className="px-10 py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest hover:scale-105 transition-all shadow-xl shadow-indigo-600/30 active:scale-95 disabled:opacity-50">
                      {isProcessing ? 'ĐANG KHỞI TẠO...' : 'BẮT ĐẦU XÂY DỰNG'}
                    </button>
                  </div>
               )}
            </div>
          ) : (
            <div className="flex-1 flex flex-col overflow-hidden relative">
              <div className="h-12 border-b border-white/5 bg-[#0b0f1a] flex items-center justify-center gap-6 shrink-0">
                <button onClick={() => setPreviewDevice('mobile')} className={`p-2 rounded-lg transition-all ${previewDevice === 'mobile' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Smartphone className="w-4 h-4" /></button>
                <button onClick={() => setPreviewDevice('tablet')} className={`p-2 rounded-lg transition-all ${previewDevice === 'tablet' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><TabletIcon className="w-4 h-4" /></button>
                <button onClick={() => setPreviewDevice('desktop')} className={`p-2 rounded-lg transition-all ${previewDevice === 'desktop' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Monitor className="w-4 h-4" /></button>
              </div>
              <div className="flex-1 overflow-y-auto p-12 bg-[#020617] flex justify-center items-start custom-scrollbar relative" onScroll={handleSyncScroll}>
                <div key={previewKey} className={`flex-shrink-0 bg-white shadow-2xl transition-all duration-500 rounded-sm overflow-hidden border border-white/10 ${previewDevice === 'desktop' ? 'w-[1200px]' : previewDevice === 'tablet' ? 'w-[768px]' : 'w-[375px]'}`}>
                  <iframe ref={previewRefs.desktop} srcDoc={fullHtml} className={`w-full ${previewDevice === 'desktop' ? 'h-[800px]' : previewDevice === 'tablet' ? 'h-[1024px]' : 'h-[667px]'} border-none`} sandbox="allow-scripts" />
                </div>
              </div>

              {showTerminal && (
                <div className="absolute bottom-0 left-0 right-0 h-64 bg-[#0b0f1a] border-t border-white/10 z-[60] flex flex-col shadow-2xl animate-in slide-in-from-bottom">
                  <div className="h-10 bg-[#131929] border-b border-white/5 flex items-center justify-between px-6 shrink-0">
                    <div className="flex items-center gap-3 text-[10px] font-black text-white uppercase tracking-widest">
                      <TerminalIcon className="w-3.5 h-3.5 text-indigo-400" /> Console
                    </div>
                    <div className="flex items-center gap-3">
                       <button onClick={() => setState(prev => ({ ...prev, logs: [] }))} className="p-1 hover:text-red-400"><Trash className="w-3 h-3" /></button>
                       <button onClick={() => setShowTerminal(false)} className="p-1 hover:text-white"><X className="w-3 h-3" /></button>
                    </div>
                  </div>
                  <div className="flex-1 overflow-y-auto p-4 space-y-1 code-font custom-scrollbar bg-slate-950">
                    {state.logs.map(log => (
                      <div key={log.id} className="text-[10px] flex gap-3 p-1 rounded hover:bg-white/5">
                        <span className="text-slate-600">[{log.timestamp}]</span>
                        <span className={`font-black uppercase w-12 ${log.type === 'error' ? 'text-red-500' : log.type === 'success' ? 'text-emerald-500' : 'text-blue-400'}`}>{log.type}</span>
                        <div className="flex-1 text-slate-300">{log.message}</div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </section>

        <aside className="w-64 bg-[#0b0f1a] border-l border-white/5 p-6 flex flex-col gap-6 shrink-0">
           <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2 mb-2"><Palette className="w-3 h-3" /> Styles</h3>
           <div className="space-y-4">
              <div className="space-y-2">
                <label className="text-[9px] font-bold text-slate-500 uppercase">Accent</label>
                <input type="color" value={state.accentColor} onChange={(e) => setState(prev => ({ ...prev, accentColor: e.target.value }))} className="w-full h-8 bg-transparent cursor-pointer rounded-lg border border-white/10" />
              </div>
              <div className="space-y-2">
                <label className="text-[9px] font-bold text-slate-500 uppercase">Font</label>
                <select value={state.fontFamily} onChange={(e) => setState(prev => ({ ...prev, fontFamily: e.target.value }))} className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-[10px] font-black text-white">
                  <option value="Inter">INTER (SANS)</option>
                  <option value="Playfair Display">PLAYFAIR (SERIF)</option>
                  <option value="Fira Code">FIRA CODE (MONO)</option>
                </select>
              </div>
           </div>
           <div className="mt-auto p-4 bg-indigo-600/5 border border-indigo-500/20 rounded-2xl">
              <div className="flex items-center gap-2 mb-2">
                 <ShieldCheck className="w-3 h-3 text-emerald-400" />
                 <span className="text-[9px] font-black text-white uppercase">Ready to Use</span>
              </div>
              <p className="text-[9px] text-slate-500 leading-relaxed italic">Dữ liệu ảnh nhúng Base64 giúp trang web chạy Offline 100% sau khi xuất.</p>
           </div>
        </aside>
      </main>
    </div>
  );
}

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { geminiService } from './services/geminiService';
import { Block, OmniState, ChatMessage, LogEntry } from './types';
import { 
  Sparkles, Zap, MessageSquare, Download, CheckCircle2, 
  Loader2, Eye, Code2, Infinity, Rocket, 
  Smartphone, Tablet as TabletIcon, Monitor, Plus, Trash2, 
  Save, RefreshCw, X, ChevronRight, Layout, Palette, Type,
  Share2, ShieldCheck, DownloadCloud, Image as ImageIcon, AlertCircle,
  Key, Terminal as TerminalIcon, Bug, History, Trash, ExternalLink
} from 'lucide-react';

const INITIAL_STATE: OmniState = {
  projectName: "AI Enterprise Landing",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#6366f1",
  fontFamily: "Inter",
  logs: []
};

export default function App() {
  const [state, setState] = useState<OmniState>(INITIAL_STATE);
  const [isProcessing, setIsProcessing] = useState(false);
  const [syncingBlocks, setSyncingBlocks] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'tablet' | 'desktop'>('desktop');
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);

  const previewRefs = {
    mobile: useRef<HTMLIFrameElement>(null),
    tablet: useRef<HTMLIFrameElement>(null),
    desktop: useRef<HTMLIFrameElement>(null)
  };

  const addLog = (type: LogEntry['type'], message: string, details?: string) => {
    const newLog: LogEntry = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toLocaleTimeString(),
      type,
      message,
      details
    };
    setState(prev => ({
      ...prev,
      logs: [newLog, ...prev.logs].slice(0, 100)
    }));
  };

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
        addLog('warning', 'API Key chưa được chọn. Vui lòng chọn key để tiếp tục.');
        // @ts-ignore
        await window.aistudio.openSelectKey();
      } else {
        addLog('success', 'Gemini API Engine đã sẵn sàng.');
      }
    };
    checkKey();
  }, []);

  const fullHtml = useMemo(() => {
    const content = state.blocks.map(b => b.html).join('\n');
    return `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <script src="https://cdn.tailwindcss.com"></script>
        <link href="https://fonts.googleapis.com/css2?family=${state.fontFamily}:wght@400;700&display=swap" rel="stylesheet">
        <style>
          body { font-family: '${state.fontFamily}', sans-serif; scroll-behavior: smooth; margin: 0; padding: 0; background-color: white; }
          :root { --accent: ${state.accentColor}; }
          ${state.globalCss}
          /* Placeholder CSS cải tiến */
          img:not([src]), img[src=""], img[src="about:blank"] {
            background-color: #1e293b;
            min-height: 240px;
            min-width: 240px;
            display: block;
            position: relative;
            background-image: linear-gradient(45deg, #0f172a 25%, transparent 25%, transparent 75%, #0f172a 75%, #0f172a), 
                              linear-gradient(45deg, #0f172a 25%, transparent 25%, transparent 75%, #0f172a 75%, #0f172a);
            background-size: 20px 20px;
            background-position: 0 0, 10px 10px;
          }
          img[data-ai-prompt] {
            filter: grayscale(1) blur(2px);
            opacity: 0.5;
          }
        </style>
      </head>
      <body>
        ${content || '<div class="h-screen flex items-center justify-center text-gray-500 font-bold uppercase tracking-widest bg-slate-900">Workspace Empty</div>'}
      </body>
      </html>
    `;
  }, [state.blocks, state.accentColor, state.fontFamily, state.globalCss, previewKey]);

  const processBlockImages = async (targetBlocks?: Block[]) => {
    const blocksToProcess = targetBlocks || state.blocks;
    if (blocksToProcess.length === 0) return;

    addLog('info', `Bắt đầu hàng đợi đồng bộ ảnh AI cho ${blocksToProcess.length} blocks.`);

    for (const block of blocksToProcess) {
      const parser = new DOMParser();
      const doc = parser.parseFromString(block.html, 'text/html');
      const imgTags = Array.from(doc.querySelectorAll('img[data-ai-prompt]'));

      if (imgTags.length === 0) continue;

      setSyncingBlocks(prev => new Set(prev).add(block.id));
      addLog('info', `Đang vẽ ${imgTags.length} ảnh cho module: ${block.name}`);

      for (const img of imgTags) {
        const prompt = img.getAttribute('data-ai-prompt');
        if (prompt) {
          try {
            const base64Image = await geminiService.generateAiImage(prompt);
            img.setAttribute('src', base64Image);
            img.removeAttribute('data-ai-prompt');
            const updatedHtml = doc.body.innerHTML;
            setState(prev => ({
              ...prev,
              blocks: prev.blocks.map(b => b.id === block.id ? { ...b, html: updatedHtml } : b)
            }));
            setPreviewKey(k => k + 1);
            addLog('success', `Đã nhúng ảnh (Base64 ready) vào ${block.name}`);
          } catch (err: any) {
            addLog('error', `Lỗi tạo ảnh cho block ${block.name}`, err.message);
          }
        }
      }

      setSyncingBlocks(prev => {
        const next = new Set(prev);
        next.delete(block.id);
        return next;
      });

      await new Promise(r => setTimeout(r, 300));
    }
    addLog('success', 'Hoàn tất tất cả các tác vụ xử lý tài nguyên.');
  };

  const handleBuild = async () => {
    if (!inputSource.trim()) return;
    setIsProcessing(true);
    addLog('info', 'Đang yêu cầu Gemini xây dựng cấu trúc website...');

    try {
      const result = await geminiService.parseToBlocks(inputSource);
      setState(prev => ({
        ...prev,
        blocks: result.blocks,
        globalCss: result.globalCss,
        selectedBlockId: result.blocks[0]?.id || null
      }));
      setViewMode('preview');
      setPreviewKey(k => k + 1);

      addLog('success', `Đã dựng xong ${result.blocks.length} module.`);
      setTimeout(() => processBlockImages(result.blocks), 500);
    } catch (e: any) {
      addLog('error', 'Xây dựng thất bại', e.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleBlockChange = (id: string, newHtml: string) => {
    setState(prev => ({
      ...prev,
      blocks: prev.blocks.map(b => b.id === id ? { ...b, html: newHtml } : b)
    }));
  };

  const handleSyncScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const scrollTop = e.currentTarget.scrollTop;
    Object.values(previewRefs).forEach(ref => {
      if (ref.current && ref.current.contentWindow) {
        ref.current.contentWindow.scrollTo(0, scrollTop);
      }
    });
  };

  const handleOpenExternalPreview = () => {
    const blob = new Blob([fullHtml], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    window.open(url, '_blank');
    addLog('info', 'Đã mở xem trước trong tab mới.');
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden relative">
      <header className="h-16 border-b border-white/5 bg-[#0b0f1a]/95 backdrop-blur-xl px-6 flex items-center justify-between z-50">
        <div className="flex items-center gap-4">
          <div className="p-2 bg-indigo-600 rounded-xl shadow-lg shadow-indigo-600/30"><Infinity className="w-5 h-5 text-white" /></div>
          <div>
            <h1 className="text-lg font-black text-white tracking-tighter uppercase">Omni <span className="text-indigo-400">Gen-3</span></h1>
            <div className="flex items-center gap-1.5 text-[8px] font-bold text-emerald-500 uppercase tracking-widest italic animate-pulse">Gemini Pro Image Engine Active</div>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <button 
            onClick={() => setShowTerminal(!showTerminal)}
            className={`flex items-center gap-2 px-4 py-2 rounded-full font-black text-[10px] transition-all border ${showTerminal ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'bg-slate-800 border-white/5 text-slate-300 hover:bg-slate-700'}`}
          >
            <TerminalIcon className="w-3 h-3" /> {showTerminal ? 'CLOSE LOG' : 'DEV LOG'}
          </button>

          <button 
            onClick={handleOpenExternalPreview}
            disabled={state.blocks.length === 0}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600/10 hover:bg-blue-600/20 text-blue-400 rounded-full font-black text-xs transition-all border border-blue-500/20 active:scale-95 disabled:opacity-30"
          >
            <ExternalLink className="w-3.5 h-3.5" /> XEM NGOÀI
          </button>

          <button onClick={() => setViewMode(viewMode === 'edit' ? 'preview' : 'edit')} className="flex items-center gap-2 px-6 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-full font-black text-xs transition-all border border-white/5 active:scale-95">
            {viewMode === 'edit' ? <Eye className="w-3.5 h-3.5" /> : <Code2 className="w-3.5 h-3.5" />}
            {viewMode === 'edit' ? 'PREVIEW' : 'EDITOR'}
          </button>

          <button onClick={() => {
            const blob = new Blob([fullHtml], { type: 'text/html' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `omnigen-export.html`;
            a.click();
            addLog('success', 'Đã xuất file HTML hoàn chỉnh.');
          }} className="flex items-center gap-2 px-6 py-2 bg-emerald-600 hover:bg-emerald-500 text-white rounded-full font-black text-xs transition-all shadow-xl shadow-emerald-600/20 active:scale-95">
            <DownloadCloud className="w-3.5 h-3.5" /> EXPORT
          </button>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden">
        <aside className="w-64 bg-[#0b0f1a] border-r border-white/5 flex flex-col p-4 gap-4 shrink-0">
          <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2 mb-2"><Layout className="w-3 h-3" /> Page Modules</h3>
          <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar space-y-2">
            {state.blocks.map(block => (
              <div 
                key={block.id} 
                onClick={() => setState(prev => ({ ...prev, selectedBlockId: block.id }))}
                className={`group p-3 rounded-xl cursor-pointer transition-all border ${state.selectedBlockId === block.id ? 'bg-indigo-600/10 border-indigo-500/30 text-white shadow-lg' : 'bg-transparent border-transparent hover:bg-white/5 text-slate-500'}`}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 min-w-0">
                    {syncingBlocks.has(block.id) ? (
                      <Loader2 className="w-3 h-3 text-amber-500 animate-spin shrink-0" />
                    ) : (
                      <CheckCircle2 className={`w-3 h-3 shrink-0 ${state.selectedBlockId === block.id ? 'text-indigo-400' : 'text-slate-700'}`} />
                    )}
                    <span className="text-[10px] font-black uppercase truncate tracking-tight">{block.name}</span>
                  </div>
                  <button onClick={(e) => { e.stopPropagation(); setState(prev => ({ ...prev, blocks: prev.blocks.filter(b => b.id !== block.id) })); }} className="opacity-0 group-hover:opacity-100 p-1 hover:text-red-400"><Trash2 className="w-3 h-3" /></button>
                </div>
              </div>
            ))}
          </div>

          <div className="p-4 bg-slate-900/50 rounded-2xl border border-white/5 text-center">
             <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-2">Sync Status</div>
             {syncingBlocks.size > 0 ? (
               <div className="flex flex-col items-center gap-2">
                 <RefreshCw className="w-4 h-4 text-amber-500 animate-spin" />
                 <span className="text-[9px] font-bold text-amber-500 animate-pulse uppercase">Vẽ ảnh AI...</span>
               </div>
             ) : (
               <div className="flex flex-col items-center gap-2 opacity-50">
                 <ShieldCheck className="w-4 h-4 text-emerald-500" />
                 <span className="text-[9px] font-bold text-emerald-500 uppercase">Đã đồng bộ</span>
               </div>
             )}
          </div>
        </aside>

        <section className="flex-1 flex flex-col overflow-hidden bg-[#020617]">
          {viewMode === 'edit' ? (
            <div className="flex-1 flex flex-col p-6 overflow-hidden">
               {state.blocks.length > 0 ? (
                  <div className="flex-1 bg-[#0b0f1a] rounded-3xl border border-white/5 shadow-2xl flex flex-col overflow-hidden">
                    <div className="p-3 bg-[#131929] border-b border-white/5 flex items-center justify-between px-6">
                       <div className="flex items-center gap-3">
                          <Code2 className="w-4 h-4 text-indigo-400" />
                          <span className="text-[10px] font-black text-white uppercase tracking-widest">{state.blocks.find(b => b.id === state.selectedBlockId)?.name}</span>
                       </div>
                    </div>
                    <textarea
                      value={state.blocks.find(b => b.id === state.selectedBlockId)?.html || ''}
                      onChange={(e) => handleBlockChange(state.selectedBlockId!, e.target.value)}
                      className="flex-1 p-8 bg-transparent text-slate-300 code-font text-sm outline-none resize-none custom-scrollbar"
                    />
                  </div>
               ) : (
                  <div className="flex-1 flex flex-col items-center justify-center text-center max-w-2xl mx-auto">
                    <div className="w-20 h-20 bg-indigo-600/10 rounded-full flex items-center justify-center mb-8 animate-pulse">
                       <Zap className="w-10 h-10 text-indigo-500" />
                    </div>
                    <h2 className="text-3xl font-black text-white mb-4 uppercase tracking-tighter">Omni Builder v3</h2>
                    <p className="text-slate-500 text-sm mb-8 leading-relaxed">Mô tả dự án của bạn, Gemini sẽ tự động thiết kế cấu trúc và tạo hình ảnh 4K nhúng trực tiếp dưới dạng Base64.</p>
                    <textarea 
                      value={inputSource}
                      onChange={(e) => setInputSource(e.target.value)}
                      placeholder="Ví dụ: Landing page dịch vụ spa sang trọng với hình ảnh 4K..."
                      className="w-full h-32 bg-slate-900 border border-white/10 rounded-2xl p-6 text-sm outline-none focus:border-indigo-500 mb-6 text-white"
                    />
                    <button onClick={handleBuild} disabled={isProcessing} className="px-10 py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest hover:scale-105 transition-all shadow-xl shadow-indigo-600/30 active:scale-95 disabled:opacity-50">
                      {isProcessing ? 'ĐANG KHỞI TẠO...' : 'BẮT ĐẦU XÂY DỰNG'}
                    </button>
                  </div>
               )}
            </div>
          ) : (
            <div className="flex-1 flex flex-col overflow-hidden relative">
              <div className="h-12 border-b border-white/5 bg-[#0b0f1a] flex items-center justify-center gap-6 shrink-0">
                <button onClick={() => setPreviewDevice('mobile')} className={`p-2 rounded-lg transition-all ${previewDevice === 'mobile' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Smartphone className="w-4 h-4" /></button>
                <button onClick={() => setPreviewDevice('tablet')} className={`p-2 rounded-lg transition-all ${previewDevice === 'tablet' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><TabletIcon className="w-4 h-4" /></button>
                <button onClick={() => setPreviewDevice('desktop')} className={`p-2 rounded-lg transition-all ${previewDevice === 'desktop' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Monitor className="w-4 h-4" /></button>
              </div>
              <div className="flex-1 overflow-y-auto p-12 bg-[#020617] flex justify-center items-start custom-scrollbar relative" onScroll={handleSyncScroll}>
                <div key={previewKey} className={`flex-shrink-0 bg-white shadow-2xl transition-all duration-500 rounded-sm overflow-hidden border border-white/10 ${previewDevice === 'desktop' ? 'w-[1200px]' : previewDevice === 'tablet' ? 'w-[768px]' : 'w-[375px]'}`}>
                  <iframe ref={previewRefs.desktop} srcDoc={fullHtml} className={`w-full ${previewDevice === 'desktop' ? 'h-[800px]' : previewDevice === 'tablet' ? 'h-[1024px]' : 'h-[667px]'} border-none`} sandbox="allow-scripts" />
                </div>
              </div>

              {showTerminal && (
                <div className="absolute bottom-0 left-0 right-0 h-64 bg-[#0b0f1a] border-t border-white/10 z-[60] flex flex-col shadow-2xl animate-in slide-in-from-bottom">
                  <div className="h-10 bg-[#131929] border-b border-white/5 flex items-center justify-between px-6 shrink-0">
                    <div className="flex items-center gap-3 text-[10px] font-black text-white uppercase tracking-widest">
                      <TerminalIcon className="w-3.5 h-3.5 text-indigo-400" /> Console
                    </div>
                    <div className="flex items-center gap-3">
                       <button onClick={() => setState(prev => ({ ...prev, logs: [] }))} className="p-1 hover:text-red-400"><Trash className="w-3 h-3" /></button>
                       <button onClick={() => setShowTerminal(false)} className="p-1 hover:text-white"><X className="w-3 h-3" /></button>
                    </div>
                  </div>
                  <div className="flex-1 overflow-y-auto p-4 space-y-1 code-font custom-scrollbar bg-slate-950">
                    {state.logs.map(log => (
                      <div key={log.id} className="text-[10px] flex gap-3 p-1 rounded hover:bg-white/5">
                        <span className="text-slate-600">[{log.timestamp}]</span>
                        <span className={`font-black uppercase w-12 ${log.type === 'error' ? 'text-red-500' : log.type === 'success' ? 'text-emerald-500' : 'text-blue-400'}`}>{log.type}</span>
                        <div className="flex-1 text-slate-300">{log.message}</div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </section>

        <aside className="w-64 bg-[#0b0f1a] border-l border-white/5 p-6 flex flex-col gap-6 shrink-0">
           <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2 mb-2"><Palette className="w-3 h-3" /> Styles</h3>
           <div className="space-y-4">
              <div className="space-y-2">
                <label className="text-[9px] font-bold text-slate-500 uppercase">Accent</label>
                <input type="color" value={state.accentColor} onChange={(e) => setState(prev => ({ ...prev, accentColor: e.target.value }))} className="w-full h-8 bg-transparent cursor-pointer rounded-lg border border-white/10" />
              </div>
              <div className="space-y-2">
                <label className="text-[9px] font-bold text-slate-500 uppercase">Font</label>
                <select value={state.fontFamily} onChange={(e) => setState(prev => ({ ...prev, fontFamily: e.target.value }))} className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-[10px] font-black text-white">
                  <option value="Inter">INTER (SANS)</option>
                  <option value="Playfair Display">PLAYFAIR (SERIF)</option>
                  <option value="Fira Code">FIRA CODE (MONO)</option>
                </select>
              </div>
           </div>
           <div className="mt-auto p-4 bg-indigo-600/5 border border-indigo-500/20 rounded-2xl">
              <div className="flex items-center gap-2 mb-2">
                 <ShieldCheck className="w-3 h-3 text-emerald-400" />
                 <span className="text-[9px] font-black text-white uppercase">Ready to Use</span>
              </div>
              <p className="text-[9px] text-slate-500 leading-relaxed italic">Dữ liệu ảnh nhúng Base64 giúp trang web chạy Offline 100% sau khi xuất.</p>
           </div>
        </aside>
      </main>
    </div>
  );
}

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { geminiService } from './services/geminiService';
import { Block, OmniState, ChatMessage, LogEntry } from './types';
import { 
  Sparkles, Zap, MessageSquare, Download, CheckCircle2, 
  Loader2, Eye, Code2, Infinity, Rocket, 
  Smartphone, Tablet as TabletIcon, Monitor, Plus, Trash2, 
  Save, RefreshCw, X, ChevronRight, Layout, Palette, Type,
  Share2, ShieldCheck, DownloadCloud, Image as ImageIcon, AlertCircle,
  Key, Terminal as TerminalIcon, Bug, History, Trash, ExternalLink,
  Eraser
} from 'lucide-react';

const STORAGE_KEY = 'omni_gen_v3_state';

const INITIAL_STATE: OmniState = {
  projectName: "AI Enterprise Landing",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#6366f1",
  fontFamily: "Inter",
  logs: []
};

export default function App() {
  const [state, setState] = useState<OmniState>(INITIAL_STATE);
  const [isProcessing, setIsProcessing] = useState(false);
  const [syncingBlocks, setSyncingBlocks] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'tablet' | 'desktop'>('desktop');
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);
  const [isSaved, setIsSaved] = useState(true);

  const previewRefs = {
    mobile: useRef<HTMLIFrameElement>(null),
    tablet: useRef<HTMLIFrameElement>(null),
    desktop: useRef<HTMLIFrameElement>(null)
  };

  const addLog = (type: LogEntry['type'], message: string, details?: string) => {
    const newLog: LogEntry = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toLocaleTimeString(),
      type,
      message,
      details
    };
    setState(prev => ({
      ...prev,
      logs: [newLog, ...prev.logs].slice(0, 100)
    }));
  };

  // Load state from LocalStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        // We don't restore logs to keep terminal clean on start
        setState({ ...parsed, logs: [] });
        addLog('success', 'Đã khôi phục phiên làm việc từ bộ nhớ trình duyệt.');
      } catch (e) {
        addLog('error', 'Không thể khôi phục dữ liệu cũ.');
      }
    }

    const checkKey = async () => {
      // @ts-ignore
      if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
        addLog('warning', 'API Key chưa được chọn.');
        // @ts-ignore
        await window.aistudio.openSelectKey();
      } else {
        addLog('success', 'Gemini AI Engine sẵn sàng.');
      }
    };
    checkKey();
  }, []);

  // Save state to LocalStorage on change
  useEffect(() => {
    const timer = setTimeout(() => {
      const { logs, ...rest } = state;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(rest));
      setIsSaved(true);
    }, 1000);

    setIsSaved(false);
    return () => clearTimeout(timer);
  }, [state.blocks, state.globalCss, state.accentColor, state.fontFamily, state.projectName]);

  const fullHtml = useMemo(() => {
    const content = state.blocks.map(b => b.html).join('\n');
    return `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <script src="https://cdn.tailwindcss.com"></script>
        <link href="https://fonts.googleapis.com/css2?family=${state.fontFamily}:wght@400;700&display=swap" rel="stylesheet">
        <style>
          body { font-family: '${state.fontFamily}', sans-serif; scroll-behavior: smooth; margin: 0; padding: 0; background-color: white; color: #1e293b; }
          :root { --accent: ${state.accentColor}; }
          ${state.globalCss}
          img:not([src]), img[src=""], img[src="about:blank"] {
            background-color: #f1f5f9;
            min-height: 200px;
            display: block;
            position: relative;
            background-image: linear-gradient(45deg, #e2e8f0 25%, transparent 25%, transparent 75%, #e2e8f0 75%, #e2e8f0), 
                              linear-gradient(45deg, #e2e8f0 25%, transparent 25%, transparent 75%, #e2e8f0 75%, #e2e8f0);
            background-size: 20px 20px;
            background-position: 0 0, 10px 10px;
          }
          img[data-ai-prompt] {
            filter: grayscale(1) blur(2px);
            opacity: 0.5;
          }
        </style>
      </head>
      <body>
        ${content || '<div class="h-screen flex items-center justify-center text-slate-400 font-bold uppercase tracking-widest bg-slate-50">No Content Generated</div>'}
      </body>
      </html>
    `;
  }, [state.blocks, state.accentColor, state.fontFamily, state.globalCss, previewKey]);

  const processBlockImages = async (targetBlocks?: Block[]) => {
    const blocksToProcess = targetBlocks || state.blocks;
    if (blocksToProcess.length === 0) return;

    addLog('info', `Khởi động engine vẽ ảnh AI...`);

    for (const block of blocksToProcess) {
      const parser = new DOMParser();
      const doc = parser.parseFromString(block.html, 'text/html');
      const imgTags = Array.from(doc.querySelectorAll('img[data-ai-prompt]'));

      if (imgTags.length === 0) continue;

      setSyncingBlocks(prev => new Set(prev).add(block.id));

      for (const img of imgTags) {
        const prompt = img.getAttribute('data-ai-prompt');
        if (prompt) {
          try {
            const base64Image = await geminiService.generateAiImage(prompt);
            img.setAttribute('src', base64Image);
            img.removeAttribute('data-ai-prompt');
            const updatedHtml = doc.body.innerHTML;
            setState(prev => ({
              ...prev,
              blocks: prev.blocks.map(b => b.id === block.id ? { ...b, html: updatedHtml } : b)
            }));
            setPreviewKey(k => k + 1);
            addLog('success', `Đã đồng bộ ảnh cho: ${block.name}`);
          } catch (err: any) {
            addLog('error', `Lỗi tạo ảnh: ${block.name}`, err.message);
          }
        }
      }

      setSyncingBlocks(prev => {
        const next = new Set(prev);
        next.delete(block.id);
        return next;
      });

      await new Promise(r => setTimeout(r, 300));
    }
    addLog('success', 'Hoàn tất cập nhật tài nguyên.');
  };

  const handleBuild = async () => {
    if (!inputSource.trim()) return;
    setIsProcessing(true);
    addLog('info', 'Đang thiết kế kiến trúc bằng Gemini-3-Pro...');

    try {
      const result = await geminiService.parseToBlocks(inputSource);
      setState(prev => ({
        ...prev,
        blocks: result.blocks,
        globalCss: result.globalCss,
        selectedBlockId: result.blocks[0]?.id || null
      }));
      setViewMode('preview');
      setPreviewKey(k => k + 1);

      addLog('success', `Dựng xong ${result.blocks.length} module.`);
      setTimeout(() => processBlockImages(result.blocks), 500);
    } catch (e: any) {
      addLog('error', 'Xây dựng thất bại', e.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleClearWorkspace = () => {
    if (confirm("Bạn có chắc chắn muốn xóa toàn bộ dự án hiện tại?")) {
      setState(INITIAL_STATE);
      localStorage.removeItem(STORAGE_KEY);
      addLog('warning', 'Đã xóa trắng Workspace.');
    }
  };

  const handleBlockChange = (id: string, newHtml: string) => {
    setState(prev => ({
      ...prev,
      blocks: prev.blocks.map(b => b.id === id ? { ...b, html: newHtml } : b)
    }));
  };

  const handleSyncScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const scrollTop = e.currentTarget.scrollTop;
    Object.values(previewRefs).forEach(ref => {
      if (ref.current && ref.current.contentWindow) {
        ref.current.contentWindow.scrollTo(0, scrollTop);
      }
    });
  };

  const handleOpenExternalPreview = () => {
    const blob = new Blob([fullHtml], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    window.open(url, '_blank');
    addLog('info', 'Mở xem trước bên ngoài.');
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden relative">
      <header className="h-16 border-b border-white/5 bg-[#0b0f1a]/95 backdrop-blur-xl px-6 flex items-center justify-between z-50">
        <div className="flex items-center gap-4">
          <div className="p-2 bg-indigo-600 rounded-xl shadow-lg shadow-indigo-600/30"><Infinity className="w-5 h-5 text-white" /></div>
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-sm font-black text-white tracking-tighter uppercase">Omni <span className="text-indigo-400">Gen-3</span></h1>
              {isSaved ? (
                <div className="flex items-center gap-1 text-[8px] text-emerald-500 font-bold bg-emerald-500/10 px-1.5 py-0.5 rounded-md border border-emerald-500/20">
                  <Save className="w-2 h-2" /> SAVED
                </div>
              ) : (
                <div className="flex items-center gap-1 text-[8px] text-amber-500 font-bold bg-amber-500/10 px-1.5 py-0.5 rounded-md border border-amber-500/20">
                  <RefreshCw className="w-2 h-2 animate-spin" /> SYNCING...
                </div>
              )}
            </div>
            <div className="text-[8px] font-bold text-slate-500 uppercase tracking-widest mt-0.5 italic">Gemini Enterprise Architect</div>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button 
            onClick={() => setShowTerminal(!showTerminal)}
            className={`flex items-center gap-2 px-3 py-1.5 rounded-full font-black text-[9px] transition-all border ${showTerminal ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'bg-slate-800 border-white/5 text-slate-400 hover:bg-slate-700'}`}
          >
            <TerminalIcon className="w-3 h-3" /> CONSOLE
          </button>

          <button 
            onClick={handleClearWorkspace}
            className="flex items-center gap-2 px-3 py-1.5 bg-red-600/10 hover:bg-red-600/20 text-red-400 rounded-full font-black text-[9px] transition-all border border-red-500/20 active:scale-95"
          >
            <Eraser className="w-3 h-3" /> CLEAR
          </button>

          <div className="h-6 w-px bg-white/5 mx-1"></div>

          <button 
            onClick={handleOpenExternalPreview}
            disabled={state.blocks.length === 0}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600/10 hover:bg-blue-600/20 text-blue-400 rounded-full font-black text-xs transition-all border border-blue-500/20 active:scale-95 disabled:opacity-30"
          >
            <ExternalLink className="w-3.5 h-3.5" /> XEM NGOÀI
          </button>

          <button onClick={() => setViewMode(viewMode === 'edit' ? 'preview' : 'edit')} className="flex items-center gap-2 px-6 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-full font-black text-xs transition-all border border-white/5 active:scale-95">
            {viewMode === 'edit' ? <Eye className="w-3.5 h-3.5" /> : <Code2 className="w-3.5 h-3.5" />}
            {viewMode === 'edit' ? 'PREVIEW' : 'EDITOR'}
          </button>

          <button onClick={() => {
            const blob = new Blob([fullHtml], { type: 'text/html' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url; a.download = `omnigen-export.html`; a.click();
            addLog('success', 'Đã xuất file HTML.');
          }} className="flex items-center gap-2 px-6 py-2 bg-emerald-600 hover:bg-emerald-500 text-white rounded-full font-black text-xs transition-all shadow-xl shadow-emerald-600/20 active:scale-95">
            <DownloadCloud className="w-3.5 h-3.5" /> EXPORT
          </button>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden">
        <aside className="w-64 bg-[#0b0f1a] border-r border-white/5 flex flex-col p-4 gap-4 shrink-0">
          <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2 mb-2"><Layout className="w-3 h-3" /> Page Modules</h3>
          <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar space-y-2">
            {state.blocks.map(block => (
              <div 
                key={block.id} 
                onClick={() => setState(prev => ({ ...prev, selectedBlockId: block.id }))}
                className={`group p-3 rounded-xl cursor-pointer transition-all border ${state.selectedBlockId === block.id ? 'bg-indigo-600/10 border-indigo-500/30 text-white shadow-lg' : 'bg-transparent border-transparent hover:bg-white/5 text-slate-500'}`}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 min-w-0">
                    {syncingBlocks.has(block.id) ? (
                      <Loader2 className="w-3 h-3 text-amber-500 animate-spin shrink-0" />
                    ) : (
                      <CheckCircle2 className={`w-3 h-3 shrink-0 ${state.selectedBlockId === block.id ? 'text-indigo-400' : 'text-slate-700'}`} />
                    )}
                    <span className="text-[10px] font-black uppercase truncate tracking-tight">{block.name}</span>
                  </div>
