                  <option value="Inter">INTER (SANS)</option>
                  <option value="Playfair Display">PLAYFAIR (SERIF)</option>
                  <option value="Fira Code">FIRA CODE (MONO)</option>
                </select>
              </div>
           </div>

           <div className="mt-auto p-4 bg-indigo-600/5 border border-indigo-500/20 rounded-2xl group hover:bg-indigo-600/10 transition-colors">
              <div className="flex items-center gap-2 mb-2">
                 <ShieldCheck className="w-3 h-3 text-emerald-400" />
                 <span className="text-[9px] font-black text-white uppercase tracking-tighter">Production Ready</span>
              </div>
              <p className="text-[9px] text-slate-500 leading-relaxed italic font-medium">Dữ liệu được lưu trữ tự động trong trình duyệt. Bạn có thể quay lại bất cứ lúc nào.</p>
           </div>
        </aside>
      </main>
    </div>
  );
}

