              {showTerminal && (
                <div className="absolute bottom-0 left-0 right-0 h-64 bg-[#0b0f1a] border-t border-white/10 z-[60] flex flex-col shadow-2xl animate-in slide-in-from-bottom">
                  <div className="h-10 bg-[#131929] border-b border-white/5 flex items-center justify-between px-6 shrink-0 text-[10px] font-black">
                    <div className="flex items-center gap-3 text-white uppercase tracking-widest">
                      <TerminalIcon className="w-3.5 h-3.5 text-indigo-400" /> Architect Logs
                    </div>
                    <div className="flex items-center gap-3">
                       <button onClick={() => setState(prev => ({ ...prev, logs: [] }))} className="p-1 hover:text-red-400"><Trash className="w-3 h-3" /></button>
                       <button onClick={() => setShowTerminal(false)} className="p-1 hover:text-white"><X className="w-3 h-3" /></button>
                    </div>
                  </div>
                  <div className="flex-1 overflow-y-auto p-4 space-y-1 code-font custom-scrollbar bg-slate-950">
                    {state.logs.map(log => (
                      <div key={log.id} className="text-[10px] flex gap-3 p-1 rounded hover:bg-white/5">
                        <span className="text-slate-600">[{log.timestamp}]</span>
                        <span className={`font-black uppercase w-12 ${log.type === 'error' ? 'text-red-500' : log.type === 'success' ? 'text-emerald-500' : 'text-blue-400'}`}>{log.type}</span>
                        <div className="flex-1 text-slate-300">{log.message}</div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </section>

        <aside className="w-64 bg-[#0b0f1a] border-l border-white/5 p-6 flex flex-col gap-6 shrink-0">
           <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2 mb-1"><Palette className="w-3 h-3" /> Identity & Style</h3>

           <div className="space-y-5">
              <div className="space-y-2">
                <label className="text-[9px] font-bold text-slate-500 uppercase flex items-center gap-2"><Edit3 className="w-2 h-2" /> Meta Title</label>
                <input 
                  type="text" 
                  value={state.metaTitle} 
                  onChange={(e) => setState(prev => ({ ...prev, metaTitle: e.target.value }))}
                  placeholder="Website Title"
                  className="w-full bg-slate-950 border border-white/10 rounded-lg p-2 text-[10px] text-white outline-none focus:border-indigo-500"
                />
              </div>

              <div className="space-y-2">
                <label className="text-[9px] font-bold text-slate-500 uppercase flex items-center gap-2"><Palette className="w-2 h-2" /> Accent Color</label>
                <div className="flex items-center gap-3 bg-slate-950 p-2 rounded-xl border border-white/10">
                  <input type="color" value={state.accentColor} onChange={(e) => setState(prev => ({ ...prev, accentColor: e.target.value }))} className="w-8 h-8 bg-transparent cursor-pointer rounded-lg border-none" />
                  <span className="text-[10px] font-mono font-black text-white">{state.accentColor.toUpperCase()}</span>
                </div>
