              </div>

              <div className="space-y-2">
                <label className="text-[9px] font-bold text-slate-500 uppercase flex items-center gap-2"><Type className="w-2 h-2" /> Typography</label>
                <select 
                  value={state.fontFamily} 
                  onChange={(e) => setState(prev => ({ ...prev, fontFamily: e.target.value }))} 
                  className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-[10px] font-black text-white outline-none"
                >
                  <option value="Inter">INTER (SANS)</option>
                  <option value="Playfair Display">PLAYFAIR (SERIF)</option>
                  <option value="Fira Code">FIRA CODE (MONO)</option>
                  <option value="Montserrat">MONTSERRAT</option>
                </select>
              </div>
           </div>

           <div className="mt-auto p-4 bg-indigo-600/5 border border-indigo-500/20 rounded-2xl group hover:bg-indigo-600/10 transition-all">
              <div className="flex items-center gap-2 mb-2">
                 <ShieldCheck className="w-3 h-3 text-emerald-400" />
                 <span className="text-[9px] font-black text-white uppercase tracking-tighter">AI Personalization</span>
