      </main>

      {isProcessing && (
        <div className="absolute inset-0 bg-slate-950/98 backdrop-blur-3xl z-[100] flex flex-col items-center justify-center p-10 text-center animate-in fade-in duration-700">
          <div className="relative mb-16 scale-150">
            <div className="w-20 h-20 border-2 border-indigo-500/10 rounded-full animate-ping"></div>
            <div className="absolute inset-0 w-20 h-20 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin [animation-duration:0.6s]"></div>
            <div className="absolute inset-0 m-auto w-8 h-8 flex items-center justify-center text-indigo-500">
               <Zap className="w-6 h-6 animate-pulse" />
            </div>
          </div>
          <h2 className="text-4xl font-black text-white mb-6 tracking-tighter uppercase italic">Crafting ${state.designTone} Experience...</h2>
          <div className="flex items-center gap-3 text-slate-500 text-[10px] font-black uppercase tracking-[0.4em] animate-pulse">
            <Sparkles className="w-4 h-4 text-amber-500" /> ENGINE ANALYZING LAYOUT <Sparkles className="w-4 h-4 text-amber-500" />
          </div>
        </div>
      )}
