                  onKeyDown={(e) => e.key === 'Enter' && setIsEditingTitle(false)}
                  className="bg-slate-900 border border-indigo-500/50 rounded px-2 py-0.5 text-xs font-black text-white outline-none"
                />
              ) : (
                <div onClick={() => setIsEditingTitle(true)} className="flex items-center gap-2 cursor-pointer">
                  <h1 className="text-sm font-black text-white tracking-tighter uppercase">{state.projectName}</h1>
                  <Edit3 className="w-3 h-3 text-slate-500 opacity-0 group-hover:opacity-100 transition-opacity" />
                </div>
              )}
              {isSaved ? (
                <div className="text-[7px] text-emerald-500 font-bold bg-emerald-500/10 px-1 py-0.5 rounded border border-emerald-500/20">SYNCED</div>
              ) : (
                <div className="text-[7px] text-amber-500 font-bold bg-amber-500/10 px-1 py-0.5 rounded border border-amber-500/20">...</div>
