          <div className="h-6 w-px bg-white/5 mx-1"></div>

          <button onClick={() => setViewMode(viewMode === 'edit' ? 'preview' : 'edit')} className="flex items-center gap-2 px-5 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-full font-black text-xs transition-all border border-white/5 active:scale-95">
