                  <div className="h-10 bg-[#131929] border-b border-white/5 flex items-center justify-between px-6 shrink-0 text-[10px] font-black">
                    <div className="flex items-center gap-3 text-white uppercase tracking-widest">
                      <TerminalIcon className="w-3.5 h-3.5 text-indigo-400" /> Architect Logs
                    </div>
                    <div className="flex items-center gap-3">
                       <button onClick={() => setState(prev => ({ ...prev, logs: [] }))} className="p-1 hover:text-red-400"><Trash className="w-3 h-3" /></button>
                       <button onClick={() => setShowTerminal(false)} className="p-1 hover:text-white"><X className="w-3 h-3" /></button>
                    </div>
                  </div>
                  <div className="flex-1 overflow-y-auto p-4 space-y-1 code-font custom-scrollbar bg-slate-950">
                    {state.logs.map(log => (
                      <div key={log.id} className="text-[10px] flex gap-3 p-1 rounded hover:bg-white/5">
                        <span className="text-slate-600">[{log.timestamp}]</span>
                        <span className={`font-black uppercase w-12 ${log.type === 'error' ? 'text-red-500' : log.type === 'success' ? 'text-emerald-500' : 'text-blue-400'}`}>{log.type}</span>
                        <div className="flex-1 text-slate-300">{log.message}</div>
                      </div>
                    ))}
