                <select 
                  value={state.borderRadius} 
                  onChange={(e) => setState(prev => ({ ...prev, borderRadius: e.target.value }))}
                  className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-[10px] font-black text-white outline-none"
                >
                  <option value="0px">SHARP (0px)</option>
                  <option value="0.375rem">SMALL (6px)</option>
