              </div>

              <div className="space-y-2">
                <label className="text-[9px] font-bold text-slate-500 uppercase flex items-center gap-2"><Type className="w-2 h-2" /> Typography</label>
                <select 
                  value={state.fontFamily} 
                  onChange={(e) => setState(prev => ({ ...prev, fontFamily: e.target.value }))} 
                  className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-[10px] font-black text-white outline-none"
                >
                  <option value="Inter">INTER (SANS)</option>
