          img:not([src]), img[src=""], img[src="about:blank"] {
            background-color: #f1f5f9; min-height: 200px; display: block;
            background-image: linear-gradient(45deg, #e2e8f0 25%, transparent 25%, transparent 75%, #e2e8f0 75%, #e2e8f0), 
                              linear-gradient(45deg, #e2e8f0 25%, transparent 25%, transparent 75%, #e2e8f0 75%, #e2e8f0);
            background-size: 20px 20px; background-position: 0 0, 10px 10px;
          }
        </style>
      </head>
      <body>
        ${content || '<div class="h-screen flex items-center justify-center text-slate-300 font-bold uppercase tracking-widest bg-slate-50">Empty Architecture</div>'}
        ${annotateScript}
      </body>
      </html>
    `;
  };

  const internalHtml = useMemo(() => generateWebsiteHtml(true), [state.blocks, state.accentColor, state.fontFamily, state.globalCss, state.borderRadius, state.metaTitle, state.projectName, previewKey]);

  const processBlockImages = async (targetBlocks?: Block[]) => {
    const blocksToProcess = targetBlocks || state.blocks;
    if (blocksToProcess.length === 0) return;

    for (const block of blocksToProcess) {
      const parser = new DOMParser();
      const doc = parser.parseFromString(block.html, 'text/html');
      const imgTags = Array.from(doc.querySelectorAll('img[data-ai-prompt]'));
      if (imgTags.length === 0) continue;
      setSyncingBlocks(prev => new Set(prev).add(block.id));
      for (const img of imgTags) {
        const prompt = img.getAttribute('data-ai-prompt');
        if (prompt) {
          try {
            const base64Image = await geminiService.generateAiImage(prompt);
            img.setAttribute('src', base64Image);
            img.removeAttribute('data-ai-prompt');
            const updatedHtml = doc.body.innerHTML;
            setState(prev => ({
              ...prev,
              blocks: prev.blocks.map(b => b.id === block.id ? { ...b, html: updatedHtml } : b)
            }));
            setPreviewKey(k => k + 1);
          } catch (err: any) {
            addLog('error', `Lỗi AI Image: ${block.name}`, err.message);
          }
        }
      }
      setSyncingBlocks(prev => {
        const next = new Set(prev);
        next.delete(block.id);
        return next;
      });
      await new Promise(r => setTimeout(r, 200));
    }
  };

  const handleBuild = async () => {
    if (!inputSource.trim()) return;
    setIsProcessing(true);
    addLog('info', `Gemini bắt đầu thi công dự án với branding context...`);
    try {
      const result = await geminiService.parseToBlocks(
        inputSource, 
        state.designTone,
        { logo: state.logoBase64, concept: state.conceptText }
      );
      setState(prev => ({
        ...prev,
        blocks: result.blocks,
        globalCss: result.globalCss,
        selectedBlockId: result.blocks[0]?.id || null
      }));
      setViewMode('preview');
      setPreviewKey(k => k + 1);
      addLog('success', `Đã dựng xong cấu trúc.`);
      setTimeout(() => processBlockImages(result.blocks), 500);
    } catch (e: any) {
      addLog('error', 'Xây dựng thất bại', e.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleLogoUpload = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = (e: any) => {
      const file = e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (re) => {
        const base64 = re.target?.result as string;
        setState(prev => ({ ...prev, logoBase64: base64 }));
        addLog('success', 'Đã tải lên Logo thương hiệu.');
      };
      reader.readAsDataURL(file);
    };
    input.click();
  };

  const moveBlock = (index: number, direction: 'up' | 'down') => {
    const newBlocks = [...state.blocks];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= newBlocks.length) return;
    [newBlocks[index], newBlocks[targetIndex]] = [newBlocks[targetIndex], newBlocks[index]];
    setState(prev => ({ ...prev, blocks: newBlocks }));
  };

  const handleOpenExternalPreview = () => {
    const prodHtml = generateWebsiteHtml(false);
    const blob = new Blob([prodHtml], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    window.open(url, '_blank');
    addLog('info', 'Mở xem trước bản sạch (không Annotate).');
  };

  const handleExport = () => {
    const prodHtml = generateWebsiteHtml(false);
    const blob = new Blob([prodHtml], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; 
    a.download = `${state.projectName.toLowerCase().replace(/\s+/g, '-')}.html`; 
    a.click();
    addLog('success', 'Đã xuất file HTML sạch (không Annotate).');
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden relative">
      <header className="h-16 border-b border-white/5 bg-[#0b0f1a]/95 backdrop-blur-xl px-6 flex items-center justify-between z-50">
        <div className="flex items-center gap-4">
          <div className="p-2 bg-indigo-600 rounded-xl shadow-lg shadow-indigo-600/30 font-black"><Infinity className="w-5 h-5 text-white" /></div>
          <div>
            <div className="flex items-center gap-2 group">
              <h1 className="text-sm font-black text-white tracking-tighter uppercase">{state.projectName}</h1>
              {isSaved && <div className="text-[7px] text-emerald-500 font-bold bg-emerald-500/10 px-1 py-0.5 rounded border border-emerald-500/20">PRODUCTION READY</div>}
            </div>
            <div className="text-[8px] font-bold text-slate-500 uppercase tracking-widest mt-0.5 italic flex items-center gap-1">
              <ImageIcon className="w-2 h-2 text-indigo-400" /> Annotate Preview Active
            </div>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button onClick={() => setShowTerminal(!showTerminal)} className={`p-2 rounded-full transition-all border ${showTerminal ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-800 border-white/5 text-slate-400 hover:bg-slate-700'}`}>
            <TerminalIcon className="w-4 h-4" />
          </button>

          <button onClick={() => { if(confirm("Xóa trắng dự án?")) setState(INITIAL_STATE); }} className="p-2 bg-red-600/10 hover:bg-red-600/20 text-red-400 rounded-full border border-red-500/20">
            <Eraser className="w-4 h-4" />
          </button>

          <div className="h-6 w-px bg-white/5 mx-1"></div>

          <button onClick={() => setViewMode(viewMode === 'edit' ? 'preview' : 'edit')} className="flex items-center gap-2 px-5 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-full font-black text-xs transition-all border border-white/5 shadow-inner">
            {viewMode === 'edit' ? <Eye className="w-3.5 h-3.5" /> : <Code2 className="w-3.5 h-3.5" />}
            {viewMode === 'edit' ? 'PREVIEW' : 'EDITOR'}
          </button>

          <button onClick={handleExport} className="flex items-center gap-2 px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-full font-black text-xs transition-all shadow-xl shadow-indigo-600/30 active:scale-95">
            <DownloadCloud className="w-3.5 h-3.5" /> EXPORT
          </button>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden">
        <aside className="w-64 bg-[#0b0f1a] border-r border-white/5 flex flex-col p-4 gap-4 shrink-0">
          <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2 mb-1 px-2"><Layout className="w-3 h-3" /> Architecture</h3>
          <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar space-y-2">
            {state.blocks.map((block, idx) => (
              <div 
                key={block.id} 
                onClick={() => setState(prev => ({ ...prev, selectedBlockId: block.id }))}
                className={`group p-3 rounded-xl cursor-pointer transition-all border relative ${state.selectedBlockId === block.id ? 'bg-indigo-600/10 border-indigo-500/30 text-white' : 'bg-transparent border-transparent hover:bg-white/5 text-slate-500'}`}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 min-w-0">
                    <span className="text-[8px] font-black opacity-30 w-3 text-center">{idx + 1}</span>
                    <span className="text-[10px] font-black uppercase truncate tracking-tight">{block.name}</span>
                  </div>
                  <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button onClick={(e) => { e.stopPropagation(); moveBlock(idx, 'up'); }} disabled={idx === 0} className="p-0.5 hover:text-white disabled:opacity-20"><ChevronUp className="w-3 h-3" /></button>
                    <button onClick={(e) => { e.stopPropagation(); moveBlock(idx, 'down'); }} disabled={idx === state.blocks.length - 1} className="p-0.5 hover:text-white disabled:opacity-20"><ChevronDown className="w-3 h-3" /></button>
                  </div>
                </div>
                {syncingBlocks.has(block.id) && (
                  <div className="absolute inset-0 bg-indigo-600/5 rounded-xl flex items-center justify-center">
                    <Loader2 className="w-3 h-3 text-indigo-500 animate-spin" />
                  </div>
                )}
              </div>
            ))}
          </div>

          <div className="p-4 bg-slate-900/50 rounded-2xl border border-white/5">
             <div className="text-[9px] font-black text-slate-500 uppercase mb-3">Tone Preset</div>
             <select 
               value={state.designTone} 
               onChange={(e) => setState(prev => ({ ...prev, designTone: e.target.value as DesignTone }))}
               className="w-full bg-slate-950 border border-white/10 rounded-lg p-2 text-[9px] font-black text-indigo-400 outline-none uppercase"
             >
               <option value="professional">Professional</option>
               <option value="minimalist">Minimalist</option>
               <option value="cyberpunk">Cyberpunk</option>
               <option value="playful">Playful</option>
               <option value="brutalist">Brutalist</option>
             </select>
          </div>
        </aside>

        <section className="flex-1 flex flex-col overflow-hidden bg-[#020617]">
          {viewMode === 'edit' ? (
            <div className="flex-1 flex flex-col p-6 overflow-hidden">
               {state.blocks.length > 0 ? (
                  <div className="flex-1 bg-[#0b0f1a] rounded-3xl border border-white/5 shadow-2xl flex flex-col overflow-hidden">
                    <div className="p-3 bg-[#131929] border-b border-white/5 px-6">
                       <span className="text-[10px] font-black text-white uppercase tracking-widest">{state.blocks.find(b => b.id === state.selectedBlockId)?.name}</span>
                    </div>
                    <textarea
                      value={state.blocks.find(b => b.id === state.selectedBlockId)?.html || ''}
                      onChange={(e) => setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === state.selectedBlockId ? { ...b, html: e.target.value } : b) }))}
                      className="flex-1 p-8 bg-transparent text-slate-300 code-font text-sm outline-none resize-none custom-scrollbar"
                    />
                  </div>
               ) : (
                  <div className="flex-1 flex flex-col items-center justify-center text-center max-w-xl mx-auto">
                    <div className="w-16 h-16 bg-indigo-600/10 rounded-full flex items-center justify-center mb-8 animate-pulse">
                      <Zap className="w-8 h-8 text-indigo-500" />
                    </div>
                    <h2 className="text-3xl font-black text-white mb-4 uppercase tracking-tighter italic">Omni Architect v3</h2>
                    <p className="text-slate-500 text-xs mb-8 uppercase tracking-widest font-bold">Dựng website 10,000 dòng mã chuẩn 2025 bằng trí tuệ nhân tạo</p>
                    <textarea 
                      value={inputSource}
                      onChange={(e) => setInputSource(e.target.value)}
                      placeholder="Mô tả ý tưởng của bạn... (VD: Landing page giới thiệu giải pháp AI Logistics với giao diện Cyberpunk)"
                      className="w-full h-32 bg-slate-900 border border-white/10 rounded-2xl p-6 text-sm outline-none focus:border-indigo-500 mb-6 text-white shadow-inner resize-none transition-all"
                    />
                    <button onClick={handleBuild} disabled={isProcessing} className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest hover:scale-[1.02] transition-all shadow-xl shadow-indigo-600/30 active:scale-95 disabled:opacity-50">
                      {isProcessing ? 'ĐANG DỰNG LAYOUT...' : 'BẮT ĐẦU THIẾT KẾ'}
                    </button>
                  </div>
               )}
            </div>
          ) : (
            <div className="flex-1 flex flex-col overflow-hidden relative">
              <div className="h-12 border-b border-white/5 bg-[#0b0f1a] flex items-center justify-center gap-6 shrink-0">
                <button onClick={() => setPreviewDevice('mobile')} className={`p-2 rounded-lg transition-all ${previewDevice === 'mobile' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500'}`}><Smartphone className="w-4 h-4" /></button>
                <button onClick={() => setPreviewDevice('tablet')} className={`p-2 rounded-lg transition-all ${previewDevice === 'tablet' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500'}`}><TabletIcon className="w-4 h-4" /></button>
                <button onClick={() => setPreviewDevice('desktop')} className={`p-2 rounded-lg transition-all ${previewDevice === 'desktop' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500'}`}><Monitor className="w-4 h-4" /></button>
                <div className="w-px h-4 bg-white/10 mx-2"></div>
                <button onClick={handleOpenExternalPreview} className="text-[9px] font-black text-blue-400 uppercase tracking-widest flex items-center gap-2 hover:text-blue-300">
                  <ExternalLink className="w-3 h-3" /> Full View (Clean)
                </button>
              </div>
              <div className="flex-1 overflow-y-auto p-12 bg-[#020617] flex justify-center items-start custom-scrollbar relative">
                <div key={previewKey} className={`flex-shrink-0 bg-white shadow-2xl transition-all duration-500 rounded-sm overflow-hidden border border-white/10 ${previewDevice === 'desktop' ? 'w-[1200px]' : previewDevice === 'tablet' ? 'w-[768px]' : 'w-[375px]'}`}>
                  <iframe ref={previewRefs.desktop} srcDoc={internalHtml} className={`w-full ${previewDevice === 'desktop' ? 'h-[800px]' : previewDevice === 'tablet' ? 'h-[1024px]' : 'h-[667px]'} border-none`} sandbox="allow-scripts allow-same-origin" />
                </div>
              </div>

              {showTerminal && (
                <div className="absolute bottom-0 left-0 right-0 h-64 bg-[#0b0f1a] border-t border-white/10 z-[60] flex flex-col shadow-2xl">
                  <div className="h-10 bg-[#131929] border-b border-white/5 flex items-center justify-between px-6 shrink-0 text-[10px] font-black uppercase">
                    <div className="flex items-center gap-2 text-indigo-400"><TerminalIcon className="w-3.5 h-3.5" /> Architect Console Output</div>
                    <button onClick={() => setShowTerminal(false)} className="hover:text-white transition-colors"><X className="w-3 h-3" /></button>
                  </div>
                  <div className="flex-1 overflow-y-auto p-4 space-y-1 code-font custom-scrollbar bg-slate-950 text-[10px]">
                    {state.logs.map(log => (
                      <div key={log.id} className="flex gap-3 text-slate-400 hover:bg-white/5 rounded px-1">
                        <span className="shrink-0 text-slate-600">[{log.timestamp}]</span>
                        <span className={`font-black w-12 ${log.type === 'error' ? 'text-red-500' : 'text-emerald-500'}`}>{log.type}</span>
                        <div className="flex-1">{log.message}</div>
                      </div>
                    ))}
                    {state.logs.length === 0 && <div className="text-slate-700 italic">No output logs...</div>}
                  </div>
                </div>
              )}
            </div>
          )}
        </section>

        <aside className="w-64 bg-[#0b0f1a] border-l border-white/5 p-6 flex flex-col gap-6 shrink-0 custom-scrollbar overflow-y-auto">
           <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1 flex items-center gap-2">
             <Briefcase className="w-3 h-3 text-indigo-400" /> Branding
           </h3>

           <div className="space-y-6">
              {/* Logo Section */}
              <div className="space-y-3">
                <label className="text-[9px] font-bold text-slate-500 uppercase flex items-center justify-between">
                  <span>Logo Thương Hiệu</span>
                  {state.logoBase64 && <button onClick={() => setState(prev => ({ ...prev, logoBase64: undefined }))} className="text-red-400 hover:text-red-300"><Trash2 className="w-2.5 h-2.5" /></button>}
                </label>
                <div 
                  onClick={handleLogoUpload}
                  className="w-full aspect-video bg-slate-950 border-2 border-dashed border-white/10 rounded-xl flex flex-col items-center justify-center gap-2 cursor-pointer hover:border-indigo-500/50 hover:bg-indigo-500/5 transition-all overflow-hidden relative"
                >
                  {state.logoBase64 ? (
                    <img src={state.logoBase64} className="w-full h-full object-contain p-2" alt="Logo" />
                  ) : (
                    <>
                      <Upload className="w-5 h-5 text-slate-600" />
                      <span className="text-[8px] font-black text-slate-600 uppercase">Upload PNG/SVG</span>
                    </>
                  )}
                </div>
              </div>

              {/* Concept Text Section */}
              <div className="space-y-3">
                <label className="text-[9px] font-bold text-slate-500 uppercase flex items-center gap-2">
                  <ScrollText className="w-2.5 h-2.5" /> <span>Concept Tham Khảo</span>
                </label>
                <textarea 
                  value={state.conceptText}
                  onChange={(e) => setState(prev => ({ ...prev, conceptText: e.target.value }))}
                  placeholder="Mô tả phong cách (VD: Sử dụng kính mờ, gradient cam-tím, font chữ đậm...)"
                  className="w-full h-32 bg-slate-950 border border-white/10 rounded-xl p-3 text-[10px] text-white outline-none focus:border-indigo-500 resize-none placeholder:text-slate-700"
                />
              </div>

              <div className="h-px bg-white/5 my-2"></div>

              <div className="space-y-2">
                <label className="text-[9px] font-bold text-slate-500 uppercase flex items-center gap-2"><Palette className="w-2 h-2" /> Accent Color</label>
                <div className="flex items-center gap-3 bg-slate-950 p-2 rounded-xl border border-white/10 shadow-inner">
                  <input type="color" value={state.accentColor} onChange={(e) => setState(prev => ({ ...prev, accentColor: e.target.value }))} className="w-8 h-8 bg-transparent cursor-pointer border-none rounded" />
                  <span className="text-[10px] font-mono font-black text-white">{state.accentColor.toUpperCase()}</span>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[9px] font-bold text-slate-500 uppercase flex items-center gap-2"><Layout className="w-2 h-2" /> Radius</label>
                <select value={state.borderRadius} onChange={(e) => setState(prev => ({ ...prev, borderRadius: e.target.value }))} className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-[10px] font-black text-white outline-none focus:border-indigo-500">
                  <option value="0px">SHARP (0px)</option>
                  <option value="0.75rem">SOFT (12px)</option>
                  <option value="1.5rem">ROUNDED (24px)</option>
                  <option value="9999px">PILL</option>
                </select>
              </div>

              <div className="space-y-2">
                <label className="text-[9px] font-bold text-slate-500 uppercase flex items-center gap-2"><Type className="w-2 h-2" /> Typography</label>
                <select value={state.fontFamily} onChange={(e) => setState(prev => ({ ...prev, fontFamily: e.target.value }))} className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-[10px] font-black text-white outline-none focus:border-indigo-500">
                  <option value="Inter">Inter (Modern Sans)</option>
                  <option value="Playfair Display">Playfair (Elegant Serif)</option>
                  <option value="Fira Code">Fira Code (Tech Mono)</option>
                  <option value="Montserrat">Montserrat</option>
                </select>
              </div>
           </div>

           <div className="mt-8 p-4 bg-indigo-600/5 border border-indigo-500/20 rounded-2xl">
              <div className="flex items-center gap-2 mb-2">
                 <ShieldCheck className="w-3 h-3 text-emerald-400" />
                 <span className="text-[9px] font-black text-white uppercase tracking-tighter">Branding Context</span>
              </div>
              <p className="text-[9px] text-slate-500 leading-relaxed italic">
                AI sẽ phân tích Logo và mô tả Concept để tự động điều chỉnh bố cục và phối màu cho phù hợp với thương hiệu của bạn.
              </p>
           </div>
        </aside>
      </main>

      {isProcessing && (
        <div className="absolute inset-0 bg-slate-950/98 backdrop-blur-3xl z-[100] flex flex-col items-center justify-center p-10 text-center animate-in fade-in duration-700">
          <div className="relative mb-12">
            <div className="w-24 h-24 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            <Zap className="absolute inset-0 m-auto w-8 h-8 text-indigo-500 animate-pulse" />
          </div>
          <h2 className="text-4xl font-black text-white mb-4 tracking-tighter uppercase italic">Omni-Engine Crafting...</h2>
          <div className="flex items-center gap-2 text-slate-500 text-[10px] font-black uppercase tracking-[0.4em] animate-pulse">
            <Sparkles className="w-4 h-4 text-amber-500" /> Analyzing Brand Style <Sparkles className="w-4 h-4 text-amber-500" />
          </div>
        </div>
      )}
    </div>
  );
}

export interface Block {
  id: string;
  type: string;
  name: string;
  html: string;
  css?: string;
}

export interface LogEntry {
  id: string;
  timestamp: string;
  type: 'info' | 'success' | 'error' | 'warning';
  message: string;
  details?: string;
}

export type DesignTone = 'professional' | 'minimalist' | 'cyberpunk' | 'playful' | 'brutalist';

export interface BrandingProfile {
  id: string;
  name: string;
  logoBase64?: string;
  conceptText?: string;
  accentColor: string;
  fontFamily: string;
  borderRadius: string;
}

export interface OmniState {
  projectName: string;
  metaTitle: string;
  blocks: Block[];
  selectedBlockId: string | null;
  globalCss: string;
  accentColor: string;
  fontFamily: string;
  designTone: DesignTone;
  borderRadius: string;
  logs: LogEntry[];
  logoBase64?: string;
  conceptText?: string;
  brandingProfiles: BrandingProfile[];
  activeBrandingId: string | null;
}

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
}

export interface GeneratedImage {
  url: string;
  prompt: string;
}

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { geminiService } from './services/geminiService';
import { Block, OmniState, LogEntry, DesignTone, BrandingProfile } from './types';
import { 
  Sparkles, Zap, Download, CheckCircle2, 
  Loader2, Eye, Code2, Infinity, 
  Smartphone, Tablet as TabletIcon, Monitor, Trash2, 
  Save, RefreshCw, X, Layout, Palette, 
  ShieldCheck, DownloadCloud, Key, Terminal as TerminalIcon, 
  Trash, ExternalLink, Eraser, ChevronUp, ChevronDown, Edit3, Type,
  Upload, Image as ImageIcon, Briefcase, ScrollText, Plus, Check, Copy
} from 'lucide-react';

const STORAGE_KEY = 'omni_gen_v3_state_pro_v2';

const INITIAL_STATE: OmniState = {
  projectName: "My New Project",
  metaTitle: "Omni Gen Website",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#6366f1",
  fontFamily: "Inter",
  designTone: 'professional',
  borderRadius: '0.75rem',
  logs: [],
  logoBase64: undefined,
  conceptText: "",
  brandingProfiles: [],
  activeBrandingId: null
};

export default function App() {
  const [state, setState] = useState<OmniState>(INITIAL_STATE);
  const [isProcessing, setIsProcessing] = useState(false);
  const [syncingBlocks, setSyncingBlocks] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'tablet' | 'desktop'>('desktop');
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);
  const [isSaved, setIsSaved] = useState(true);

  const previewRefs = {
    mobile: useRef<HTMLIFrameElement>(null),
    tablet: useRef<HTMLIFrameElement>(null),
    desktop: useRef<HTMLIFrameElement>(null)
  };

  const addLog = (type: LogEntry['type'], message: string, details?: string) => {
    const newLog: LogEntry = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toLocaleTimeString(),
      type,
      message,
      details
    };
    setState(prev => ({
      ...prev,
      logs: [newLog, ...prev.logs].slice(0, 100)
    }));
  };

  useEffect(() => {
    const handleIframeMessage = (event: MessageEvent) => {
      if (event.data?.type === 'UPDATE_BLOCK_HTML') {
        const { blockId, newHtml } = event.data;
        setState(prev => ({
          ...prev,
          blocks: prev.blocks.map(b => b.id === blockId ? { ...b, html: newHtml } : b)
        }));
        addLog('success', 'Đã cập nhật ảnh module từ Preview Annotate.');
      }
    };
    window.addEventListener('message', handleIframeMessage);
    return () => window.removeEventListener('message', handleIframeMessage);
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setState({ ...parsed, logs: [] });
      } catch (e) {
        addLog('error', 'Lỗi khôi phục dữ liệu.');
      }
    }

    const checkKey = async () => {
      // @ts-ignore
      if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
        addLog('warning', 'API Key chưa được chọn.');
        // @ts-ignore
        await window.aistudio.openSelectKey();
      } else {
        addLog('success', 'Gemini AI Engine sẵn sàng.');
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => {
      const { logs, ...rest } = state;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(rest));
      setIsSaved(true);
    }, 1000);
    setIsSaved(false);
    return () => clearTimeout(timer);
  }, [state.blocks, state.globalCss, state.accentColor, state.fontFamily, state.projectName, state.designTone, state.borderRadius, state.logoBase64, state.conceptText, state.brandingProfiles, state.activeBrandingId]);

  const generateWebsiteHtml = (isInternal: boolean = false) => {
    const content = state.blocks.map(b => 
      isInternal 
        ? `<div data-block-id="${b.id}" class="omni-block-wrapper relative">${b.html}</div>`
        : b.html
    ).join('\n');

    const annotateScript = isInternal ? `
      <script>
        (function() {
          const style = document.createElement('style');
          style.innerHTML = \`
            .omni-img-overlay {
              position: absolute;
              top: 8px;
              right: 8px;
              background: rgba(79, 70, 229, 0.95);
              color: white;
              padding: 6px 12px;
              border-radius: 8px;
              font-family: 'Inter', sans-serif;
              font-size: 10px;
              font-weight: 800;
              cursor: pointer;
              display: none;
              z-index: 10000;
              box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.3);
              backdrop-filter: blur(8px);
              border: 1px solid rgba(255,255,255,0.2);
              transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
              text-transform: uppercase;
              letter-spacing: 0.05em;
            }
            .omni-img-overlay:hover {
              background: #6366f1;
              transform: translateY(-2px);
            }
            .omni-img-target {
              outline: 3px solid #6366f1 !important;
              outline-offset: -3px;
              transition: outline 0.15s ease-in-out;
              cursor: pointer;
            }
          \`;
          document.head.appendChild(style);

          const overlay = document.createElement('div');
          overlay.className = 'omni-img-overlay';
          overlay.innerHTML = '<span style="display:flex;align-items:center;gap:6px;"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg> CHANGE IMAGE</span>';
          document.body.appendChild(overlay);

          let currentTargetImg = null;

          document.addEventListener('mouseover', (e) => {
            const img = e.target.closest('img');
            if (img) {
              currentTargetImg = img;
              img.classList.add('omni-img-target');
              const rect = img.getBoundingClientRect();
              overlay.style.display = 'block';
              overlay.style.top = (window.scrollY + rect.top + 12) + 'px';
              overlay.style.left = (window.scrollX + rect.right - 130) + 'px';
            }
          });

          overlay.addEventListener('click', () => {
            const input = document.createElement('input');
            input.type = 'file';
            input.accept = 'image/*';
            input.onchange = (e) => {
              const file = e.target.files[0];
              if (!file) return;
              const reader = new FileReader();
              reader.onload = (re) => {
                if (currentTargetImg) {
                  currentTargetImg.src = re.target.result;
                  currentTargetImg.removeAttribute('data-ai-prompt');
                  const wrapper = currentTargetImg.closest('[data-block-id]');
                  if (wrapper) {
                    const blockId = wrapper.getAttribute('data-block-id');
                    const clone = wrapper.cloneNode(true);
                    clone.querySelectorAll('.omni-img-target').forEach(el => el.classList.remove('omni-img-target'));
                    window.parent.postMessage({
                      type: 'UPDATE_BLOCK_HTML',
                      blockId: blockId,
                      newHtml: clone.innerHTML
                    }, '*');
                  }
                }
              };
              reader.readAsDataURL(file);
            };
            input.click();
          });

          document.addEventListener('mouseout', (e) => {
            const img = e.target.closest('img');
            if (img && !e.relatedTarget?.closest('.omni-img-overlay')) {
              img.classList.remove('omni-img-target');
            }
          });
        })();
      </script>
    ` : '';

    return `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title>${state.metaTitle || state.projectName}</title>
        <script src="https://cdn.tailwindcss.com"></script>
        <link href="https://fonts.googleapis.com/css2?family=${state.fontFamily}:wght@400;700&display=swap" rel="stylesheet">
        <style>
          body { font-family: '${state.fontFamily}', sans-serif; scroll-behavior: smooth; margin: 0; padding: 0; background-color: white; color: #1e293b; }
          :root { --accent: ${state.accentColor}; --radius: ${state.borderRadius}; }
          ${state.globalCss}
          img:not([src]), img[src=""], img[src="about:blank"] {
            background-color: #f1f5f9; min-height: 200px; display: block;
            background-image: linear-gradient(45deg, #e2e8f0 25%, transparent 25%, transparent 75%, #e2e8f0 75%, #e2e8f0), 
                              linear-gradient(45deg, #e2e8f0 25%, transparent 25%, transparent 75%, #e2e8f0 75%, #e2e8f0);
            background-size: 20px 20px; background-position: 0 0, 10px 10px;
          }
        </style>
      </head>
      <body>
        ${content || '<div class="h-screen flex items-center justify-center text-slate-300 font-bold uppercase tracking-widest bg-slate-50">Empty Architecture</div>'}
        ${annotateScript}
      </body>
      </html>
    `;
  };

  const internalHtml = useMemo(() => generateWebsiteHtml(true), [state.blocks, state.accentColor, state.fontFamily, state.globalCss, state.borderRadius, state.metaTitle, state.projectName, previewKey]);

  const processBlockImages = async (targetBlocks?: Block[]) => {
    const blocksToProcess = targetBlocks || state.blocks;
    if (blocksToProcess.length === 0) return;

    for (const block of blocksToProcess) {
      const parser = new DOMParser();
      const doc = parser.parseFromString(block.html, 'text/html');
      const imgTags = Array.from(doc.querySelectorAll('img[data-ai-prompt]'));
      if (imgTags.length === 0) continue;
      setSyncingBlocks(prev => new Set(prev).add(block.id));
      for (const img of imgTags) {
        const prompt = img.getAttribute('data-ai-prompt');
        if (prompt) {
          try {
            const base64Image = await geminiService.generateAiImage(prompt);
            img.setAttribute('src', base64Image);
            img.removeAttribute('data-ai-prompt');
            const updatedHtml = doc.body.innerHTML;
            setState(prev => ({
              ...prev,
              blocks: prev.blocks.map(b => b.id === block.id ? { ...b, html: updatedHtml } : b)
            }));
            setPreviewKey(k => k + 1);
          } catch (err: any) {
            addLog('error', `Lỗi AI Image: ${block.name}`, err.message);
          }
        }
      }
      setSyncingBlocks(prev => {
        const next = new Set(prev);
        next.delete(block.id);
        return next;
      });
      await new Promise(r => setTimeout(r, 200));
    }
  };

  const handleBuild = async () => {
    if (!inputSource.trim()) return;
    setIsProcessing(true);
    addLog('info', `Gemini bắt đầu thi công dự án với branding context...`);
    try {
      const result = await geminiService.parseToBlocks(
        inputSource, 
        state.designTone,
        { logo: state.logoBase64, concept: state.conceptText }
      );
      setState(prev => ({
        ...prev,
        blocks: result.blocks,
        globalCss: result.globalCss,
        selectedBlockId: result.blocks[0]?.id || null
      }));
      setViewMode('preview');
      setPreviewKey(k => k + 1);
      addLog('success', `Đã dựng xong cấu trúc.`);
      setTimeout(() => processBlockImages(result.blocks), 500);
    } catch (e: any) {
      addLog('error', 'Xây dựng thất bại', e.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleLogoUpload = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = (e: any) => {
      const file = e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (re) => {
        const base64 = re.target?.result as string;
        setState(prev => ({ ...prev, logoBase64: base64 }));
        addLog('success', 'Đã tải lên Logo thương hiệu.');
      };
      reader.readAsDataURL(file);
    };
    input.click();
  };

  const saveBrandingProfile = () => {
    const name = prompt("Tên bộ nhận diện thương hiệu này:", `Branding ${state.brandingProfiles.length + 1}`);
    if (!name) return;

    const newProfile: BrandingProfile = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      logoBase64: state.logoBase64,
      conceptText: state.conceptText,
      accentColor: state.accentColor,
      fontFamily: state.fontFamily,
      borderRadius: state.borderRadius
    };

    setState(prev => ({
      ...prev,
      brandingProfiles: [...prev.brandingProfiles, newProfile],
      activeBrandingId: newProfile.id
    }));
    addLog('success', `Đã lưu bộ nhận diện: ${name}`);
  };

  const applyBrandingProfile = (profile: BrandingProfile) => {
    setState(prev => ({
      ...prev,
      logoBase64: profile.logoBase64,
      conceptText: profile.conceptText,
      accentColor: profile.accentColor,
      fontFamily: profile.fontFamily,
      borderRadius: profile.borderRadius,
      activeBrandingId: profile.id
    }));
    addLog('info', `Đã áp dụng Branding: ${profile.name}`);
  };

  const deleteBrandingProfile = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!confirm("Xóa bộ nhận diện này?")) return;
    setState(prev => ({
      ...prev,
      brandingProfiles: prev.brandingProfiles.filter(p => p.id !== id),
      activeBrandingId: prev.activeBrandingId === id ? null : prev.activeBrandingId
    }));
  };

  const moveBlock = (index: number, direction: 'up' | 'down') => {
    const newBlocks = [...state.blocks];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= newBlocks.length) return;
    [newBlocks[index], newBlocks[targetIndex]] = [newBlocks[targetIndex], newBlocks[index]];
    setState(prev => ({ ...prev, blocks: newBlocks }));
  };

  const handleOpenExternalPreview = () => {
    const prodHtml = generateWebsiteHtml(false);
    const blob = new Blob([prodHtml], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    window.open(url, '_blank');
    addLog('info', 'Mở xem trước bản sạch (không Annotate).');
  };

  const handleExport = () => {
    const prodHtml = generateWebsiteHtml(false);
    const blob = new Blob([prodHtml], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; 
    a.download = `${state.projectName.toLowerCase().replace(/\s+/g, '-')}.html`; 
    a.click();
    addLog('success', 'Đã xuất file HTML sạch (không Annotate).');
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden relative">
      <header className="h-16 border-b border-white/5 bg-[#0b0f1a]/95 backdrop-blur-xl px-6 flex items-center justify-between z-50">
        <div className="flex items-center gap-4">
          <div className="p-2 bg-indigo-600 rounded-xl shadow-lg shadow-indigo-600/30 font-black"><Infinity className="w-5 h-5 text-white" /></div>
          <div>
            <div className="flex items-center gap-2 group">
              <h1 className="text-sm font-black text-white tracking-tighter uppercase">{state.projectName}</h1>
              {isSaved && <div className="text-[7px] text-emerald-500 font-bold bg-emerald-500/10 px-1 py-0.5 rounded border border-emerald-500/20 uppercase">PRODUCTION READY</div>}
            </div>
            <div className="text-[8px] font-bold text-slate-500 uppercase tracking-widest mt-0.5 italic flex items-center gap-1">
              <ImageIcon className="w-2 h-2 text-indigo-400" /> Annotate Preview Active
            </div>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button onClick={() => setShowTerminal(!showTerminal)} className={`p-2 rounded-full transition-all border ${showTerminal ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-800 border-white/5 text-slate-400 hover:bg-slate-700'}`}>
            <TerminalIcon className="w-4 h-4" />
          </button>

          <button onClick={() => { if(confirm("Xóa trắng dự án?")) setState(INITIAL_STATE); }} className="p-2 bg-red-600/10 hover:bg-red-600/20 text-red-400 rounded-full border border-red-500/20">
            <Eraser className="w-4 h-4" />
          </button>

          <div className="h-6 w-px bg-white/5 mx-1"></div>

          <button onClick={() => setViewMode(viewMode === 'edit' ? 'preview' : 'edit')} className="flex items-center gap-2 px-5 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-full font-black text-xs transition-all border border-white/5 shadow-inner">
            {viewMode === 'edit' ? <Eye className="w-3.5 h-3.5" /> : <Code2 className="w-3.5 h-3.5" />}
            {viewMode === 'edit' ? 'PREVIEW' : 'EDITOR'}
          </button>

          <button onClick={handleExport} className="flex items-center gap-2 px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-full font-black text-xs transition-all shadow-xl shadow-indigo-600/30 active:scale-95">
            <DownloadCloud className="w-3.5 h-3.5" /> EXPORT
          </button>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden">
        <aside className="w-64 bg-[#0b0f1a] border-r border-white/5 flex flex-col p-4 gap-4 shrink-0 overflow-hidden">
          <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2 mb-1 px-2 shrink-0"><Layout className="w-3 h-3" /> Architecture</h3>
          <div className="flex-1 overflow-y-auto pr-2 custom-scrollbar space-y-2">
            {state.blocks.map((block, idx) => (
              <div 
                key={block.id} 
                onClick={() => setState(prev => ({ ...prev, selectedBlockId: block.id }))}
                className={`group p-3 rounded-xl cursor-pointer transition-all border relative ${state.selectedBlockId === block.id ? 'bg-indigo-600/10 border-indigo-500/30 text-white' : 'bg-transparent border-transparent hover:bg-white/5 text-slate-500'}`}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2 min-w-0">
                    <span className="text-[8px] font-black opacity-30 w-3 text-center">{idx + 1}</span>
                    <span className="text-[10px] font-black uppercase truncate tracking-tight">{block.name}</span>
                  </div>
                  <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button onClick={(e) => { e.stopPropagation(); moveBlock(idx, 'up'); }} disabled={idx === 0} className="p-0.5 hover:text-white disabled:opacity-20"><ChevronUp className="w-3 h-3" /></button>
                    <button onClick={(e) => { e.stopPropagation(); moveBlock(idx, 'down'); }} disabled={idx === state.blocks.length - 1} className="p-0.5 hover:text-white disabled:opacity-20"><ChevronDown className="w-3 h-3" /></button>
                  </div>
                </div>
                {syncingBlocks.has(block.id) && (
                  <div className="absolute inset-0 bg-indigo-600/5 rounded-xl flex items-center justify-center">
                    <Loader2 className="w-3 h-3 text-indigo-500 animate-spin" />
                  </div>
                )}
              </div>
            ))}
            {state.blocks.length === 0 && (
               <div className="p-4 text-center border border-dashed border-white/5 rounded-2xl text-[10px] font-bold text-slate-600 uppercase italic">
                 Empty layout...
               </div>
            )}
          </div>

          <div className="p-4 bg-slate-900/50 rounded-2xl border border-white/5 shrink-0">
             <div className="text-[9px] font-black text-slate-500 uppercase mb-3">Tone Preset</div>
             <select 
               value={state.designTone} 
               onChange={(e) => setState(prev => ({ ...prev, designTone: e.target.value as DesignTone }))}
               className="w-full bg-slate-950 border border-white/10 rounded-lg p-2 text-[9px] font-black text-indigo-400 outline-none uppercase cursor-pointer"
             >
               <option value="professional">Professional</option>
               <option value="minimalist">Minimalist</option>
               <option value="cyberpunk">Cyberpunk</option>
               <option value="playful">Playful</option>
               <option value="brutalist">Brutalist</option>
             </select>
          </div>
        </aside>

        <section className="flex-1 flex flex-col overflow-hidden bg-[#020617]">
          {viewMode === 'edit' ? (
            <div className="flex-1 flex flex-col p-6 overflow-hidden">
               {state.blocks.length > 0 ? (
                  <div className="flex-1 bg-[#0b0f1a] rounded-3xl border border-white/5 shadow-2xl flex flex-col overflow-hidden">
                    <div className="p-3 bg-[#131929] border-b border-white/5 px-6">
                       <span className="text-[10px] font-black text-white uppercase tracking-widest">{state.blocks.find(b => b.id === state.selectedBlockId)?.name}</span>
                    </div>
                    <textarea
                      value={state.blocks.find(b => b.id === state.selectedBlockId)?.html || ''}
                      onChange={(e) => setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === state.selectedBlockId ? { ...b, html: e.target.value } : b) }))}
                      className="flex-1 p-8 bg-transparent text-slate-300 code-font text-sm outline-none resize-none custom-scrollbar"
                    />
                  </div>
               ) : (
                  <div className="flex-1 flex flex-col items-center justify-center text-center max-w-xl mx-auto">
                    <div className="w-16 h-16 bg-indigo-600/10 rounded-full flex items-center justify-center mb-8 animate-pulse">
                      <Zap className="w-8 h-8 text-indigo-500" />
                    </div>
                    <h2 className="text-3xl font-black text-white mb-4 uppercase tracking-tighter italic">Omni Architect v3</h2>
                    <p className="text-slate-500 text-xs mb-8 uppercase tracking-widest font-bold">Dựng website 10,000 dòng mã chuẩn 2025 bằng trí tuệ nhân tạo</p>
                    <textarea 
                      value={inputSource}
                      onChange={(e) => setInputSource(e.target.value)}
                      placeholder="Mô tả ý tưởng của bạn... (VD: Landing page giới thiệu giải pháp AI Logistics với giao diện Cyberpunk)"
                      className="w-full h-32 bg-slate-900 border border-white/10 rounded-2xl p-6 text-sm outline-none focus:border-indigo-500 mb-6 text-white shadow-inner resize-none transition-all"
                    />
                    <button onClick={handleBuild} disabled={isProcessing} className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest hover:scale-[1.02] transition-all shadow-xl shadow-indigo-600/30 active:scale-95 disabled:opacity-50">
                      {isProcessing ? 'ĐANG DỰNG LAYOUT...' : 'BẮT ĐẦU THIẾT KẾ'}
                    </button>
                  </div>
               )}
            </div>
          ) : (
            <div className="flex-1 flex flex-col overflow-hidden relative">
              <div className="h-12 border-b border-white/5 bg-[#0b0f1a] flex items-center justify-center gap-6 shrink-0">
                <button onClick={() => setPreviewDevice('mobile')} className={`p-2 rounded-lg transition-all ${previewDevice === 'mobile' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500'}`}><Smartphone className="w-4 h-4" /></button>
                <button onClick={() => setPreviewDevice('tablet')} className={`p-2 rounded-lg transition-all ${previewDevice === 'tablet' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500'}`}><TabletIcon className="w-4 h-4" /></button>
                <button onClick={() => setPreviewDevice('desktop')} className={`p-2 rounded-lg transition-all ${previewDevice === 'desktop' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500'}`}><Monitor className="w-4 h-4" /></button>
                <div className="w-px h-4 bg-white/10 mx-2"></div>
                <button onClick={handleOpenExternalPreview} className="text-[9px] font-black text-blue-400 uppercase tracking-widest flex items-center gap-2 hover:text-blue-300">
                  <ExternalLink className="w-3 h-3" /> Full View (Clean)
                </button>
              </div>
              <div className="flex-1 overflow-y-auto p-12 bg-[#020617] flex justify-center items-start custom-scrollbar relative">
                <div key={previewKey} className={`flex-shrink-0 bg-white shadow-2xl transition-all duration-500 rounded-sm overflow-hidden border border-white/10 ${previewDevice === 'desktop' ? 'w-[1200px]' : previewDevice === 'tablet' ? 'w-[768px]' : 'w-[375px]'}`}>
                  <iframe ref={previewRefs.desktop} srcDoc={internalHtml} className={`w-full ${previewDevice === 'desktop' ? 'h-[800px]' : previewDevice === 'tablet' ? 'h-[1024px]' : 'h-[667px]'} border-none`} sandbox="allow-scripts allow-same-origin" />
                </div>
              </div>

              {showTerminal && (
                <div className="absolute bottom-0 left-0 right-0 h-64 bg-[#0b0f1a] border-t border-white/10 z-[60] flex flex-col shadow-2xl">
                  <div className="h-10 bg-[#131929] border-b border-white/5 flex items-center justify-between px-6 shrink-0 text-[10px] font-black uppercase">
                    <div className="flex items-center gap-2 text-indigo-400"><TerminalIcon className="w-3.5 h-3.5" /> Architect Console Output</div>
                    <button onClick={() => setShowTerminal(false)} className="hover:text-white transition-colors"><X className="w-3 h-3" /></button>
                  </div>
                  <div className="flex-1 overflow-y-auto p-4 space-y-1 code-font custom-scrollbar bg-slate-950 text-[10px]">
                    {state.logs.map(log => (
                      <div key={log.id} className="flex gap-3 text-slate-400 hover:bg-white/5 rounded px-1">
                        <span className="shrink-0 text-slate-600">[{log.timestamp}]</span>
                        <span className={`font-black w-12 ${log.type === 'error' ? 'text-red-500' : 'text-emerald-500'}`}>{log.type}</span>
                        <div className="flex-1">{log.message}</div>
                      </div>
                    ))}
                    {state.logs.length === 0 && <div className="text-slate-700 italic px-2">No output logs...</div>}
                  </div>
                </div>
              )}
            </div>
          )}
        </section>

        <aside className="w-64 bg-[#0b0f1a] border-l border-white/5 p-6 flex flex-col gap-6 shrink-0 custom-scrollbar overflow-y-auto">
           <div className="flex items-center justify-between">
              <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <Briefcase className="w-3 h-3 text-indigo-400" /> Branding
              </h3>
              <button onClick={saveBrandingProfile} className="p-1 hover:bg-indigo-600/20 hover:text-indigo-400 rounded transition-all" title="Lưu thiết kế hiện tại thành Preset">
                <Plus className="w-3.5 h-3.5" />
              </button>
           </div>

           <div className="space-y-6">
              {/* Presets List */}
              {state.brandingProfiles.length > 0 && (
                <div className="space-y-2">
                   <label className="text-[8px] font-black text-slate-600 uppercase tracking-widest px-1">Presets</label>
                   <div className="grid grid-cols-1 gap-2">
                      {state.brandingProfiles.map(profile => (
                        <div 
                          key={profile.id}
                          onClick={() => applyBrandingProfile(profile)}
                          className={`group p-2.5 rounded-xl border flex items-center justify-between cursor-pointer transition-all ${state.activeBrandingId === profile.id ? 'bg-indigo-600/10 border-indigo-500/50' : 'bg-slate-950 border-white/5 hover:border-white/10'}`}
                        >
                          <div className="flex items-center gap-2 min-w-0">
                             <div className="w-3 h-3 rounded-full shrink-0 shadow-sm" style={{ backgroundColor: profile.accentColor }}></div>
                             <span className="text-[10px] font-black truncate text-slate-300 uppercase">{profile.name}</span>
                          </div>
                          <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                             {state.activeBrandingId === profile.id && <Check className="w-3 h-3 text-emerald-500" />}
                             <button onClick={(e) => deleteBrandingProfile(profile.id, e)} className="p-1 text-red-500 hover:text-red-400">
                               <Trash2 className="w-3 h-3" />
                             </button>
                          </div>
                        </div>
                      ))}
                   </div>
                </div>
              )}

              {/* Logo Section */}
              <div className="space-y-3">
                <label className="text-[9px] font-bold text-slate-500 uppercase flex items-center justify-between">
                  <span>Logo Hiện Tại</span>
                  {state.logoBase64 && <button onClick={() => setState(prev => ({ ...prev, logoBase64: undefined }))} className="text-red-400 hover:text-red-300"><Trash2 className="w-2.5 h-2.5" /></button>}
                </label>
                <div 
                  onClick={handleLogoUpload}
                  className="w-full aspect-video bg-slate-950 border-2 border-dashed border-white/10 rounded-xl flex flex-col items-center justify-center gap-2 cursor-pointer hover:border-indigo-500/50 hover:bg-indigo-500/5 transition-all overflow-hidden relative shadow-inner"
                >
                  {state.logoBase64 ? (
                    <img src={state.logoBase64} className="w-full h-full object-contain p-2" alt="Logo" />
                  ) : (
                    <>
                      <Upload className="w-5 h-5 text-slate-600" />
                      <span className="text-[8px] font-black text-slate-600 uppercase">Upload PNG/SVG</span>
                    </>
                  )}
                </div>
              </div>

              {/* Concept Text Section */}
              <div className="space-y-3">
                <label className="text-[9px] font-bold text-slate-500 uppercase flex items-center gap-2">
                  <ScrollText className="w-2.5 h-2.5" /> <span>Concept Tham Khảo</span>
                </label>
                <textarea 
                  value={state.conceptText}
                  onChange={(e) => setState(prev => ({ ...prev, conceptText: e.target.value }))}
                  placeholder="Mô tả phong cách thiết kế..."
                  className="w-full h-32 bg-slate-950 border border-white/10 rounded-xl p-3 text-[10px] text-white outline-none focus:border-indigo-500 resize-none placeholder:text-slate-700 shadow-inner"
                />
              </div>

              <div className="h-px bg-white/5 my-2"></div>

              <div className="space-y-2">
                <label className="text-[9px] font-bold text-slate-500 uppercase flex items-center gap-2"><Palette className="w-2 h-2" /> Accent Color</label>
                <div className="flex items-center gap-3 bg-slate-950 p-2 rounded-xl border border-white/10 shadow-inner">
                  <input type="color" value={state.accentColor} onChange={(e) => setState(prev => ({ ...prev, accentColor: e.target.value }))} className="w-8 h-8 bg-transparent cursor-pointer border-none rounded" />
                  <span className="text-[10px] font-mono font-black text-white">{state.accentColor.toUpperCase()}</span>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[9px] font-bold text-slate-500 uppercase flex items-center gap-2"><Layout className="w-2 h-2" /> Radius</label>
                <select value={state.borderRadius} onChange={(e) => setState(prev => ({ ...prev, borderRadius: e.target.value }))} className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-[10px] font-black text-white outline-none focus:border-indigo-500 cursor-pointer">
                  <option value="0px">SHARP (0px)</option>
                  <option value="0.75rem">SOFT (12px)</option>
                  <option value="1.5rem">ROUNDED (24px)</option>
                  <option value="9999px">PILL</option>
                </select>
              </div>

              <div className="space-y-2">
                <label className="text-[9px] font-bold text-slate-500 uppercase flex items-center gap-2"><Type className="w-2 h-2" /> Typography</label>
                <select value={state.fontFamily} onChange={(e) => setState(prev => ({ ...prev, fontFamily: e.target.value }))} className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-[10px] font-black text-white outline-none focus:border-indigo-500 cursor-pointer">
                  <option value="Inter">Inter</option>
                  <option value="Playfair Display">Playfair</option>
                  <option value="Fira Code">Fira Code</option>
                  <option value="Montserrat">Montserrat</option>
                </select>
              </div>
           </div>

           <div className="mt-8 p-4 bg-indigo-600/5 border border-indigo-500/20 rounded-2xl">
              <div className="flex items-center gap-2 mb-2">
                 <ShieldCheck className="w-3 h-3 text-emerald-400" />
                 <span className="text-[9px] font-black text-white uppercase tracking-tighter">Branding Sync</span>
              </div>
              <p className="text-[9px] text-slate-500 leading-relaxed italic">
                Lưu nhiều Branding Profile để chuyển đổi nhanh giữa các phong cách khác nhau cho dự án.
              </p>
           </div>
        </aside>
      </main>

      {isProcessing && (
        <div className="absolute inset-0 bg-slate-950/98 backdrop-blur-3xl z-[100] flex flex-col items-center justify-center p-10 text-center animate-in fade-in duration-700">
          <div className="relative mb-12">
            <div className="w-24 h-24 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            <Zap className="absolute inset-0 m-auto w-8 h-8 text-indigo-500 animate-pulse" />
          </div>
          <h2 className="text-4xl font-black text-white mb-4 tracking-tighter uppercase italic">Omni-Engine Crafting...</h2>
          <div className="flex items-center gap-2 text-slate-500 text-[10px] font-black uppercase tracking-[0.4em] animate-pulse">
            <Sparkles className="w-4 h-4 text-amber-500" /> Applying Branding Presets <Sparkles className="w-4 h-4 text-amber-500" />
          </div>
        </div>
      )}
    </div>
  );
}
